window.__DICT_CHUNKS__=window.__DICT_CHUNKS__||{};window.__DICT_CHUNKS__["I"]={"3492":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /aɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[used as the subject of a verb]</span></span></div><div class=\"entry-body\"><div class=\"sense\">used by the person speaking or writing to refer to himself or herself:</div><ul class=\"examples\"><li><em>I moved to this city six years ago.</em></li><li><em>I’m not late again, am I?</em></li><li><em>My husband and I enjoy going to the theatre.</em></li></ul></div>","3493":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ˌaɪ ˈiː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">written before a word or phrase that gives the exact meaning of something you have just written or said:</div><ul class=\"examples\"><li><em>The film is only open to adults, i.e. people over 18.</em></li></ul></div>","3494":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /aɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> water that has frozen into a solid state → icy:</div><ul class=\"examples\"><li><em>Would you like some ice in your drink?</em></li><li><em>Her hands were as cold as ice.</em></li><li><em>The city spent $7 million to remove snow and ice from the roads.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>keep/put something on ice</strong> to do nothing about a plan or suggestion for a period of time:</div><ul class=\"examples\"><li><em>I’m putting my plans for a new car on ice until I finish college.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be (skating) on thin ice</strong> to be in a situation in which you are likely to upset someone or cause trouble:</div><ul class=\"examples\"><li><em>Don’t be late again, Hugo – you’re skating on thin ice.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the ice</strong> a specially prepared surface of ice where you can ice-skate or play ice hockey:</div><ul class=\"examples\"><li><em>The two teams are ready to take to the ice.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a frozen sweet food made with fruit juice <em>SYN sorbet</em></div><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>especially British English</em> <em>old-fashioned</em> an ice cream</div><div class=\"sense\"><span class=\"snum\">6</span> <span class=\"gram\">[uncountable]</span> <em>American English</em> diamonds</div></div>","3495":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌice ˈcream</span><span class=\"meta-item\"><strong>IPA:</strong> / $ ˈ../</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> a frozen sweet food made of milk, cream, and sugar, with fruit, nuts, chocolate etc sometimes added to it:</div><ul class=\"examples\"><li><em>vanilla ice cream</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a small amount of this food for one person:</div><ul class=\"examples\"><li><em>Mummy, can I have an ice cream?</em></li></ul></div>","3496":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ice‧berg</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈaɪsbɜːɡ $ -bɜːrɡ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a very large mass of ice floating in the sea, most of which is under the surface of the water</div></div>","3497":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧con</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈaɪkɒn $ -kɑːn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a small sign or picture on a computer screen that is used to start a particular operation:</div><ul class=\"examples\"><li><em>To open a new file, click on the icon.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone famous who is admired by many people and is thought to represent an important idea:</div><ul class=\"examples\"><li><em>a sixties cultural icon</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> (also ikon) a picture or figure of a holy person that is used in worship in the Greek or Russian Orthodox Church</div></div>","3498":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ic‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈaɪsi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> extremely cold <em>SYN frosty</em>:</div><ul class=\"examples\"><li><em>an icy wind</em></li><li><em>The bath water was icy cold.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> covered in ice:</div><ul class=\"examples\"><li><em>an icy mountain road</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> an icy remark, look etc shows that you feel annoyed with or unfriendly towards someone:</div><ul class=\"examples\"><li><em>an icy stare</em></li></ul></div>","3499":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧dea</span><span class=\"meta-item\"><strong>IPA:</strong> /aɪˈdɪə/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[plan/suggestion]</strong> <span class=\"gram\">[countable]</span> a plan or suggestion for a possible course of action, especially one that you think of suddenly: ► Don’t say ‘the idea to do something’. Say the idea of doing something. However, you can say it is a good idea to do something and it was someone’s idea to do something.</div><ul class=\"examples\"><li><em>You should talk to Ken - he’s always full of good ideas.</em></li><li><em>I knew it was a bad idea to leave him on his own.</em></li><li><em>It was my wife’s idea to move house.</em></li><li><strong><em>idea for</strong>: The idea for the book came from an old war movie.</em></li><li><strong><em>the idea of doing something</strong>: I had the idea of asking Katie for help.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[knowledge]</strong> <span class=\"gram\">[countable, uncountable]</span> a general understanding of something, based on some knowledge about it:</div><ul class=\"examples\"><li><em>Could you give me an idea of how bad his injuries are?</em></li><li><em>You must have some idea (=have at least a little knowledge) of what happened to the money.</em></li><li><em>Don’t worry if you don’t understand it right now – you’ll get the idea (=begin to understand or be able to do something).</em></li><li><strong><em>have no idea/not have any idea</strong>: She doesn’t have any idea where they’ve gone.</em></li><li><strong><em>a general/rough idea</strong> (=a not very exact idea): Can you give me a rough idea of how much the repairs will cost?</em></li><li><strong><em>not have the faintest/slightest/foggiest idea<em>spoken</em></strong>: I don’t have the faintest idea what to get Rachel for her birthday.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[aim/intention]</strong> <span class=\"gram\">[countable, uncountable]</span> the aim, intention, or purpose of doing something:</div><ul class=\"examples\"><li><em>The idea is to teach children to save money.</em></li><li><strong><em>idea of/behind</strong>: The idea behind the outing is to encourage employees to get to know each other.</em></li><li><em>They wanted Mike to go to law school, but he had other ideas (=had different plans).</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[how you imagine something to be]</strong> <span class=\"gram\">[countable, uncountable]</span> an image in your mind of what something is like or should be like</div><ul class=\"examples\"><li><strong><em>idea of</strong>: Chefs differ in their idea of what makes a good dessert.</em></li><li><em>I only have a vague idea of the kind of work I’ll be doing.</em></li><li><em>It helps if you have a clear idea of what you want.</em></li><li><strong><em>not my idea of something</strong>: Chocolate milk and a piece of cake is not my idea of dinner.</em></li><li><em>The very idea of kissing him made her feel physically sick.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[belief/opinion]</strong> <span class=\"gram\">[countable usually plural]</span> someone’s opinion or belief about something</div><ul class=\"examples\"><li><strong><em>idea about</strong>: She had some rather unusual ideas about raising children.</em></li><li><strong><em>where did you get that idea?</strong> (=used to say that what someone thinks is completely wrong): No, I’m not seeing Jane. Where did you get that idea?</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[principle]</strong> <span class=\"gram\">[countable]</span> a principle or belief about how something is or should be</div><ul class=\"examples\"><li><strong><em>idea of</strong>: The whole idea of democracy was something strange and new to most people.</em></li><li><strong><em>idea that</strong>: It’s based on the idea that all people are created equal.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>have an idea (that)</strong> to be fairly sure that something is true, without being completely sure:</div><ul class=\"examples\"><li><em>I’m not sure where my necklace is, but I have a pretty good idea who took it.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>get the wrong idea</strong> to think that something is true when it is not:</div><ul class=\"examples\"><li><em>Don’t get the wrong idea about Dan and Helen – they’re just friends.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>have the right idea</strong> to act or think in a way that will probably lead to the correct result:</div><ul class=\"examples\"><li><em>He still makes a few mistakes but I reckon he’s got the right idea.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>that’s/there’s an idea</strong> <em>spoken</em> used to say that you like what someone has just suggested:</div><ul class=\"examples\"><li><em>‘Why don’t you invite Paula to come with us?’ ‘There’s an idea.’</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>that’s the idea</strong> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to tell someone who is learning to do something that they are doing it the right way, in order to encourage them:</div><ul class=\"examples\"><li><em>Keep your knees bent and lean forward slightly. That’s the idea!</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to emphasize what the main point of something is, or to say that someone understands that point:</div><ul class=\"examples\"><li><em>‘You’re thinking of getting a new job?’ ‘Yeah, that’s the idea.’</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>bright idea</strong> a very clever idea, often used in a joking way to mean a very stupid idea or action:</div><ul class=\"examples\"><li><em>Whose bright idea was it to leave the back door wide open?</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>give somebody ideas/put ideas into somebody’s head</strong> to make someone think of doing something that they had not thought of doing before, especially something that they should not do:</div><ul class=\"examples\"><li><em>Nick tells me he wants a motorbike. Have you been putting ideas into his head?</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>is it somebody’s idea of a joke?</strong> used when you are surprised and often rather annoyed by what someone has said or done:</div><ul class=\"examples\"><li><em>‘She wants you to do it by tomorrow.’ ‘Is that your idea of a joke?’</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>what’s the big idea?</strong> <em>spoken</em> used when you cannot understand why someone has done something</div><div class=\"sense\"><span class=\"snum\">16</span> <strong>you have no idea (how/what etc)</strong> <em>spoken</em> used when you are telling someone that something is extremely good, bad etc:</div><ul class=\"examples\"><li><em>You have no idea how worried I was.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>the idea!</strong> <em>old-fashioned</em> <em>spoken</em> used to express surprise or disapproval when someone has said something stupid</div></div>","3500":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧deal</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌaɪˈdɪəl◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the best or most suitable that something could possibly be <em>SYN perfect</em>:</div><ul class=\"examples\"><li><em>advice on how to reach your ideal weight</em></li><li><em>The scheme offers an ideal opportunity for youngsters to get training.</em></li><li><em>With so much rain, conditions are far from ideal.</em></li><li><strong><em>ideal for</strong>: An elastic waist makes these jeans ideal for the larger woman.</em></li><li><em>an ideal place for a walk</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[only before noun]</span> an ideal world, job, system etc is one that you imagine to be perfect, but that is not likely to really exist <em>SYN perfect</em>:</div><ul class=\"examples\"><li><em>In an ideal world there would be no need for a police force.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a principle about what is morally right or a perfect standard that you hope to achieve</div><ul class=\"examples\"><li><strong><em>ideal of</strong>: the ideal of a free and democratic society</em></li><li><em>the long-vanished ideals of the 1950s</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a perfect example of what something should be like</div><ul class=\"examples\"><li><strong><em>ideal of</strong>: Are our ideals of beauty changing?</em></li></ul></div></div>","3501":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧deal‧is‧tic</span><span class=\"meta-item\"><strong>IPA:</strong> /aɪˌdɪəˈlɪstɪk◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">believing that you should live according to high standards and principles, even if they cannot really be achieved, or showing this belief → realistic:</div><ul class=\"examples\"><li><em>idealistic young doctors</em></li><li><em>the idealistic values of the 1960s</em></li></ul></div>","3502":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧deal‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /aɪˈdɪəli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to describe the way you would like things to be, even though this may not be possible</div><ul class=\"examples\"><li><em><span class=\"gram\">[sentence adverb]</span>: Ideally, your car should have high-security locks.</em></li><li><em>Fruit and vegetables should ideally be organically grown.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>ideally suited/placed/situated etc</strong> having the best qualities, experience, knowledge etc for a particular situation:</div><ul class=\"examples\"><li><em>He was ideally suited for the job.</em></li><li><em>The hotel is ideally located for enjoying the beauty of Yorkshire.</em></li></ul></div>","3503":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧den‧ti‧cal</span><span class=\"meta-item\"><strong>IPA:</strong> /aɪˈdentɪkəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">exactly the same, or very similar: ► see thesaurus at same, similar</div><ul class=\"examples\"><li><em>four identical houses</em></li><li><strong><em>identical to/with</strong>: Nutritionally, infant formulas are almost identical to breast milk. / The ingredients are identical with those of competing products.</em></li><li><strong><em>identical in</strong>: The sisters were identical in appearance and character.</em></li></ul></div>","3504":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧den‧ti‧fi‧a‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /aɪˈdentəfaɪəbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">able to be recognized</div><ul class=\"examples\"><li><strong><em>identifiable as</strong>: She looked young, and was immediately identifiable as a trainee.</em></li><li><strong><em>identifiable by</strong>: The police were identifiable by their uniform.</em></li></ul></div>","3505":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧den‧ti‧fi‧ca‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /aɪˌdentɪfɪˈkeɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> (abbreviation ID) official papers or cards, such as your passport, that prove who you are:</div><ul class=\"examples\"><li><em>Do you have any identification?</em></li><li><strong><em>form/proof of identification</strong>: Bring some form of identification, preferably a passport.</em></li><li><em>fingerprinting as a means of identification</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> when someone says officially that they know who someone else is, especially a criminal or a dead person:</div><ul class=\"examples\"><li><em>His body was taken to Brighton mortuary for identification.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> when you recognize something or discover exactly what it is</div><ul class=\"examples\"><li><strong><em>identification of</strong>: the identification of customer needs / the identification of children who need professional help</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> the act of saying that two things are very closely related</div><ul class=\"examples\"><li><strong><em>identification of something with something</strong>: the identification of sexism with women’s oppression</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> a strong feeling of sympathy with someone that makes you able to share their feelings</div><ul class=\"examples\"><li><strong><em>identification with</strong>: my identification with the heroine of the book</em></li></ul></div>","3506":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧den‧ti‧fy</span><span class=\"meta-item\"><strong>IPA:</strong> /aɪˈdentɪfaɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W1 AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle identified, present participle identifying, third person singular identifies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to recognize and correctly name someone or something: ► see thesaurus at recognize</div><ul class=\"examples\"><li><em>He was too far away to be able to identify faces.</em></li><li><em>The police took fingerprints and identified the body.</em></li><li><strong><em>identify somebody/something as somebody/something</strong>: Eyewitnesses identified the gunman as an army sergeant. / The aircraft were identified as American.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to recognize something or discover exactly what it is, what its nature or origin is etc:</div><ul class=\"examples\"><li><em>Scientists have identified the gene that causes abnormal growth.</em></li><li><em>They identified a number of problem areas.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> if a particular thing identifies someone or something, it makes them easy to recognize</div><ul class=\"examples\"><li><strong><em>identify somebody as somebody</strong>: His accent identified him as a Frenchman.</em></li></ul></div>","3507":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧den‧ti‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /aɪˈdentəti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2 AWL</span><span class=\"meta-item\">(plural identities)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> someone’s identity is their name or who they are:</div><ul class=\"examples\"><li><em>The identity of the killer is still unknown.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the qualities and attitudes that a person or group of people have, that make them different from other people:</div><ul class=\"examples\"><li><em>Children need continuity, security, and a sense of identity.</em></li><li><em>Travelling alone can lead to a loss of identity.</em></li><li><strong><em>national/cultural/social etc identity</strong> (=a strong feeling of belonging to a particular group, race etc): Our strong sense of national identity has been shaped by our history.</em></li><li><strong><em>identity crisis/crisis of identity</strong> (=a feeling of uncertainty about who you really are and what your purpose is): My father experienced an identity crisis in middle age.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> <em>formal</em> exact similarity between two things</div></div>","3508":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧de‧o‧lo‧gic‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌaɪdiəˈlɒdʒɪkəl◂ $ -ˈlɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">based on strong beliefs or ideas, especially political or economic ideas:</div><ul class=\"examples\"><li><em>The party is split by ideological differences.</em></li></ul></div>","3509":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧de‧ol‧o‧gy</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌaɪdiˈɒlədʒi $ -ˈɑːl-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span><span class=\"meta-item\">(plural ideologies)</span></div><div class=\"entry-body\"><div class=\"sense\">a set of beliefs on which a political or economic system is based, or which strongly influence the way people behave → philosophy:</div><ul class=\"examples\"><li><em>the ideologies of fascism and communism</em></li><li><em>a new ideology based on individualism</em></li></ul></div>","3510":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> id‧i‧om</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪdiəm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a group of words that has a special meaning that is different from the ordinary meaning of each separate word. For example, ‘under the weather’ is an idiom meaning ‘ill’. ► see thesaurus at phrase, word</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> <em>formal</em> or <em>technical</em> a style of expression in writing, speech, or music that is typical of a particular group of people:</div><ul class=\"examples\"><li><em>the new musical idiom</em></li></ul></div>","3511":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> id‧i‧o‧mat‧ic</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪdiəˈmætɪk◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>idiomatic expression/phrase</strong> an idiom</div><div class=\"sense\"><span class=\"snum\">2</span> typical of the natural way in which someone speaks or writes when they are using their own language:</div><ul class=\"examples\"><li><em>He had the ability to write fluent and idiomatic English.</em></li><li><em>the idiomatic richness of the Spanish language</em></li></ul></div>","3512":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> id‧i‧ot</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪdiət/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a stupid person or someone who has done something stupid:</div><ul class=\"examples\"><li><em>It was all your fault, you idiot.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>old use</em> someone who is mentally ill or has a very low level of intelligence</div></div>","3513":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i·dle</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈaɪdl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not working or producing anything <em>OPP busy</em>:</div><ul class=\"examples\"><li><em>I cannot afford to leave the land lying idle.</em></li><li><em>The whole team stood idle, waiting for the mechanic.</em></li><li><em>The workers have been idle for the last six months.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> not serious, or not done with any definite intention:</div><ul class=\"examples\"><li><em>She was not a woman to make idle threats.</em></li><li><strong><em>idle chatter/talk/gossip etc</em></strong></li><li><em>It was only from idle curiosity that she went into the barn.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> lazy: RegisterIdle sounds rather old-fashioned and literary. In everyday English, people usually say lazy:· She&#x27;s not stupid, just lazy.</div><ul class=\"examples\"><li><em>Go and wake up that idle brother of yours.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>it is idle to do something</strong> it is not worth doing something, because nothing will be achieved:</div><ul class=\"examples\"><li><em>It would be idle to deny that progress was made.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>the idle rich</strong> rich people who do not have to work</div></div>","3514":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧dol</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈaɪdl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone or something that you love or admire very much <em>SYN hero</em></div><ul class=\"examples\"><li><strong><em>idol of</strong>: She is the idol of countless teenagers.</em></li><li><em>She had made an idol of her husband.</em></li><li><em>a pop idol</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a picture or statue that is worshipped as a god → effigy</div></div>","3515":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ɪf/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used when talking about something that might happen or be true, or might have happened:</div><ul class=\"examples\"><li><em>We’ll stay at home if it rains.</em></li><li><em>If you need money, I can lend you some.</em></li><li><em>If I didn’t apologize, I’d feel guilty.</em></li><li><em>If you had worked harder, you would have passed your exams.</em></li><li><em>What would happen to your family if you were to die in an accident?</em></li><li><em>If Dad were here, he would know what to do.</em></li><li><em>Taste the soup and add salt and pepper if necessary.</em></li><li><em>I want to get back by five o’clock if possible.</em></li><li><em>I think I can fix it tomorrow. If not, you’ll have to wait till Friday.</em></li><li><em>Is the book available, and if so, where?</em></li><li><em>The missiles can be fired only if the operator types in a six-digit code.</em></li><li><em>We’ll face that problem if and when it comes along (=if it happens or when it happens).</em></li><li><em>If by any chance you can’t manage dinner tonight, perhaps we can at least have a drink together.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to mention a fact, situation, or event that someone asks about, or is not certain about:</div><ul class=\"examples\"><li><em>He stopped to ask me if I was all right.</em></li><li><em>I don’t know if what I am saying makes any sense.</em></li><li><em>I doubt if anyone will remember me.</em></li><li><em>I’m not sure if this is the right road or not.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to mention a type of event or situation when talking about what happens on occasions of that type:</div><ul class=\"examples\"><li><em>If I go to bed late, I feel dreadful in the morning.</em></li><li><em>Plastic will melt if it gets too hot.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> used when saying what someone’s feelings are about a possible situation:</div><ul class=\"examples\"><li><em>You don’t seem to care if I’m tired.</em></li><li><em>I’m sorry if I upset you.</em></li><li><em>It would be nice if we could spend more time together.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <em>spoken</em> used when making a polite request:</div><ul class=\"examples\"><li><em>I wonder if you could help me.</em></li><li><em>I’d be grateful if you would send me further details.</em></li><li><em>Would you mind if I open a window?</em></li><li><em>If you would just wait for a moment, I’ll try to find your papers.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> used when you are adding that something may be even more, less, better, worse etc than you have just said:</div><ul class=\"examples\"><li><em>Brian rarely, if ever, goes to bed before 3 am.</em></li><li><em>Their policies have changed little, if at all, since the last election.</em></li><li><em>Her needs are just as important as yours, if not more so.</em></li><li><em>The snow was now two feet deep, making it difficult, if not impossible, to get the car out.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>even if</strong> used to emphasize that, although something may happen or may be true, it will not change a situation:</div><ul class=\"examples\"><li><em>I wouldn’t tell you even if I knew.</em></li><li><em>Even if she survives, she’ll never fully recover.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>if anything</strong> used when adding a remark that changes what you have just said or makes it stronger:</div><ul class=\"examples\"><li><em>It’s warm enough here in London. A little too warm, if anything.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <em>spoken</em> used during a conversation when you are trying to make a suggestion, change the subject, or interrupt someone else:</div><ul class=\"examples\"><li><em>If I might just make a suggestion, I think that the matter could be easily settled with a little practical demonstration.</em></li><li><em>If I could just take one example to illustrate this.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>if I were you</strong> <em>spoken</em> used when giving advice and telling someone what you think they should do:</div><ul class=\"examples\"><li><em>I wouldn’t worry about it if I were you.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>if only</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to express a strong wish, especially when you know that what you want cannot happen:</div><ul class=\"examples\"><li><em>If only he had talked to her sooner!</em></li><li><em>If only I weren’t so tired!</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to give a reason for something, although you think it is not a good one:</div><ul class=\"examples\"><li><em>Media studies is regarded as a more exciting subject, if only because it’s new.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> used to say that, although something may be true, it is not important:</div><ul class=\"examples\"><li><em>If he has a fault at all, it is that he is too generous.</em></li><li><em>Her only problem, if you can call it a problem, is that she expects to be successful all the time.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> used when adding one criticism of a person or thing that you generally like:</div><ul class=\"examples\"><li><em>The eldest son was highly intelligent, if somewhat lazy.</em></li><li><em>Lunch was a grand if rather noisy affair.</em></li></ul></div>","3516":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ig‧no‧rance</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪɡnərəns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> lack of knowledge or information about something:</div><ul class=\"examples\"><li><em>Excuse my ignorance, but how does it actually work?</em></li><li><strong><em>ignorance of</strong>: our ignorance of the true situation</em></li><li><strong><em>in ignorance</strong>: I would have remained in ignorance if Shaun hadn’t mentioned it.</em></li><li><strong><em>ignorance about</strong>: public fear and ignorance about AIDS</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>ignorance is bliss</strong> used to say that if you do not know about a problem, you cannot worry about it</div></div>","3517":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ig‧no‧rant</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪɡnərənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not knowing facts or information that you ought to know:</div><ul class=\"examples\"><li><em>an ignorant and uneducated man</em></li><li><strong><em>ignorant of</strong>: Political historians are often rather ignorant of economics.</em></li><li><strong><em>ignorant about</strong>: Many people remain blissfully ignorant about the dangers of too much sun (=happy because they do not know about the dangers).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> caused by a lack of knowledge and understanding:</div><ul class=\"examples\"><li><em>an ignorant remark</em></li><li><em>ignorant opinions</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>British English</em> <em>spoken</em> rude or impolite:</div><ul class=\"examples\"><li><em>ignorant behaviour</em></li></ul></div>","3518":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ig‧nore</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪɡˈnɔː $ -ˈnɔːr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2 AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to deliberately pay no attention to something that you have been told or that you know about:</div><ul class=\"examples\"><li><em>You can’t ignore the fact that many criminals never go to prison.</em></li><li><em>problems which we can’t afford to ignore</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to behave as if you had not heard or seen someone or something: RegisterIn everyday British English, people often say take no notice of something or not take any notice of something rather than ignore something:· There are signs telling you not to smoke, but people don’t take any notice of them.</div><ul class=\"examples\"><li><em>The phone rang, but she ignored it.</em></li><li><em>Sam rudely ignored the question.</em></li><li><strong><em>completely/totally ignore somebody/something</strong>: He had completely ignored her remark, preferring his own theory.</em></li></ul></div>","3519":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ɪl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>especially British English</em> suffering from a disease or not feeling well SYN sick<em>American English</em>:</div><ul class=\"examples\"><li><em>Bridget can’t come – she’s ill.</em></li><li><em>I was feeling ill that day and decided to stay at home.</em></li><li><strong><em>ill with</strong>: Her husband has been ill with bladder trouble.</em></li><li><em>a hospice for the terminally ill</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[only before noun]</span> bad or harmful:</div><ul class=\"examples\"><li><em>Many people consumed the poisoned oil without ill effects.</em></li><li><em>the neglect and ill treatment of children</em></li><li><em>He was unable to join the army because of ill health.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>ill at ease</strong> nervous, uncomfortable, or embarrassed:</div><ul class=\"examples\"><li><em>He always felt shy and ill at ease at parties.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>it’s an ill wind (that blows nobody any good)</strong> <em>spoken</em> used to say that every problem brings an advantage for someone</div></div>","3520":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> il‧le‧gal</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪˈliːɡəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\">not allowed by the law <em>SYN unlawful</em> <em>OPP legal</em>: RegisterIn everyday English, people often say that something is against the law rather than illegal:· It is against the law to have a gun without a licence.</div><ul class=\"examples\"><li><em>illegal drugs</em></li><li><em>They were involved in illegal activities.</em></li><li><strong><em>it is illegal to do something</strong>: It is illegal to sell tobacco to someone under 16.</em></li></ul></div>","3521":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> il‧li‧cit</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪˈlɪsɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">not allowed by laws or rules, or strongly disapproved of by society → illegal:</div><ul class=\"examples\"><li><em>illicit drugs</em></li><li><em>the illicit trade in stolen cattle</em></li></ul></div>","3522":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ill‧ness</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪlnəs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a disease of the body or mind, or the condition of being ill:</div><ul class=\"examples\"><li><em>She had all the normal childhood illnesses.</em></li><li><em>Her mother was recovering from a serious illness.</em></li><li><em>I’ve never missed a day’s work through illness.</em></li><li><em>ways to improve your health and reduce the risk of illness</em></li></ul></div>","3523":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> il‧lu‧mi‧nate</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪˈluːməneɪt, ɪˈljuː- $ ɪˈluː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to make a light shine on something, or to fill a place with light:</div><ul class=\"examples\"><li><em>A single candle illuminated his face.</em></li><li><em>At night the canals are beautifully illuminated.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>formal</em> to make something much clearer and easier to understand:</div><ul class=\"examples\"><li><em>The report illuminated the difficult issues at the heart of science policy.</em></li></ul></div>","3524":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> il‧lu‧sion</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪˈluːʒən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an idea or opinion that is wrong, especially about yourself → delusion</div><ul class=\"examples\"><li><strong><em>illusion that</strong>: They suffer from the illusion that they cannot solve their problems.</em></li><li><em>She was under no illusion that he loved her.</em></li><li><em>It is an illusion that the Arctic is dark in winter.</em></li><li><em>She had no illusions about her physical attractiveness.</em></li><li><em>‘I hate to shatter your illusions,’ he said.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> something that seems to be different from the way it really is</div><ul class=\"examples\"><li><strong><em>illusion of</strong>: He was unlikely to be satisfied with the illusion of power.</em></li><li><strong><em>give/create an illusion</strong>: The mirrors in the room gave an illusion of greater space.</em></li><li><em>Credit creates the illusion that you can own things without paying for them.</em></li></ul></div>","3525":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> il‧lus‧trate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪləstreɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to make the meaning of something clearer by giving examples:</div><ul class=\"examples\"><li><em>Let me give an example to illustrate the point.</em></li><li><em>She illustrated her discussion with diagrams.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to be an example which shows that something is true or that a fact exists</div><ul class=\"examples\"><li><strong><em>illustrate that</strong>: This dispute illustrates that the regime is deeply divided.</em></li><li><strong><em>illustrate how</strong>: The following examples illustrate how this operates in practice.</em></li><li><em>This illustrates a fundamental weakness in the system.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to put pictures in a book, article etc: ► see thesaurus at draw</div><ul class=\"examples\"><li><em>Over a hundred diagrams, tables and pictures illustrate the book.</em></li></ul></div>","3526":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> il‧lus‧tra‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪləˈstreɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a picture in a book, article etc, especially one that helps you to understand it:</div><ul class=\"examples\"><li><em>The book contains 62 pages of illustrations.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> a story, event, action etc that shows the truth or existence of something very clearly ► see thesaurus at example</div><ul class=\"examples\"><li><strong><em>illustration of</strong>: a striking illustration of 19th-century attitudes to women</em></li><li><em>For the purposes of illustration, some of the more important symptoms are listed below.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> the act or process of illustrating something</div></div>","3527":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧age</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪmɪdʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[public opinion]</strong> the opinion people have of a person, organization, product etc, or the way a person, organization etc seems to be to the public → reputation ► see thesaurus at reputation</div><ul class=\"examples\"><li><strong><em>image of</strong>: attempts to improve the image of the police</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[idea in mind]</strong> a picture that you have in your mind, especially about what someone or something is like or the way they look</div><ul class=\"examples\"><li><strong><em>image of</strong>: He had no visual image of her, only her name.</em></li><li><em>He had the clearest image in his mind of his mother and father.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[picture/what you see]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a picture of an object in a mirror or in the lens of a camera:</div><ul class=\"examples\"><li><em>She peered closely at her image in the mirror.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> a picture on the screen of a television, cinema, or computer:</div><ul class=\"examples\"><li><em>Jill Sharpe was little more than a name, a glossy image on a television screen.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> a picture or shape of a person or thing that is copied onto paper or is cut in wood or stone:</div><ul class=\"examples\"><li><em>carved images</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[description]</strong> a word, phrase, or picture that describes an idea in a poem, book, film etc:</div><ul class=\"examples\"><li><em>He paints a very romantic image of working-class communities.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be the (very/living/spitting) image of somebody</strong> to look exactly like someone or something else:</div><ul class=\"examples\"><li><em>He’s the spitting image of his mother.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>in the image of somebody/something</strong> <em>literary</em> in the same form or shape as someone or something else:</div><ul class=\"examples\"><li><em>According to the Bible, man was made in the image of God.</em></li></ul></div>","3528":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧ag‧e‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪmɪdʒəri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the use of words or pictures to describe ideas or actions in poems, books, films etc ► see thesaurus at language</div><ul class=\"examples\"><li><strong><em>imagery of</strong>: the imagery of love</em></li><li><em>Their dreams commonly involved complex stories with visual imagery.</em></li></ul></div>","3529":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧ma‧gi‧na‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪˈmædʒənəri $ -neri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">not real, but produced from pictures or ideas in your mind → fictional:</div><ul class=\"examples\"><li><em>As she listened, she played an imaginary piano on her knees.</em></li><li><em>We must protect older people from harm, whether it is real or imaginary.</em></li></ul></div>","3530":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧ma‧gi‧na‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪˌmædʒəˈneɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the ability to form pictures or ideas in your mind:</div><ul class=\"examples\"><li><em>a storyteller with an incredible imagination</em></li><li><em>It does not take much imagination to understand their grief.</em></li><li><em>With a little imagination, you can find great inexpensive gifts.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be (a figment of) somebody’s imagination</strong> to be something that someone imagines, not something that really exists or happens:</div><ul class=\"examples\"><li><em>Did you hear that noise, or was it my imagination?</em></li><li><em>These people do exist; they’re not figments of my imagination.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>in somebody’s imagination</strong> only existing or happening in someone’s mind, not in real life:</div><ul class=\"examples\"><li><em>For the refugees, home exists only in their imagination.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>capture/catch somebody’s imagination</strong> to make people feel very interested and excited:</div><ul class=\"examples\"><li><em>American football really captured the imagination of the British public.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>leave something to somebody’s imagination</strong> to deliberately not describe something because you think someone can guess or imagine it:</div><ul class=\"examples\"><li><em>Mercifully, the writer leaves most of the physical horrors to our imagination.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>leave little/nothing to the imagination</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if someone’s clothes leave little or nothing to the imagination, the clothes are very thin or are worn in a way that shows the person’s body:</div><ul class=\"examples\"><li><em>Her black satin dress left nothing to the imagination.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if something sexual or violent is described in a way that leaves nothing to the imagination, it is described in too much detail</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>use your imagination</strong> <em>spoken</em> used to tell someone that they can easily guess the answer to a question, so you should not need to tell them</div></div>","3531":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧ma‧gi‧na‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪˈmædʒənətɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> containing new and interesting ideas:</div><ul class=\"examples\"><li><em>an imaginative use of computer technology</em></li><li><em>children’s imaginative play</em></li><li><em>an imaginative solution to the litter problem</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> good at thinking of new and interesting ideas:</div><ul class=\"examples\"><li><em>an imaginative child</em></li></ul></div>","3532":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧ma‧gine</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪˈmædʒɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to form a picture or idea in your mind about what something could be like GRAMMARImagine is followed by an -ing form, not an infinitive. You say: · I can’t imagine living without music. ✗Don’t say: I can’t imagine to live without music.Grammar guide ‒ VERBS</div><ul class=\"examples\"><li><strong><em>imagine (that)</strong>: Imagine that you have just won a million pounds.</em></li><li><em>Imagine life without hot water.</em></li><li><strong><em>imagine what/how/why etc</strong>: Can you imagine what it’s like when it’s really hot out here in Delhi?</em></li><li><strong><em>imagine somebody doing something</strong>: She could imagine dark-robed figures moving silently along the stone corridors.</em></li><li><strong><em>(just) imagine doing something</strong>: Imagine doing a horrible job like that! / Just imagine going all that way for nothing!</em></li><li><strong><em>imagine somebody/something as something</strong>: He didn’t quite dare to imagine himself as a real artist.</em></li><li><strong><em>imagine somebody in/with/without etc something</strong>: Somehow, I can’t imagine him without a beard.</em></li><li><strong><em>it’s difficult/easy/possible/impossible etc to imagine something</strong>: After such a dry summer, it’s difficult to imagine what rain looks like.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to have a false or wrong idea about something:</div><ul class=\"examples\"><li><em>Perhaps she’d never really been there at all – perhaps she’d just imagined it.</em></li><li><em>imagined dangers</em></li><li><strong><em>imagine (that)</strong>: She had imagined that the doctor would be male. / I was surprised when I saw the farm. I had imagined it would be much bigger.</em></li><li><strong><em>imagine something/somebody to be something</strong>: There’s nobody here. You’re just imagining things.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[not in progressive]</span> to think that something is true or may happen, but without being sure or having proof:</div><ul class=\"examples\"><li><em>‘A very complicated subject, I imagine,’ said Edwin.</em></li><li><strong><em>imagine (that)</strong>: You are obviously tired and I imagine that nothing would make you admit it.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>you can/can’t imagine something</strong> <em>British English</em> <em>spoken</em> used to emphasize how good, bad etc something is</div><ul class=\"examples\"><li><strong><em>You can/can’t imagine how/what/why etc</strong>: You can imagine how angry I was! / You can’t imagine what a terrible week we had.</em></li></ul></div>","3533":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧bal‧ance</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪmˈbæləns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a lack of a fair or correct balance between two things, which results in problems or unfairness <em>SYN inequality</em></div><ul class=\"examples\"><li><strong><em>imbalance in</strong>: The government must redress the imbalance (=put it right) in spending on black and white children.</em></li><li><strong><em>imbalance between</strong>: the current imbalance between farming and conservation interests</em></li><li><em>a hormonal imbalance</em></li></ul></div>","3534":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧i‧tate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪmɪteɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to copy the way someone behaves, speaks, moves etc, especially in order to make people laugh: ► Do not use imitate to mean ‘do the same thing as someone else’. Use copy: She worries that Tom will copy his brother (NOT imitate his brother) and leave home.</div><ul class=\"examples\"><li><em>She was a splendid mimic and loved to imitate Winston Churchill.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to copy something because you think it is good:</div><ul class=\"examples\"><li><em>vegetarian products which imitate meat</em></li><li><em>The Japanese have no wish to imitate Western social customs and attitudes.</em></li></ul></div>","3535":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧i‧ta‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪmɪˈteɪʃən◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> when you copy someone else’s actions</div><ul class=\"examples\"><li><strong><em>by imitation</strong>: Many people think that children learn language by imitation.</em></li><li><em>The remake of ‘Casablanca’ was a pale imitation (=something that is much less good than the thing it imitates) of the original movie.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> when you copy the way someone speaks or behaves, especially in order to be funny <em>SYN impression</em>:</div><ul class=\"examples\"><li><em>She acted, she danced, she did imitations.</em></li><li><strong><em>imitation of</strong>: his imitation of an American accent</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a copy of something ► see thesaurus at artificial, false</div><ul class=\"examples\"><li><strong><em>imitation of</strong>: She wore an imitation of a sailor’s hat.</em></li><li><strong><em>imitation fur/pearls/silk/leather etc</strong> (=something that looks like an expensive material but is a copy of it): an imitation fur coat</em></li></ul></div>","3536":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧mac‧u‧late</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪˈmækjələt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> very clean and tidy <em>OPP messy</em>: ► see thesaurus at clean, tidy</div><ul class=\"examples\"><li><em>He wore an immaculate dark blue suit.</em></li><li><em>an immaculate kitchen</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> exactly correct or perfect in every detail <em>SYN flawless</em>:</div><ul class=\"examples\"><li><em>her immaculate stage performances</em></li></ul></div>","3537":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧ma‧ture</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪməˈtʃʊə $ -ˈtʃʊr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who is immature behaves or thinks in a way that is typical of someone much younger – used to show disapproval <em>SYN childish</em> <em>OPP mature</em>:</div><ul class=\"examples\"><li><em>He forgave his son’s immature behaviour.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> not fully formed or developed:</div><ul class=\"examples\"><li><em>measures to protect immature whales</em></li></ul></div>","3538":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧me‧di‧ate</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪˈmiːdiət/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> happening or done at once and without delay:</div><ul class=\"examples\"><li><em>Our immediate response to the attack was sheer horror.</em></li><li><em>They promise immediate action to help the unemployed.</em></li><li><em>If the eyes are affected, seek immediate medical attention.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[only before noun]</span> existing now, and needing to be dealt with quickly:</div><ul class=\"examples\"><li><em>Let’s try and solve the most immediate problem.</em></li><li><em>There is an immediate danger of war.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[only before noun]</span> happening just before or just after someone or something else:</div><ul class=\"examples\"><li><em>The most immediate effect of retirement is a dramatic reduction in living standards.</em></li><li><em>He promised that there would be no tax increases in the immediate future.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[only before noun]</span> next to, or very near to, a particular place:</div><ul class=\"examples\"><li><em>It is a thriving shopping centre for the people who live in the immediate area.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>immediate family</strong> people who are very closely related to you, such as your parents, children, brothers, and sisters</div></div>","3539":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧me‧di‧ate‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪˈmiːdiətli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> without delay <em>SYN at once</em>: RegisterIn everyday English, people usually say right away or, in British English, straight away rather than immediately:· Yes, I’ll do it right away.</div><ul class=\"examples\"><li><em>Mix in the remaining ingredients and serve immediately.</em></li><li><em>The telephone rang, and he answered it immediately.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> very soon before or after something</div><ul class=\"examples\"><li><strong><em>immediately after/following something</strong>: He retired immediately after the end of the war.</em></li><li><strong><em>immediately before/preceding something</strong>: I can’t remember what happened immediately before the crash.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>immediately obvious/apparent</strong> able to be seen or understood very easily:</div><ul class=\"examples\"><li><em>The solution to this problem is not immediately obvious.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[+adjective/adverb]</span> very near to something</div><ul class=\"examples\"><li><strong><em>immediately behind/above/below/in front of etc something</strong>: the seat immediately behind the driver</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>immediately involved/affected/concerned etc</strong> very closely involved etc in a particular situation:</div><ul class=\"examples\"><li><em>Those most immediately involved in the disaster will be given support.</em></li></ul></div>","3540":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧mense</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪˈmens/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">extremely large <em>SYN enormous</em>:</div><ul class=\"examples\"><li><em>People who travel by rail still read an immense amount.</em></li><li><em>Regular visits from a social worker can be of immense value to old people living alone.</em></li></ul></div>","3541":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧mense‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪˈmensli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">very much <em>SYN extremely</em>:</div><ul class=\"examples\"><li><em>Champagne wines became immensely popular in the 18th century.</em></li><li><strong><em>immensely powerful/strong/important etc</strong>: Nationalism is an immensely powerful force.</em></li><li><em>We enjoyed the play immensely.</em></li></ul></div>","3542":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧mi‧grant</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪməɡrənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who enters another country to live there permanently → emigrant:</div><ul class=\"examples\"><li><em>an illegal immigrant</em></li><li><em>a new wave of immigrants from the Middle East</em></li></ul></div>","3543":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧mi‧grate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪmɪɡreɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to come into a country in order to live there permanently → emigrate, migrate:</div><ul class=\"examples\"><li><em>His father and mother immigrated when he was two.</em></li></ul></div>","3544":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧mi‧gra‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪmɪˈɡreɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the process of entering another country in order to live there permanently → emigration:</div><ul class=\"examples\"><li><em>He called for a common European policy on immigration.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the total number of people who immigrate:</div><ul class=\"examples\"><li><em>Immigration fell in the 1980s.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> (also immigration control) the place at an airport, sea port etc where officials check the documents of everyone entering the country</div></div>","3545":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧mi‧nent</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪmɪnənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">an event that is imminent, especially an unpleasant one, will happen very soon</div><ul class=\"examples\"><li><strong><em>imminent danger/threat/death/disaster etc</strong>: He was in imminent danger of dying.</em></li><li><em>A new trade agreement is imminent.</em></li></ul></div>","3546":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧mune</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪˈmjuːn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[not before noun]</span> someone who is immune to a particular disease cannot catch it:</div><ul class=\"examples\"><li><em>Once we’ve had the disease, we’re immune for life.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>immune response/reaction</strong> the reaction of the body’s immune system to something that is harmful:</div><ul class=\"examples\"><li><em>HIV is a progressive disease which the immune response ultimately fails to control.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[not before noun]</span> not affected by something that happens or is done</div><ul class=\"examples\"><li><strong><em>immune to</strong>: The Labour Party is not immune to new ideas.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[not before noun]</span> specially protected from something unpleasant</div><ul class=\"examples\"><li><strong><em>immune from</strong>: The senior members of the group appeared to be immune from arrest.</em></li></ul></div>","3547":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧mu‧ni‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪˈmjuːnəti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the state or right of being protected from particular laws or from unpleasant things</div><ul class=\"examples\"><li><strong><em>immunity from</strong>: They were granted immunity from prosecution.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the state of being immune to a disease</div><ul class=\"examples\"><li><strong><em>immunity to</strong>: immunity to infection</em></li><li><strong><em>immunity from</strong>: immunity from smallpox</em></li></ul></div>","3548":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧pact</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪmpækt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> the effect or influence that an event, situation etc has on someone or something ► Don’t say ‘cause an impact’ on something. Say have an impact on something. ► see thesaurus at effect</div><ul class=\"examples\"><li><strong><em>impact on/upon</strong>: We need to assess the impact on climate change.</em></li><li><strong><em>major/significant/profound etc impact</strong>: Higher mortgage rates have already had a major impact on spending.</em></li><li><strong><em>impact of</strong>: an international meeting to consider the environmental impacts of global warming</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> the force of one object hitting another:</div><ul class=\"examples\"><li><em>The force of the impact knocked the breath out of her.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>on impact</strong> at the moment when one thing hits another:</div><ul class=\"examples\"><li><em>The plane’s wing was damaged on impact.</em></li></ul></div>","3549":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧pair</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪmˈpeə $ -ˈper/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to damage something or make it not as good as it should be: ► see thesaurus at harm</div><ul class=\"examples\"><li><em>The illness had impaired his ability to think and concentrate.</em></li></ul></div>","3550":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧par‧tial</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪmˈpɑːʃəl $ -ɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">not involved in a particular situation, and therefore able to give a fair opinion or piece of advice <em>SYN fair</em> <em>OPP biased</em>:</div><ul class=\"examples\"><li><em>We offer impartial advice on tax and insurance.</em></li><li><em>an impartial inquiry into the deaths</em></li><li><em>an impartial observer</em></li></ul></div>","3551":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧pa‧tient</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪmˈpeɪʃənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> annoyed because of delays, someone else’s mistakes etc <em>OPP patient</em></div><ul class=\"examples\"><li><strong><em>become/grow impatient (with somebody/something)</strong>: We are growing impatient with the lack of results.</em></li><li><em>He turned away with an impatient gesture.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[not before noun]</span> very eager for something to happen and not wanting to wait</div><ul class=\"examples\"><li><strong><em>impatient to do something</strong>: Alec strode down the street, impatient to be home.</em></li><li><strong><em>impatient for somebody to do something</strong>: He was eager to talk to Shildon and impatient for him to return from lunch.</em></li></ul></div>","3552":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧per‧fect</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪmˈpɜːfɪkt $ -ɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">not completely correct or perfect <em>SYN flawed</em>:</div><ul class=\"examples\"><li><em>the imperfect world we live in</em></li></ul></div>","3553":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧pe‧tus</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪmpɪtəs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an influence that makes something happen or makes it happen more quickly</div><ul class=\"examples\"><li><strong><em>impetus for</strong>: The report may provide further impetus for reform.</em></li><li><em>The discovery gave fresh impetus to the research.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>technical</em> the force that makes an object start moving, or keeps it moving</div></div>","3554":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧ple‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪmpləment/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to take action or make changes that you have officially decided should happen</div><ul class=\"examples\"><li><strong><em>implement a policy/plan/decision etc</strong>: We have decided to implement the committee’s recommendations in full.</em></li></ul></div>","3555":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧pli‧cate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪmplɪkeɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to show or suggest that someone is involved in a crime or dishonest act:</div><ul class=\"examples\"><li><em>The allegations implicated Abe to such an extent he was forced to resign.</em></li><li><strong><em>implicate somebody in something</strong>: Three police officers are implicated in the cover-up.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>formal</em> if something is implicated in something bad or harmful, it is shown to be its cause GRAMMAR Implicate is usually passive in this meaning.</div><ul class=\"examples\"><li><strong><em>be implicated in something</strong>: Viruses are known to be implicated in the development of some cancers.</em></li></ul></div>","3556":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧pli‧ca‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪmplɪˈkeɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable usually plural]</span> a possible future effect or result of an action, event, decision etc</div><ul class=\"examples\"><li><strong><em>implication of</strong>: What are the implications of these proposals?</em></li><li><em>This election has profound implications for the future of U.S. democracy.</em></li><li><strong><em>consider/discuss/examine the implications</strong>: His talk will examine the wider implications of the Internet revolution.</em></li><li><strong><em>practical/financial/political etc implications</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> a situation in which it is shown or suggested that someone or something is involved in a crime or a dishonest act → implicate</div><ul class=\"examples\"><li><strong><em>the implication of somebody (in something)</strong>: the implication of the former Chief of Staff in a major scandal</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> a suggestion that is not made directly but that people are expected to understand or accept → imply:</div><ul class=\"examples\"><li><em>They are called ‘Supertrams’, the implication being that (=which is meant to suggest that) they are more advanced than earlier models.</em></li><li><strong><em>by implication</strong>: The law bans organized protests and, by implication, any form of opposition.</em></li></ul></div>","3557":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧pli‧cit</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪmˈplɪsɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> suggested or understood without being stated directly <em>OPP explicit</em></div><ul class=\"examples\"><li><strong><em>implicit criticism/threat/assumption</strong>: Her words contained an implicit threat.</em></li><li><em>His statement is being seen as implicit criticism of the work of research laboratories.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>formal</em> forming a central part of something, but without being openly stated</div><ul class=\"examples\"><li><strong><em>implicit in</strong>: Confidentiality is implicit in your relationship with a counselor.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> complete and containing no doubts</div><ul class=\"examples\"><li><strong><em>implicit faith/trust/belief</strong>: They had implicit faith in his powers.</em></li></ul></div>","3558":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧ply</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪmˈplaɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2 AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle implied, present participle implying, third person singular implies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to suggest that something is true, without saying this directly → infer, implication</div><ul class=\"examples\"><li><strong><em>imply (that)</strong>: Cleo blushed. She had not meant to imply that he was lying. / an implied threat</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if a fact, event etc implies something, it shows that it is likely to be true <em>SYN suggest</em></div><ul class=\"examples\"><li><strong><em>imply (that)</strong>: The high level of radiation in the rocks implies that they are volcanic in origin.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> if one thing implies another, it proves that the second thing exists:</div><ul class=\"examples\"><li><em>Democracy implies a respect for individual liberties.</em></li><li><em>High profits do not necessarily imply efficiency.</em></li></ul></div>","3559":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧port</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪmpɔːt $ -ɔːrt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a product that is brought from one country into another so that it can be sold there, or the business of doing this <em>OPP export</em>: ► see thesaurus at product</div><ul class=\"examples\"><li><em>a ban on beef imports</em></li><li><em>the abolition of import duties (=taxes)</em></li><li><strong><em>import from</strong>: cheap imports from Asia</em></li><li><em>American demand for Japanese imports (=goods from Japan)</em></li><li><em>the import of electrical goods</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> something new or different that is brought to a place where it did not previously exist:</div><ul class=\"examples\"><li><em>The beetle is thought to be a European import.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> <em>formal</em> importance or meaning → significance:</div><ul class=\"examples\"><li><em>a matter of no great import</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im·port</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪmˈpɔːt $ -ɔːrt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to bring a product from one country into another so that it can be sold there <em>OPP export</em>:</div><ul class=\"examples\"><li><em>In 2001, Britain exported more cars than it imported.</em></li><li><strong><em>import something from something</strong>: All the meat is imported from France.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to introduce something new or different in a place where it did not previously exist:</div><ul class=\"examples\"><li><em>The unusual designs were probably imported from Iran.</em></li><li><strong><em>import something to/into something</strong>: The US comedy format was gradually imported to UK screens.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to move information from one computer to another <em>OPP export</em></div><ul class=\"examples\"><li><strong><em>import something from/into something</strong>: You can now import graphics from other applications.</em></li></ul></div></div>","3560":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧por‧tance</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪmˈpɔːtəns $ -ɔːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W1</span><span class=\"meta-item\"><span class=\"gram\">[singular, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the quality of being important</div><ul class=\"examples\"><li><strong><em>the importance of something</strong>: the importance of regular exercise / I agree about the importance of these proposals (=the reasons why they are important).</em></li><li><strong><em>of importance</strong>: They make decisions about various matters of importance (=important matters).</em></li><li><em>He was full of his own importance (=he behaved in an annoying way which showed that he thought he was very important).</em></li></ul></div>","3561":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧por‧tant</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪmˈpɔːtənt $ -ɔːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an important event, decision, problem etc has a big effect or influence on people’s lives or on events in the future: ► When you mean that you care about something a lot, say that it is important to you, not that it is ‘important for’ you.</div><ul class=\"examples\"><li><em>a very important meeting</em></li><li><em>The accident taught him an important lesson.</em></li><li><em>Happiness is more important than money.</em></li><li><em>‘What did you say?’ ‘Oh, nothing important.’</em></li><li><strong><em>it is important (to do something)</strong>: It’s important to explain the procedure to the patient.</em></li><li><em>It’s vitally important that you understand the danger.</em></li><li><strong><em>important for</strong>: It was important for the president to continue his schedule, regardless of the bomb threat.</em></li><li><strong><em>important to</strong>: Nothing could be more important to me than my family.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> people who are important have a lot of power or influence:</div><ul class=\"examples\"><li><em>a very important customer</em></li><li><em>They carry guns because it makes them feel important.</em></li></ul></div>","3562":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧por‧tant‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪmˈpɔːtəntli $ -ɔːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[sentence adverb]</span> used to show that your next statement or question is more, equally etc important than what you said before</div><ul class=\"examples\"><li><strong><em>more/most/less/equally importantly</strong>: Most importantly, you must keep a record of everything you do.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> in a way that shows you think that what someone is saying or doing is important:</div><ul class=\"examples\"><li><em>He strode importantly into the room.</em></li></ul></div>","3563":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧port‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪmˈpɔːtə $ -ˈpɔːrtər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a person, company, or country that buys goods from other countries so they can be sold in their own country <em>OPP exporter</em></div></div>","3564":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧pose</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪmˈpəʊz $ -ˈpoʊz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> if someone in authority imposes a rule, punishment, tax etc, they force people to accept it:</div><ul class=\"examples\"><li><em>The court can impose a fine.</em></li><li><strong><em>impose something on something/somebody</strong>: The government imposed a ban on the sale of ivory.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to force someone to have the same ideas, beliefs etc as you</div><ul class=\"examples\"><li><strong><em>impose something on somebody</strong>: parents who impose their own moral values on their children</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive]</span> <em>formal</em> to expect or ask someone to do something for you when this is not convenient for them</div><ul class=\"examples\"><li><strong><em>impose on/upon</strong>: We could ask to stay the night, but I don’t want to impose on them.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[transitive]</span> to have a bad effect on something or someone and to cause problems for them RegisterIn everyday English, people usually say put a ban/tax/burden/strain on something rather than impose a ban/tax/burden/strain on something:· The government put a higher tax on cigarettes.· This puts a lot of strain on families.</div><ul class=\"examples\"><li><strong><em>impose a burden/hardship etc (on somebody/something)</strong>: Military spending imposes a huge strain on the economy.</em></li></ul></div>","3565":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧po‧si‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪmpəˈzɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the introduction of something such as a rule, punishment, tax etc</div><ul class=\"examples\"><li><strong><em>imposition of</strong>: the imposition of martial law</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable usually singular]</span> <em>formal</em> something that someone expects or asks you to do for them, which is not convenient for you:</div><ul class=\"examples\"><li><em>I know it’s an imposition, but could I use your bathroom?</em></li></ul></div>","3566":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧pos‧si‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪmˈpɒsəbəl $ ɪmˈpɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> something that is impossible cannot happen or be done <em>OPP possible</em>:</div><ul class=\"examples\"><li><em>‘I want to speak to Mr Franks.’ ‘I’m afraid that’s impossible.’</em></li><li><em>It’s impossible to be accurate about these things.</em></li><li><em>The noise made sleep impossible.</em></li><li><em>Members with young children often found it impossible to attend evening meetings.</em></li><li><em>It is difficult to find work these days, but for blind people it is virtually impossible.</em></li><li><em>He was faced with a seemingly impossible task.</em></li><li><em>It was physically impossible to get the fridge through the door.</em></li><li><em>Six months ago, peace seemed an impossible dream.</em></li><li><em>Such mental attitudes are difficult, if not impossible, to change.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a situation that is impossible is one that you cannot deal with:</div><ul class=\"examples\"><li><em>We were in an impossible situation. Whatever we decided to do would upset someone.</em></li><li><em>Helen’s refusal to cooperate put me in an impossible position.</em></li><li><em>His attitude is making life impossible for the rest of the team.</em></li><li><em>He was facing impossible odds.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> behaving in a very unreasonable and annoying way:</div><ul class=\"examples\"><li><em>Oh, you’re just impossible!</em></li></ul></div>","3567":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧press</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪmˈpres/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[not in progressive]</span> to make someone feel admiration and respect:</div><ul class=\"examples\"><li><em>Steve borrowed his dad’s sports car to impress his girlfriend.</em></li><li><strong><em>impress somebody with/by something</strong>: We were very impressed by the standard of work. / One candidate in particular impressed us with her knowledge. / I think the chief exec was favourably impressed by your presentation.</em></li><li><em>‘He’s a lawyer?’ Mum looked suitably impressed (=as impressed as you would expect).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make the importance of something clear to someone</div><ul class=\"examples\"><li><strong><em>impress something on somebody</strong>: Father impressed on me the value of hard work.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to press something into a soft surface so that a mark or pattern appears on it:</div><ul class=\"examples\"><li><em>patterns impressed in the clay</em></li></ul></div>","3568":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧pres‧sion</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪmˈpreʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the opinion or feeling you have about someone or something because of the way they seem: ► see thesaurus at idea</div><ul class=\"examples\"><li><em>When we looked around the school we got a very good impression.</em></li><li><em>I got the impression that she wasn&#x27;t very happy with her job.</em></li><li><strong><em>impression of</strong>: What was your impression of Roger?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be under the impression (that)</strong> to believe that something is true when it is not:</div><ul class=\"examples\"><li><em>I’m sorry, I was under the impression that you were the manager.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> if you do an impression of a famous person, you copy their speech or behaviour in order to make people laugh <em>SYN imitation</em>:</div><ul class=\"examples\"><li><em>Jean does a great impression of Madonna.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> a picture or drawing of what someone or something might look like, or what something will look like in the future</div><ul class=\"examples\"><li><strong><em>impression of</strong>: an artist’s impression of the new building</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable]</span> a mark left by pressing something into a soft surface:</div><ul class=\"examples\"><li><em>Some of the fallen trees had left a clear impression in the hardened mud.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <span class=\"gram\">[countable]</span> all the copies of a book printed at one time → edition</div></div>","3569":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧pres‧sive</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪmˈpresɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\">something that is impressive makes you admire it because it is very good, large, important etc: ► see thesaurus at good</div><ul class=\"examples\"><li><em>The figures certainly look impressive.</em></li><li><em>Among the guests was an impressive array of authors and critics.</em></li></ul></div>","3570":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧pris‧on</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪmˈprɪzən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to put someone in prison or to keep them somewhere and prevent them from leaving:</div><ul class=\"examples\"><li><em>The government imprisoned all opposition leaders.</em></li><li><em>She was imprisoned within his strong arms.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if a situation or feeling imprisons people, it restricts what they can do:</div><ul class=\"examples\"><li><em>Many elderly people feel imprisoned in their own homes.</em></li></ul></div>","3571":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧pris‧on‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪmˈprɪzənmənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the state of being in prison, or the time someone spends there:</div><ul class=\"examples\"><li><em>They were sentenced to 6 years’ imprisonment.</em></li><li><em>life imprisonment</em></li></ul></div>","3572":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧prove</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪmˈpruːv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"gram\">[intransitive, transitive]</span> to make something better, or to become better: RegisterIn everyday English, people often say something gets better rather than improves:· Her English is definitely getting better.· I hope things get better soon.</div><ul class=\"examples\"><li><em>a course for students wishing to improve their English</em></li><li><em>The doctors say she is improving (=after being ill).</em></li><li><em>You could use the money for improving your home.</em></li><li><em>Many wines improve with age (=get better as they get older).</em></li></ul></div>","3573":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧proved</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪmˈpruːvd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[usually before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\">better than before:</div><ul class=\"examples\"><li><em>improved performance</em></li><li><em>Our washing powder now has a new improved formula.</em></li></ul></div>","3574":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧prove‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪmˈpruːvmənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the act of improving something, or the state of being improved</div><ul class=\"examples\"><li><strong><em>improvement in/on/to</strong>: There’s been a big improvement in the children’s behaviour. / an improvement on earlier models / We need to carry out some improvements to the system.</em></li><li><em>Our results have shown some improvement this month.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a change or addition that improves something:</div><ul class=\"examples\"><li><em>Are you making some improvements to your home?</em></li></ul></div>","3575":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧pulse</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪmpʌls/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a sudden strong desire to do something without thinking about whether it is a sensible thing to do <em>SYN urge</em></div><ul class=\"examples\"><li><strong><em>impulse to do something</strong>: a sudden impulse to laugh / Marge’s first impulse was to run. / Gerry couldn’t resist the impulse to kiss her.</em></li><li><strong><em>on impulse</strong>: On impulse, I picked up the phone and rang her. / Most beginners buy plants on impulse and then hope for the best.</em></li><li><strong><em>impulse buying/shopping</strong> (=when you buy things that you had not planned to buy)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> <em>technical</em> a short electrical signal that travels in one direction along a nerve or wire:</div><ul class=\"examples\"><li><em>The eye converts light signals to nerve impulses.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a reason or aim that causes a particular kind of activity or behaviour:</div><ul class=\"examples\"><li><em>It is the passions which provide the main impulse of music.</em></li></ul></div>","3576":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> im‧pul‧sive</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪmˈpʌlsɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">someone who is impulsive does things without considering the possible dangers or problems first → rash:</div><ul class=\"examples\"><li><em>Rosa was impulsive and sometimes regretted things she’d done.</em></li><li><em>In a burst of impulsive generosity, I offered to pay.</em></li></ul></div>","3577":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">preposition</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used with the name of a container, place, or area to say where someone or something is:</div><ul class=\"examples\"><li><em>There’s some sugar in the cupboard.</em></li><li><em>My mother was in the kitchen.</em></li><li><em>He took us for a drive in his new car.</em></li><li><em>I found her sitting up in bed.</em></li><li><em>Manson spent fifteen years in prison.</em></li><li><em>a hole in the ground</em></li><li><em>Mr Fisher is in Boston this week.</em></li><li><em>My parents live in New Zealand now.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> into a container, place etc:</div><ul class=\"examples\"><li><em>I never went in pubs.</em></li><li><em>He almost drowned when he fell in the river.</em></li><li><em>You can put your pyjamas in the bottom drawer.</em></li><li><em>Get in the car.</em></li><li><em>She looked in her handbag, but her keys were not there.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to say how something is done or happens:</div><ul class=\"examples\"><li><em>a room furnished in the modern style</em></li><li><em>Her parents always talk to her in German.</em></li><li><em>She shouted my name in a harsh voice.</em></li><li><em>a short note scribbled in pencil</em></li><li><em>The title was printed in capital letters.</em></li><li><em>We waited in silence.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> used with the names of months, years, seasons etc to say when something happens:</div><ul class=\"examples\"><li><em>Shaw first visited Russia in 1927.</em></li><li><em>Bright yellow flowers appear in late summer.</em></li><li><em>He retired in October.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> during a period of time: GRAMMAR• You say: · I got a card from my sister this morning.· I hope to go to Europe next summer. ✗Don’t say: in this morning | in next summer• You say: · The group meets three times a month. ✗Don’t say: three times in a month• You can say in one week, month etc when emphasizing how often something happens: · He was stopped for speeding three times in one month.</div><ul class=\"examples\"><li><em>It was amazing how much we managed to do in a day.</em></li><li><em>the hardest decision I ever made in my life</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> at the end of a period of time: ► see thesaurus at after</div><ul class=\"examples\"><li><em>I’ll be with you in a minute.</em></li><li><em>The results will be announced in two weeks’ time.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> used with negatives or with ‘first’ to say how much time has passed since the last time something happened:</div><ul class=\"examples\"><li><em>I haven’t enjoyed myself so much in years.</em></li><li><em>It was the team’s first win in eighteen months.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> used to name the book, document, film etc where something or someone appears:</div><ul class=\"examples\"><li><em>You shouldn’t believe everything you read in the newspapers.</em></li><li><em>Which actress starred in the film ‘Cleopatra’?</em></li><li><em>There are a few mistakes in your essay.</em></li><li><em>In his speech, Professor Leary praised the work of the volunteers.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> making up the whole of something or included as part of something:</div><ul class=\"examples\"><li><em>There are twelve programmes in the series.</em></li><li><em>How many minutes are there in an hour?</em></li><li><em>Think of a word with eight letters in it meaning ‘cold’.</em></li><li><em>Owen will be playing in the England team tomorrow.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> doing or affecting a particular kind of job:</div><ul class=\"examples\"><li><em>a career in industry</em></li><li><em>He’s been in politics for fifteen years.</em></li><li><em>reforms in education</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> wearing something:</div><ul class=\"examples\"><li><em>He looked very handsome in his uniform.</em></li><li><em>She was dressed in a blue linen suit.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> used to talk about the state or situation of something or someone:</div><ul class=\"examples\"><li><em>I hear that their marriage is in trouble.</em></li><li><em>The engine appears to be in good condition.</em></li><li><em>His life was in danger.</em></li><li><em>The castle now lies in ruins.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> used to say what activity a group of people do:</div><ul class=\"examples\"><li><em>About 4,000 students took part in the protest.</em></li><li><em>his role in the negotiations</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> used to talk about the shape, arrangement, or course of something or someone:</div><ul class=\"examples\"><li><em>I want you all to stand in a circle.</em></li><li><em>She slept curled up in a ball.</em></li><li><em>Can you walk in a straight line?</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> used between a smaller number and a larger number to say how common or how likely something is:</div><ul class=\"examples\"><li><em>One in ten homes now has cable TV.</em></li><li><em>Smokers have a one in three chance of dying from their habit.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> used before a plural number or amount to say how many people or things are involved, or how many there are in each group:</div><ul class=\"examples\"><li><em>Eggs are still sold in half dozens.</em></li><li><em>The children work in pairs.</em></li><li><strong><em>in their hundreds/thousands etc</strong> (=in very large numbers): People flocked in their thousands to greet their new princess.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> used between a smaller number or amount and a larger one to say what a rate is:</div><ul class=\"examples\"><li><em>Income tax stands at 23 pence in the pound.</em></li><li><em>a hill with a gradient of one in six</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> used to say what colour something is or what it is made of:</div><ul class=\"examples\"><li><em>Do you have the same pattern in blue?</em></li><li><em>a sculpture in white marble</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> used to say what specific thing your statement is related to:</div><ul class=\"examples\"><li><em>Milk is very rich in calcium.</em></li><li><em>Clark had become more extreme in his opinions.</em></li><li><em>an increase in fuel prices</em></li><li><em>The street is about a mile in length.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> used to refer to the weather or the physical conditions somewhere:</div><ul class=\"examples\"><li><em>I’ve been standing in the rain for over an hour.</em></li><li><em>Would you prefer to sit in the shade?</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> used to say what feeling you have when you do something:</div><ul class=\"examples\"><li><em>She looked at me in horror.</em></li><li><em>It was all done purely in fun.</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> used before the name of someone or something when you are saying how they are regarded:</div><ul class=\"examples\"><li><em>You have a very good friend in Pat.</em></li><li><em>In Dwight D. Eisenhower the Republicans had found the ideal candidate.</em></li></ul><div class=\"sense\"><span class=\"snum\">23</span> used to say what person or thing has the quality you are mentioning:</div><ul class=\"examples\"><li><em>There was a hint of spring in the air.</em></li><li><em>I don’t think Freddy had it in him to be a killer.</em></li><li><em>She’s everything I’d want in a wife (=she has every quality I would want a wife to have).</em></li></ul><div class=\"sense\"><span class=\"snum\">24</span> used to name the substance, food, drink etc that contains something:</div><ul class=\"examples\"><li><em>Vitamin D is found in butter.</em></li></ul><div class=\"sense\"><span class=\"snum\">25</span> used to say how many parts something is divided into:</div><ul class=\"examples\"><li><em>a radio serial in four parts</em></li><li><strong><em>in two/halves/pieces etc</strong>: I tore the letter in two and threw the pieces in the fire.</em></li></ul><div class=\"sense\"><span class=\"snum\">26</span> while doing something or while something is happening, and as a result of this:</div><ul class=\"examples\"><li><em>In all the confusion, it is quite possible that some people got tickets without paying.</em></li><li><em>In my excitement, I forgot all about the message.</em></li><li><strong><em>in doing something</strong>: In trying to protect the queen, Howard had put his own life in danger.</em></li></ul><div class=\"sense\"><span class=\"snum\">27</span> <strong>in that</strong> used after a statement to begin to explain in what way it is true:</div><ul class=\"examples\"><li><em>I’ve been lucky in that I have never had to worry about money.</em></li></ul><div class=\"sense\"><span class=\"snum\">28</span> <strong>be in your 20s/30s/40s etc</strong> to be between the ages of 20 and 29, 30 and 39 etc:</div><ul class=\"examples\"><li><em>Matthews was already in his mid-40s.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> into or inside a container, place, vehicle etc <em>OPP out</em>:</div><ul class=\"examples\"><li><em>Eric held the boat steady while the children got in.</em></li><li><em>He went to the ticket machine and put a coin in.</em></li><li><em>She dived in and swam out to the yacht.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> inside or into a building, especially your home or the place where you work <em>OPP out</em>:</div><ul class=\"examples\"><li><em>Come in and sit down.</em></li><li><em>I’m afraid Mr Stewart won’t be in until tomorrow morning.</em></li><li><em>We’re staying in this evening.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> if a train, boat, or plane is in, it has arrived at a station, airport etc:</div><ul class=\"examples\"><li><em>Our train’s not in yet.</em></li><li><em>When’s her flight due in?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> given or sent to a person or organization to be dealt with by them:</div><ul class=\"examples\"><li><em>All entries must be in by next week.</em></li><li><em>Letters have been pouring in from all over the country.</em></li><li><em>Have you handed your essay in yet?</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> if you write, paint, or draw something in, you add it in the correct place:</div><ul class=\"examples\"><li><em>Fill in your name and address on the form provided.</em></li><li><em>The information is typed in by trained keyboarders.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> if a player or team is in during a game of cricket, they are batting (bat)</div><div class=\"sense\"><span class=\"snum\">7</span> if a ball is in during a game, it is inside the area where the game is being played <em>OPP out</em>:</div><ul class=\"examples\"><li><em>Agassi’s second serve was just in.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> if a politician or a political party is in, they have been elected:</div><ul class=\"examples\"><li><em>Labour recorded its highest vote ever, but the Tories got in again.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> towards the centre <em>SYN inward(s)</em>:</div><ul class=\"examples\"><li><em>The map had started to curl in at the edges.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> when the tide is in, the sea by the shore is at its highest level <em>OPP out</em>:</div><ul class=\"examples\"><li><em>The tide was in, and the sea lapped against the harbour wall.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>be in for something</strong> if someone is in for something unpleasant, it is going to happen to them:</div><ul class=\"examples\"><li><em>I’m afraid he’s in for a bit of a disappointment.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>be in for it</strong> <em>informal</em> if someone is in for it, they are going to be punished:</div><ul class=\"examples\"><li><em>If they find out what I’ve done, I’ll be in for it, won’t I?</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>be/get in on something</strong> to be or become involved in something that is happening:</div><ul class=\"examples\"><li><em>I think you ought to be in on this discussion, Ted.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>be in with somebody</strong> <em>informal</em> to have a friendly relationship with someone:</div><ul class=\"examples\"><li><em>She’s in with the theatrical crowd.</em></li><li><em>You have to be well in with the directors (=be very friendly with them) if you want to get promotion here.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>be in at the beginning/start (of something)</strong> to be present or involved when something starts</div></div></div>","3578":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧a‧bil‧i‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnəˈbɪləti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[singular, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the fact of being unable to do something</div><ul class=\"examples\"><li><strong><em>inability to do something</strong>: Alcoholism can result in an inability to cope. / the government’s inability to enforce the ceasefire</em></li></ul></div>","3579":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ac‧cu‧rate</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈækjərət/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">not completely correct <em>OPP accurate</em>: ► see thesaurus at wrong</div><ul class=\"examples\"><li><em>A lot of what has been written about him is inaccurate.</em></li><li><strong><em>inaccurate information/data etc</strong>: He was fined $300,000 for making inaccurate statements to Congress.</em></li></ul></div>","3580":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ad‧e‧quate</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈædəkwət/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not good enough, big enough, skilled enough etc for a particular purpose <em>OPP adequate</em>:</div><ul class=\"examples\"><li><em>inadequate resources</em></li><li><strong><em>inadequate for</strong>: The parking facilities are inadequate for a busy shopping centre.</em></li><li><strong><em>totally/wholly/woefully/hopelessly etc inadequate</strong>: The building’s electrical system was completely inadequate.</em></li><li><em>The new air conditioning system proved inadequate.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who feels inadequate thinks other people are better, more skilful, more intelligent etc than they are:</div><ul class=\"examples\"><li><em>The teacher made us feel inadequate and stupid if we made mistakes.</em></li></ul></div>","3581":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ap‧pro‧pri‧ate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnəˈprəʊpri-ət $ -ˈproʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">not suitable or right for a particular purpose or in a particular situation <em>OPP appropriate</em></div><ul class=\"examples\"><li><strong><em>wholly/totally/completely etc inappropriate</strong>: His comments were wholly inappropriate on such a solemn occasion.</em></li><li><strong><em>it is inappropriate (for somebody) to do something</strong>: It would be inappropriate for me to comment until we know more of the facts.</em></li><li><strong><em>inappropriate for</strong>: an inappropriate gift for a child</em></li><li><strong><em>inappropriate to</strong>: marketing techniques that are totally inappropriate to education</em></li><li><strong><em>inappropriate behaviour/response/language etc</em></strong></li></ul></div>","3582":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧box</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnbɒks $ -bɑːks/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the place in a computer email program where new messages arrive:</div><ul class=\"examples\"><li><em>I had 130 emails in my inbox this morning.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>American English</em> a container on an office desk that is used to hold letters, documents etc that you must deal with SYN in tray<em>British English</em> → outbox</div></div>","3583":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ca‧pa‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈkeɪpəbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"gram\">[not before noun]</span> not able to do something <em>OPP capable</em></div><ul class=\"examples\"><li><strong><em>incapable of</strong>: He seemed incapable of understanding how she felt. / Seventy-five percent of the electorate believe his party is incapable of government. / The stroke rendered her incapable of speech.</em></li></ul></div>","3584":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧cen‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈsentɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">something that encourages you to work harder, start a new activity etc → motivation:</div><ul class=\"examples\"><li><em>As an added incentive, there’s a bottle of champagne for the best team.</em></li><li><strong><em>create/provide/give somebody an incentive</strong>: Awards provide an incentive for young people to improve their skills.</em></li><li><strong><em>incentive to do something</strong>: Farmers lack any incentive to manage their land organically.</em></li><li><strong><em>economic/financial/tax etc incentives</strong>: a recycling drive backed with financial incentives</em></li></ul></div>","3585":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ɪntʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> (written abbreviation in<em>British English</em> or in.<em>American English</em>) a unit for measuring length, equal to 2.54 centimetres. There are 12 inches in a foot:</div><ul class=\"examples\"><li><em>The curtains were an inch too short.</em></li><li><em>Rainfall here is under 15 inches a year.</em></li><li><strong><em>a one-/two-/three- etc inch something</strong>: a six-inch nail</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a very small distance:</div><ul class=\"examples\"><li><em>Derek leaned closer, his face only inches from hers.</em></li><li><em>The bus missed us by inches.</em></li><li><em>On several occasions, they came within inches of death.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>every inch</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> completely or in every way:</div><ul class=\"examples\"><li><em>With her designer clothes and elegant hair, she looks every inch the celebrity.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> the whole of an area or distance</div><ul class=\"examples\"><li><strong><em>inch of</strong>: Every inch of space in the tiny shop was crammed with goods. / Italy deserved to win, though Greece made them fight every inch of the way.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>give somebody an inch and they’ll take a yard/mile</strong> used to say that, if you allow someone a little freedom or power, they will try to take more</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>inch by inch</strong> moving very gradually and slowly:</div><ul class=\"examples\"><li><em>Inch by inch, he lowered himself from the roof.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>not give/budge an inch</strong> to refuse to change your decision or opinion, even though people are trying to persuade you to do this:</div><ul class=\"examples\"><li><em>Neither side is prepared to give an inch in the negotiations.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>beat/thrash etc somebody to within an inch of their life</strong> to beat someone very hard and thoroughly:</div><ul class=\"examples\"><li><em>Another word out of you and I’ll beat you to within an inch of your life.</em></li></ul></div>","3586":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ci‧dent</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnsɪdənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an event, especially one that is unusual, important, or violent: ► see thesaurus at event RegisterIncident is used mainly in journalism or in formal contexts. In everyday English, people usually say something happened rather than talking about an incident:· Am I at risk because of something that happened in my past?</div><ul class=\"examples\"><li><em>Am I at risk because of some incident in my sexual past?</em></li><li><em>Roads were sealed off because of a major incident.</em></li><li><strong><em>without incident</strong>: The plane landed without incident.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a serious disagreement between two countries:</div><ul class=\"examples\"><li><em>You could have caused a major diplomatic incident.</em></li></ul></div>","3587":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ci‧den‧tal‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnsəˈdentəli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[sentence adverb]</span> used to add more information to what you have just said, or to introduce a new subject that you have just thought of <em>SYN by the way</em>:</div><ul class=\"examples\"><li><em>Incidentally, where were you born?</em></li><li><em>The wine, incidentally, goes very well with a mature cheese.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> in a way that was not planned, but as a result of something else:</div><ul class=\"examples\"><li><em>Quite incidentally, I got some useful information at the party.</em></li></ul></div>","3588":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧cli‧na‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪŋkləˈneɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a feeling that makes you want to do something:</div><ul class=\"examples\"><li><em>My natural inclination was to say no.</em></li><li><strong><em>inclination to do something</strong>: Neither of my children showed the slightest inclination to follow me into journalism.</em></li><li><em>Teachers simply do not have the time or the inclination to investigate these matters.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> a tendency to think or behave in a particular way</div><ul class=\"examples\"><li><strong><em>inclination to do something</strong>: an inclination to see everything in political terms</em></li><li><strong><em>inclination to/towards</strong>: She’s troubled by her son’s inclination toward atheism.</em></li><li><strong><em>by inclination</strong>: Bart was a romantic by inclination.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a movement made down towards the ground:</div><ul class=\"examples\"><li><em>She greeted Maggie with an inclination of the head.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable, uncountable]</span> <em>formal</em> a slope, or the angle at which something slopes</div></div>","3589":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧clined</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈklaɪnd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>be inclined to agree/think/believe etc</strong> to hold a particular opinion, but not very strongly:</div><ul class=\"examples\"><li><em>Arthur has some strange ideas, but on this occasion I’m inclined to agree with him.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be inclined to do something/inclined to something</strong> to be likely to do something or behave in a particular way:</div><ul class=\"examples\"><li><em>Commandos are inclined to shoot first and ask questions later.</em></li><li><em>He was inclined to self-pity.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be/feel inclined (to do something)</strong> to want to do something, but without having a strong desire:</div><ul class=\"examples\"><li><em>It was Sunday morning, and she was not inclined to get up yet.</em></li><li><em>You can visit our chat rooms, if you feel so inclined.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>artistically/musically/mathematically etc inclined</strong> naturally interested in or good at art, music etc:</div><ul class=\"examples\"><li><em>For the artistically inclined, the markets are full of interest.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> sloping or leaning in a particular direction</div></div>","3590":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧clude</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈkluːd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if one thing includes another, the second thing is part of the first:</div><ul class=\"examples\"><li><em>Does the price include postage?</em></li><li><em>His job includes looking after under-21 teams.</em></li><li><em>The curriculum includes courses in computing.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make someone or something part of a larger group or set <em>OPP exclude</em>:</div><ul class=\"examples\"><li><em>The team is stronger now they’ve included Roscoe.</em></li><li><strong><em>include something in/on something</strong>: Service is included in the bill. / Would you include a mobile phone on your list of essentials?</em></li></ul></div>","3591":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧clud‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈkluːdɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\">used to introduce something or someone that is part of a larger group or amount you have just mentioned <em>OPP excluding</em>: RegisterIn written or business English, people often prefer to use excluding rather than not including, as it sounds more formal:· The cost is $49.95 excluding tax.</div><ul class=\"examples\"><li><em>The price is £25.50, including postage and packing.</em></li><li><em>You’ll need a variety of skills, including leadership and negotiating.</em></li></ul></div>","3592":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧clu‧sion</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈkluːʒən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the act of including someone or something in a larger group or set, or the fact of being included in one</div><ul class=\"examples\"><li><strong><em>inclusion in</strong>: His inclusion in the team has caused controversy. / photos chosen for inclusion in the magazine</em></li><li><strong><em>inclusion of</strong>: the inclusion of early recordings on the CD</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> someone or something that has been included in a larger group:</div><ul class=\"examples\"><li><em>With the recent inclusions, there will be 28 delegates in all.</em></li></ul></div>","3593":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧clu‧sive</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈkluːsɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an inclusive price or cost includes everything <em>OPP exclusive</em></div><ul class=\"examples\"><li><strong><em>all-inclusive/fully inclusive</strong>: The fully inclusive fare for the trip is £22.</em></li><li><strong><em>inclusive of</strong>: The rent is £120 a week, inclusive of heating.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> including a wide variety of people, things etc <em>OPP exclusive</em>:</div><ul class=\"examples\"><li><em>Not everyone shares his vision of an inclusive America.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>(from) April to June inclusive/15 to 20 inclusive etc</strong> used to refer to a range of months, numbers etc, including the ones that start and end the range RegisterIn everyday American English, people usually use through rather than inclusive:· They are open Monday through Friday.</div></div>","3594":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧come</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪŋkʌm, ˈɪn-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the money that you earn from your work or that you receive from investments, the government etc → salary ► see thesaurus at salary</div><ul class=\"examples\"><li><strong><em>on an income</strong>: People on higher incomes should pay more tax.</em></li><li><strong><em>income from</strong>: income from savings and pensions / low-income families</em></li></ul></div>","3595":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧com‧pat‧i‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnkəmˈpætəbəl◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> two people who are incompatible have such different characters, beliefs etc that they cannot have a friendly relationship <em>OPP compatible</em>:</div><ul class=\"examples\"><li><em>I don’t know why they ever got married. They’re totally incompatible.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> two things that are incompatible cannot exist or be accepted together</div><ul class=\"examples\"><li><strong><em>incompatible with</strong>: Business interests are incompatible with public office.</em></li><li><em>Politeness and truth are often mutually incompatible.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> two things that are incompatible are of different types and so cannot be used together <em>OPP compatible</em></div><ul class=\"examples\"><li><strong><em>incompatible with</strong>: The laser printer is incompatible with the new computer.</em></li><li><em>incompatible blood groups</em></li></ul></div>","3596":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧com‧plete</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnkəmˈpliːt◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">not having everything that should be there, or not completely finished <em>OPP complete</em>:</div><ul class=\"examples\"><li><em>Unfortunately, I do not have the information because our records are incomplete.</em></li><li><em>an incomplete process</em></li><li><em>TV ads implied that a woman was incomplete without a man.</em></li></ul></div>","3597":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧com‧pre‧hen‧si‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˌkɒmprɪˈhensəbəl $ -ˌkɑːm-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">difficult or impossible to understand:</div><ul class=\"examples\"><li><em>legal documents full of incomprehensible jargon</em></li><li><em>I find your attitude quite incomprehensible.</em></li><li><strong><em>incomprehensible to</strong>: His accent made his speech incomprehensible to me.</em></li></ul></div>","3598":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧con‧sid‧er‧ate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnkənˈsɪdərət◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">not caring about the feelings, needs, or comfort of other people <em>SYN thoughtless</em> <em>OPP considerate</em>: ► see thesaurus at unkind</div><ul class=\"examples\"><li><em>inconsiderate motorists</em></li><li><strong><em>it was inconsiderate (of somebody) to do something</strong>: It was very inconsiderate of you to keep us waiting.</em></li></ul></div>","3599":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧con‧sis‧tent</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnkənˈsɪstənt◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> two statements that are inconsistent cannot both be true <em>SYN contradictory</em> <em>OPP consistent</em>:</div><ul class=\"examples\"><li><em>The accounts of the witnesses are inconsistent.</em></li><li><strong><em>inconsistent with</strong>: His results are inconsistent with our data.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> not right according to a particular set of principles or standards <em>OPP consistent</em></div><ul class=\"examples\"><li><strong><em>inconsistent with</strong>: His conduct was inconsistent with what is expected of a congressman.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> inconsistent behaviour, work etc changes too often from good to bad <em>OPP consistent</em>:</div><ul class=\"examples\"><li><em>The team’s performance has been highly inconsistent this season.</em></li></ul></div>","3600":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧con‧ve‧ni‧ent</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnkənˈviːniənt◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">causing problems, often in a way that is annoying <em>OPP convenient</em>:</div><ul class=\"examples\"><li><em>Monday’s a bit inconvenient for me. How about Wednesday?</em></li><li><em>Am I calling at an inconvenient time?</em></li></ul></div>","3601":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧cor‧po‧rate</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈkɔːpəreɪt $ -ɔːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to include something as part of a group, system, plan etc</div><ul class=\"examples\"><li><strong><em>incorporate something into/in something</strong>: We’ve incorporated many environmentally friendly features into the design of the building. / Our original proposals were not incorporated in the new legislation.</em></li></ul></div>","3602":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧cor‧rect</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnkəˈrekt◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not correct or true: ► see thesaurus at wrong</div><ul class=\"examples\"><li><em>The information you gave us was incorrect.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> not following the rules of polite or fair behaviour <em>SYN impolite</em>:</div><ul class=\"examples\"><li><em>It would be incorrect of me to comment.</em></li></ul></div>","3603":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧crease</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈkriːs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"gram\">[intransitive, transitive]</span> if you increase something, or if it increases, it becomes bigger in amount, number, or degree <em>OPP decrease</em> <em>, reduce</em>: RegisterIn everyday English, people usually say that an amount or level goes up rather than increases:· The population has gone up a lot.· Her investments all went up in value.</div><ul class=\"examples\"><li><em>The population increased dramatically in the first half of the century.</em></li><li><em>political tensions that might increase the likelihood of war</em></li><li><em>Visits to the site have increased threefold since May.</em></li><li><strong><em>increase in value/price/importance etc</strong>: Investments are certain to increase in value.</em></li><li><strong><em>increase (something) by something</strong>: Food prices increased by 10% in less than a year.</em></li><li><strong><em>increase (something) from/to something</strong>: The salary is £18,600 a year, increasing to £23,000.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧crease</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnkriːs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a rise in amount, number, or degree <em>OPP decrease</em></div><ul class=\"examples\"><li><strong><em>increase in</strong>: an increase in the crime rate</em></li><li><em>Recent tax increases have affected the poor more than the rich.</em></li><li><em>the dramatic increase in the population aged over 65</em></li><li><em>There has been a marked increase in the use of firearms.</em></li><li><em>Cases of tuberculosis are on the increase.</em></li></ul></div></div>","3604":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧creas‧ing‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈkriːsɪŋli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2</span></div><div class=\"entry-body\"><div class=\"sense\">more and more all the time:</div><ul class=\"examples\"><li><em>Marketing techniques are becoming increasingly sophisticated.</em></li><li><em>Increasingly, young people distrust all forms of government.</em></li></ul></div>","3605":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧cred‧i‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈkredəbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> extremely good, large, or great <em>SYN unbelievable</em>: ► see thesaurus at good</div><ul class=\"examples\"><li><em>The view is just incredible.</em></li><li><em>There was blood everywhere and the pain was incredible.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> too strange to be believed, or very difficult to believe <em>SYN unbelievable</em>:</div><ul class=\"examples\"><li><em>It’s incredible that he survived the fall.</em></li><li><em>It’s incredible how much Tom has changed since he met Sally.</em></li><li><em>I find it almost incredible that no one noticed these errors.</em></li></ul></div>","3606":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧cred‧i‧bly</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈkredəbli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[+adjective/adverb]</span> <em>informal</em> extremely:</div><ul class=\"examples\"><li><em>Nicotine is incredibly addictive.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[sentence adverb]</span> in a way that is hard to believe:</div><ul class=\"examples\"><li><em>The knife had pierced his heart, but incredibly he was still alive.</em></li></ul></div>","3607":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧cur</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈkɜː $ -ˈkɜːr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle incurred, present participle incurring)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if you incur a cost, debt, or a fine, you have to pay money because of something you have done</div><ul class=\"examples\"><li><strong><em>incur expenses/costs/losses/debts etc</strong>: If the council loses the appeal, it will incur all the legal costs. / the heavy losses incurred by airlines since September 11th</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if you incur something unpleasant, it happens to you because of something you have done</div><ul class=\"examples\"><li><strong><em>incur somebody’s displeasure/wrath/disapproval etc</strong>: She wondered what she’d done to incur his displeasure this time.</em></li></ul></div>","3608":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧de‧ci‧sive</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪndɪˈsaɪsɪv◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> unable to make clear decisions or choices <em>OPP decisive</em>:</div><ul class=\"examples\"><li><em>a weak and indecisive leader</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> not having a clear result <em>SYN inconclusive</em>:</div><ul class=\"examples\"><li><em>a confused, indecisive battle</em></li></ul></div>","3609":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧deed</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈdiːd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[sentence adverb]</span> used to emphasize a statement or answer:</div><ul class=\"examples\"><li><em>The blood tests prove that Vince is indeed the father.</em></li><li><em>‘Would it help if you had an assistant?’ ‘It would indeed.’</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[sentence adverb]</span> <em>formal</em> used to introduce an additional statement that emphasizes or supports what you have just said:</div><ul class=\"examples\"><li><em>I didn’t mind at all. Indeed, I was pleased.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>especially British English</em> used with ‘very’ and an adjective or adverb to emphasize a statement or description:</div><ul class=\"examples\"><li><em>Most of the essays were very good indeed.</em></li><li><em>Thank you very much indeed.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>British English</em> <em>spoken</em> used to show that you are surprised or annoyed by something that someone has just told you:</div><ul class=\"examples\"><li><em>‘He said he was too busy to see you.’ ‘Did he, indeed?’</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>why/how/who etc indeed?</strong> <em>spoken</em> used when someone has asked you a question, to show that you do not know the answer and you do not think there can be a satisfactory answer:</div><ul class=\"examples\"><li><em>‘Why would John have left without saying a word?’ ‘Why indeed?’</em></li></ul></div>","3610":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧def‧i‧nite</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈdefənət/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an indefinite action or period of time has no definite end arranged for it:</div><ul class=\"examples\"><li><em>The next day the union voted to begin an indefinite strike.</em></li><li><em>The picture has been loaned for an indefinite period to the National Gallery.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> not clear or exact <em>SYN vague</em>:</div><ul class=\"examples\"><li><em>Teachers find the report’s terminology so indefinite that it is confusing.</em></li></ul></div>","3611":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧def‧i‧nit‧ely</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈdefənətli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> for a period of time for which no definite end has been arranged:</div><ul class=\"examples\"><li><em>The project has been postponed indefinitely.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> without giving clear or exact details</div></div>","3612":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧de‧pen‧dence</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪndəˈpendəns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W2</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> political freedom from control by the government of another country</div><ul class=\"examples\"><li><strong><em>independence from</strong>: Nigeria gained independence from Britain in 1960.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the time when a country becomes politically independent:</div><ul class=\"examples\"><li><em>The country has made great advances since independence.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> the freedom and ability to make your own decisions in life, without having to ask other people for permission, help, or money:</div><ul class=\"examples\"><li><em>ways of helping old people maintain their independence</em></li><li><em>Having a job gives you financial independence.</em></li></ul></div>","3613":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧de‧pen‧dent</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪndəˈpendənt◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[not owned/controlled by something]</strong> <span class=\"gram\">[usually before noun]</span> an independent organization is not owned or controlled by, or does not receive money from, another organization or the government:</div><ul class=\"examples\"><li><em>There are plans to split the corporation into a number of smaller independent companies.</em></li><li><em>an independent charity</em></li><li><em>small independent bookshops</em></li><li><strong><em>independent of</strong>: We need a central bank that is independent of the government.</em></li><li><strong><em>independent school<em>especially British English</em></strong> (=one not owned or paid for by the government)</em></li><li><em>schools in the independent sector</em></li><li><strong><em>independent television/radio/broadcasting etc<em>British English</em></strong> (=not owned or paid for by the government): independent television companies</em></li><li><strong><em>independent film</strong> (=one not made or produced by a large film production company)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[fair]</strong> <span class=\"gram\">[usually before noun]</span> an independent organization or person is not involved in a particular situation, and can therefore be trusted to be fair in judging it:</div><ul class=\"examples\"><li><em>an independent panel of scientists</em></li><li><em>An independent body (=group of people who work together) has been set up to monitor government spending.</em></li><li><em>There were no independent witnesses to the shooting.</em></li><li><strong><em>independent inquiry/advice/opinion etc</strong> (=carried out by or given by an independent person or organization): Human rights groups have called for an independent inquiry into the killings. / the results of an independent study</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[country]</strong> an independent country is not governed or controlled by another country:</div><ul class=\"examples\"><li><em>India became independent in 1947.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[person]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> confident and able to do things by yourself in your own way, without needing help or advice from other people <em>OPP dependent</em>:</div><ul class=\"examples\"><li><em>Now that my sons are more independent, I have more time for myself.</em></li><li><em>an independent young woman</em></li><li><em>He’s helping other people with spinal injuries to lead an independent life.</em></li><li><strong><em>independent of</strong>: By this age, the child becomes relatively independent of his mother.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> having enough money to live, without having to ask for help from other people:</div><ul class=\"examples\"><li><em>It was always very important to me to be financially independent.</em></li><li><strong><em>independent of</strong>: Robert aimed to be independent of his parents by the time he was twenty.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>independent study/learning</strong> when you study on your own, rather than being taught by a teacher:</div><ul class=\"examples\"><li><em>The tapes can be used in class or for independent study.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>woman/man etc of independent means</strong> someone who has their own income from property, investments etc, so that they do not have to work or depend on anyone else</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>[separate]</strong> if one thing is independent of another, the two are not connected, or the second thing does not influence the first</div><ul class=\"examples\"><li><strong><em>independent of</strong>: reports from two separate sources entirely independent of one another</em></li><li><em>Three independent studies all arrived at the same conclusion.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[politician]</strong> <span class=\"gram\">[usually before noun]</span> an independent politician does not belong to a particular party:</div><ul class=\"examples\"><li><em>Independent candidates won three seats.</em></li></ul></div>","3614":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧dex</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪndeks/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> (plural indexes) an alphabetical list of names, subjects etc at the back of a book, with the numbers of the pages where they can be found</div><div class=\"sense\"><span class=\"snum\">2</span> (plural indexes) a set of cards or a database containing information, usually arranged in alphabetical order and used especially in a library</div><div class=\"sense\"><span class=\"snum\">3</span> (plural indices /ˈɪndəsiːz/) a standard by which the level of something can be judged or measured</div><ul class=\"examples\"><li><strong><em>index of</strong>: The changing size of an infant’s head is considered an index of brain growth.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> (plural indices /ˈɪndəsiːz/ or indexes) <em>technical</em> a system by which prices, costs etc can be compared to those of a previous date</div></div>","3615":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧di‧cate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪndɪkeɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W1 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to show that a particular situation exists, or that something is likely to be true</div><ul class=\"examples\"><li><strong><em>indicate (that)</strong>: Research indicates that over 81% of teachers are dissatisfied with their salary. / Long skid marks on the pavement indicated the driver had attempted to brake.</em></li><li><em>The study indicates a connection between poverty and crime.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to say or do something to make your wishes, intentions etc clear:</div><ul class=\"examples\"><li><em>The Russians have already indicated their willingness to cooperate.</em></li><li><em>Professor Johnson has indicated his intention to retire at the end of next year.</em></li><li><strong><em>indicate (that)</strong>: Ralph patted the sofa to indicate that she should join him.</em></li><li><em>Please indicate your preference on the booking form.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to direct someone’s attention to something or someone, for example by pointing:</div><ul class=\"examples\"><li><em>‘That’s her,’ said Toby, indicating a girl on the other side of the room.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[transitive]</span> to represent something:</div><ul class=\"examples\"><li><em>Sales targets are indicated on the graph by a vertical dotted line.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[intransitive, transitive]</span> <em>British English</em> to show the direction in which you intend to turn in a vehicle, using lights or your hands <em>SYN signal</em>:</div><ul class=\"examples\"><li><em>Don’t forget to indicate before you pull out.</em></li></ul></div>","3616":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧di‧ca‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪndɪˈkeɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a sign, remark, event etc that shows what is happening, what someone is thinking or feeling, or what is true ► see thesaurus at sign</div><ul class=\"examples\"><li><strong><em>indication of</strong>: Dark green leaves are a good indication of healthy roots. / He gave no indication at all of his own feelings.</em></li><li><em>Could you give me some indication as to when I am likely to receive a reply?</em></li><li><strong><em>indication (that)</strong>: Taking a career history along with you will be a clear indication that you are well organized. / Indications are that the situation hasn’t improved much.</em></li><li><em>There is every indication (=there are very clear signs) that it is true.</em></li></ul></div>","3617":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧dic‧a‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈdɪkətɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>be indicative of something</strong> to be a clear sign that a particular situation exists or that something is likely to be true:</div><ul class=\"examples\"><li><em>This behaviour is indicative of her whole attitude, I’m afraid.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>technical</em> an indicative verb form is used for making statements</div></div>","3618":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧di‧ca‧tor</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪndəkeɪtə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> something that can be regarded as a sign of something else <em>SYN sign</em>: ► see thesaurus at sign</div><ul class=\"examples\"><li><em>All the main economic indicators suggest that trade is improving.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>British English</em> one of the lights on a car that flash to show which way the car is turning SYN turn signal<em>American English</em></div><div class=\"sense\"><span class=\"snum\">3</span> a pointer on a machine that shows the temperature, pressure, speed etc</div></div>","3619":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧dict</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈdaɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to officially charge someone with a criminal offence ► see thesaurus at accuse</div><ul class=\"examples\"><li><strong><em>indict somebody for something</strong>: He was indicted for vehicular homicide in 1987.</em></li></ul></div>","3620":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧dict‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈdaɪtmənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>be an indictment of something</strong> to be a very clear sign that a system, method etc is very bad or very wrong:</div><ul class=\"examples\"><li><em>The fact that these children cannot read is a damning indictment of our education system.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> <em>especially American English</em> <em>law</em> an official written statement charging someone with a criminal offence</div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> <em>especially American English</em> <em>law</em> the act of officially charging someone with a criminal offence</div></div>","3621":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧dif‧fer‧ence</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈdɪfərəns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">lack of interest or concern</div><ul class=\"examples\"><li><strong><em>indifference to</strong>: his apparent indifference to material luxuries</em></li><li><em>Whether you stay or leave is a matter of total indifference to me (=I do not care).</em></li></ul></div>","3622":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧dif‧fer‧ent</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈdɪfərənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not at all interested in someone or something</div><ul class=\"examples\"><li><strong><em>indifferent to</strong>: Sarah was absolutely indifferent to him, and it hurt.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> not particularly good <em>SYN mediocre</em>:</div><ul class=\"examples\"><li><em>an indifferent cook</em></li></ul></div>","3623":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧di‧rect</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪndəˈrekt◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not directly caused by something <em>OPP direct</em>:</div><ul class=\"examples\"><li><em>Losing weight is an indirect result of smoking cigarettes.</em></li><li><em>The indirect effects of climate change may be profound.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an indirect way to a place is not the straightest way <em>OPP direct</em>:</div><ul class=\"examples\"><li><em>They took an indirect route, avoiding the town centre.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> not saying or showing something in a clear definite way <em>OPP direct</em>:</div><ul class=\"examples\"><li><em>George’s comments were an indirect way of blaming me.</em></li></ul></div>","3624":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧di‧spen‧sa‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪndɪˈspensəbəl◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">someone or something that is indispensable is so important or useful that it is impossible to manage without them <em>SYN essential</em> ► see thesaurus at useful</div><ul class=\"examples\"><li><strong><em>indispensable to</strong>: This book is indispensable to anyone interested in space exploration.</em></li><li><strong><em>indispensable for/in (doing) something</strong>: Meat is not indispensable for maintaining a healthy diet.</em></li><li><em>Mobile phones have become an indispensable part of our lives.</em></li></ul></div>","3625":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧dis‧tin‧guish‧a‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪndɪˈstɪŋɡwɪʃəbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">things that are indistinguishable are so similar that you cannot see any difference between them ► see thesaurus at same</div><ul class=\"examples\"><li><strong><em>indistinguishable from</strong>: an artificial material that is almost indistinguishable from real silk</em></li></ul></div>","3626":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧di‧vid‧u‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪndəˈvɪdʒuəl◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[only before noun]</span> considered separately from other people or things in the same group:</div><ul class=\"examples\"><li><em>Each individual leaf on the tree is different.</em></li><li><em>the needs of the individual customer</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[only before noun]</span> belonging to or intended for one person rather than a group:</div><ul class=\"examples\"><li><em>Children get more individual attention in small classes.</em></li><li><em>You can have the bathroom designed to suit your individual needs.</em></li><li><em>individual portions of jam</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> an individual style, way of doing things etc is different from anyone else’s – usually used to show approval <em>SYN distinctive</em>:</div><ul class=\"examples\"><li><em>a tennis player with a highly individual style</em></li><li><em>a very individual way of dressing</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a person, considered separately from the rest of the group or society that they live in:</div><ul class=\"examples\"><li><em>the rights of the individual</em></li><li><em>Each individual receives two genes, one inherited from each parent.</em></li><li><em>Most churches were built with donations from private individuals (=ordinary people, rather than the government or companies).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a person of a particular kind, especially one who is unusual in some way:</div><ul class=\"examples\"><li><em>a strange-looking individual</em></li></ul></div></div>","3627":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧di‧vid‧u‧al‧i‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪndəvɪdʒuˈæləti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the qualities that make someone or something different from other things or people:</div><ul class=\"examples\"><li><em>We like our staff to show their individuality rather than wear a uniform.</em></li></ul></div>","3628":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧di‧vid‧u‧al‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪndəˈvɪdʒuəli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">separately, not together in a group <em>OPP collectively</em>:</div><ul class=\"examples\"><li><em>The bridegroom thanked them all individually.</em></li><li><em>individually wrapped portions of cheese</em></li></ul></div>","3629":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧door</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪndɔː $ -ɔːr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\">used or happening inside a building <em>OPP outdoor</em>:</div><ul class=\"examples\"><li><em>an indoor swimming pool</em></li><li><em>the world indoor athletics championship</em></li><li><em>Too much central heating can harm indoor plants.</em></li></ul></div>","3630":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧doors</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnˈdɔːz◂ $ -ɔːrz◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">into or inside a building <em>OPP outdoors</em>:</div><ul class=\"examples\"><li><em>Let’s go indoors and have something to eat.</em></li><li><em>It rained all day so we had to stay indoors.</em></li></ul></div>","3631":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧duce</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈdjuːs $ ɪnˈduːs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>formal</em> to persuade someone to do something, especially something that does not seem wise</div><ul class=\"examples\"><li><strong><em>induce somebody to do something</strong>: Nothing would induce me to vote for him again.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>medical</em> to make a woman give birth to her baby, by giving her a special drug:</div><ul class=\"examples\"><li><em>She had to be induced because the baby was four weeks late.</em></li><li><em>The doctor decided to induce labour.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>formal</em> to cause a particular physical condition:</div><ul class=\"examples\"><li><em>Patients with eating disorders may use drugs to induce vomiting.</em></li><li><strong><em>drug-induced/stress-induced etc</strong>: a drug-induced coma</em></li></ul></div>","3632":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧dulge</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈdʌldʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to let yourself do or have something that you enjoy, especially something that is considered bad for you</div><ul class=\"examples\"><li><strong><em>indulge in</strong>: Most of us were too busy to indulge in heavy lunchtime drinking. / Eva had never been one to indulge in self-pity.</em></li><li><strong><em>indulge yourself</strong>: Even if you’re dieting, you can indulge yourself (=eat what you want) once in a while.</em></li><li><em>Ray has enough money to indulge his taste for expensive wines.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to let someone have or do whatever they want, even if it is bad for them:</div><ul class=\"examples\"><li><em>His mother spoiled him, indulging his every whim.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive]</span> to take part in an activity, especially an illegal one</div><ul class=\"examples\"><li><strong><em>indulge in</strong>: Women do not indulge in crime to the same extent as men.</em></li></ul></div>","3633":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧dus‧tri‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈdʌstriəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> relating to industry or the people working in it</div><ul class=\"examples\"><li><strong><em>industrial production/output</strong>: Industrial production has risen by 0.5% since November.</em></li><li><strong><em>industrial development/growth</strong>: rapid post-war industrial development</em></li><li><strong><em>industrial conflict/dispute/unrest</strong> (=disagreement between workers and their employers): Last year 1.3 million workers took part in industrial disputes.</em></li><li><strong><em>industrial accident/injury</strong> (=happening at work)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> having many industries</div><ul class=\"examples\"><li><strong><em>industrial countries/nations/states</strong>: a meeting of the world’s major industrial nations</em></li><li><strong><em>industrial area/zone</strong>: pollution in industrial areas</em></li><li><em>By 1900, Britain was a mainly industrial society.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> of the type used in industry:</div><ul class=\"examples\"><li><em>cleaning products that are for industrial use only (=not to be used at home)</em></li></ul></div>","3634":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧dus‧tri‧al‧ist</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈdʌstriəlɪst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a person who owns or runs a factory or industrial company</div></div>","3635":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧dus‧tri‧al‧ized</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈdʌstriəlaɪzd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">an industrialized country or place has a lot of factories, mines etc</div></div>","3636":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧dus‧try</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪndəstri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\">(plural industries)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> the large-scale production of goods or of substances such as coal and steel:</div><ul class=\"examples\"><li><em>This type of software is widely used in industry.</em></li><li><em>workers in manufacturing industry</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> the people who work in industry:</div><ul class=\"examples\"><li><em>an agreement that will be welcomed by both sides of industry (=employers and workers)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> businesses that produce a particular type of thing or provide a particular service:</div><ul class=\"examples\"><li><em>I work in the oil industry.</em></li><li><em>Italy’s thriving tourist industry</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> <em>formal</em> the fact of working hard:</div><ul class=\"examples\"><li><em>Gould is a man of great industry.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[singular]</span> an area of work which has grown too large – used to show disapproval:</div><ul class=\"examples\"><li><em>another book from the Shakespeare industry</em></li></ul></div>","3637":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ef‧fec‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnəˈfektɪv◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">something that is ineffective does not achieve what it is intended to achieve <em>OPP effective</em></div><ul class=\"examples\"><li><strong><em>ineffective in doing something</strong>: The chemical was almost totally ineffective in killing the weeds.</em></li><li><strong><em>ineffective against</strong>: Various drugs have proved ineffective against the virus.</em></li><li><em>an ineffective marketing campaign</em></li></ul></div>","3638":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ef‧fi‧cient</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnəˈfɪʃənt◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">not using time, money, energy etc in the best way <em>OPP efficient</em>:</div><ul class=\"examples\"><li><em>an inefficient use of resources</em></li><li><em>Local government was inefficient.</em></li></ul></div>","3639":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧e‧qual‧i‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnɪˈkwɒləti $ -ˈkwɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span><span class=\"meta-item\">(plural inequalities)</span></div><div class=\"entry-body\"><div class=\"sense\">an unfair situation, in which some groups in society have more money, opportunities, power etc than others <em>OPP equality</em></div><ul class=\"examples\"><li><strong><em>inequality in</strong>: There are inequalities in wealth distribution.</em></li><li><strong><em>inequality of</strong>: inequality of opportunity</em></li><li><strong><em>inequality between</strong>: inequalities between men and women</em></li><li><strong><em>social/gender/racial etc inequality</strong>: a policy that aims to redress racial inequalities</em></li></ul></div>","3640":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ev‧i‧ta‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪˈnevətəbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> certain to happen and impossible to avoid: ► see thesaurus at certain</div><ul class=\"examples\"><li><em>A further escalation of the crisis now seems inevitable.</em></li><li><strong><em>it is inevitable (that)</strong>: It’s inevitable that doctors will make the occasional mistake.</em></li><li><strong><em>inevitable consequence/result</strong>: Disease was an inevitable consequence of poor living conditions.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the inevitable</strong> a situation that is certain to happen:</div><ul class=\"examples\"><li><em>One day the inevitable happened and I got a speeding ticket.</em></li></ul></div>","3641":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ev‧i‧ta‧bly</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪˈnevətəbli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\">used for saying that something is certain to happen and cannot be avoided:</div><ul class=\"examples\"><li><em>The decision will inevitably lead to political tensions.</em></li><li><em><span class=\"gram\">[sentence adverb]</span>: Inevitably, the situation did not please everyone.</em></li></ul></div>","3642":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ex‧pen‧sive</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnɪkˈspensɪv◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">cheap – use this to show approval <em>OPP expensive</em>: ► see thesaurus at cheap</div><ul class=\"examples\"><li><em>a good selection of inexpensive wines</em></li><li><em>Painting is a relatively inexpensive way to enhance your home.</em></li></ul></div>","3643":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ex‧pe‧ri‧enced</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnɪkˈspɪəriənst◂ $ -ˈspɪr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">not having had much experience:</div><ul class=\"examples\"><li><em>inexperienced pilots</em></li></ul></div>","3644":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧fa‧mous</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnfəməs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">well known for being bad or evil: ► see thesaurus at famous</div><ul class=\"examples\"><li><em>an infamous killer</em></li><li><em>Los Angeles’ infamous smog</em></li><li><strong><em>infamous for</strong>: This area is infamous for drugs and prostitution.</em></li></ul></div>","3645":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧fant</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnfənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> <em>formal</em> a baby or very young child: ► see thesaurus at baby → Sudden Infant Death Syndrome</div><ul class=\"examples\"><li><em>An infant’s skin is very sensitive.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>infants</strong> <span class=\"gram\">[plural]</span> children in school in Britain between the ages of four and eight</div></div>","3646":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧fect</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈfekt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to give someone a disease:</div><ul class=\"examples\"><li><em>People with the virus may feel perfectly well, but they can still infect others.</em></li><li><strong><em>infect with</strong>: the number of people infected with HIV</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make something contain something harmful that gives people a disease GRAMMAR Infect is usually passive in this meaning.</div><ul class=\"examples\"><li><strong><em>be infected with something</strong>: Eggs known to be infected with salmonella were allowed to go on sale.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> if a feeling or interest that you have infects other people, it makes them begin to feel the same way or have the same interest:</div><ul class=\"examples\"><li><em>Lucy’s enthusiasm soon infected the rest of the class.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> if a virus infects your computer or disk, it changes or destroys the information in or on it</div></div>","3647":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧fec‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈfekʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a disease that affects a particular part of your body and is caused by bacteria or a virus: ► see thesaurus at illness</div><ul class=\"examples\"><li><em>The baby had an ear infection.</em></li><li><strong><em>infection of/in</strong>: an infection of the bladder</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> when someone is infected by a disease:</div><ul class=\"examples\"><li><em>Always sterilize the needle to prevent infection.</em></li></ul></div>","3648":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧fec‧tious</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈfekʃəs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an infectious illness can be passed from one person to another, especially through the air you breathe:</div><ul class=\"examples\"><li><em>infectious diseases</em></li><li><em>Flu is highly infectious.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who is infectious has an illness and could pass it to other people</div><div class=\"sense\"><span class=\"snum\">3</span> infectious feelings or laughter spread quickly from one person to another:</div><ul class=\"examples\"><li><em>an infectious smile</em></li><li><em>infectious enthusiasm</em></li></ul></div>","3649":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧fer</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈfɜː $ -ɜːr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle inferred, present participle inferring)</span></div><div class=\"entry-body\"><div class=\"sense\">to form an opinion that something is probably true because of information that you have</div><ul class=\"examples\"><li><strong><em>infer something from something</strong>: A lot can be inferred from these statistics.</em></li><li><strong><em>infer that</strong>: From the evidence, we can infer that the victim knew her killer.</em></li></ul></div>","3650":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧fer‧ence</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnfərəns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> something that you think is true, based on information that you have</div><ul class=\"examples\"><li><strong><em>draw/make inferences (about/from something)</strong>: What inferences have you drawn from this evidence?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> when someone infers something</div><ul class=\"examples\"><li><strong><em>by inference</strong>: He was portrayed as a hero and, by inference, Thompson as the villain.</em></li></ul></div>","3651":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧fe‧ri‧or</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈfɪəriə $ -ˈfɪriər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not good, or not as good as someone or something else <em>OPP superior</em>:</div><ul class=\"examples\"><li><em>I felt very inferior among all those academics.</em></li><li><em>wine of inferior quality</em></li><li><em>inferior goods</em></li><li><strong><em>inferior to</strong>: I always felt slightly inferior to her.</em></li><li><em>Their performance was inferior to that of other teams.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>formal</em> lower in rank <em>OPP superior</em>:</div><ul class=\"examples\"><li><em>an inferior court of law</em></li><li><em>He refused to accept a job of inferior status.</em></li></ul></div>","3652":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧fi‧nite</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnfənət/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> very great in amount or degree:</div><ul class=\"examples\"><li><em>a woman of infinite patience</em></li><li><strong><em>an infinite number/variety of something</strong>: There was an infinite variety of drinks to choose from.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> without limits in space or time <em>OPP finite</em>:</div><ul class=\"examples\"><li><em>The universe is infinite.</em></li></ul></div>","3653":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧fi‧nite‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnfənətli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[+adjective/adverb]</span></span></div><div class=\"entry-body\"><div class=\"sense\">very much – used especially when comparing things:</div><ul class=\"examples\"><li><em>This school is infinitely better than the last one I went to.</em></li><li><em>someone with infinitely more experience</em></li></ul></div>","3654":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧fin‧i‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈfɪnətɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">in grammar, the basic form of a verb, used with ‘to’ in English. In the sentence ‘I want to watch television’, ‘to watch’ is an infinitive.</div></div>","3655":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧fla‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈfleɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a continuing increase in prices, or the rate at which prices increase:</div><ul class=\"examples\"><li><em>Inflation is now at over 16%.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the process of filling something with air</div></div>","3656":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧flict</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈflɪkt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to make someone suffer something unpleasant</div><ul class=\"examples\"><li><strong><em>inflict something on/upon somebody</strong>: The strikes inflicted serious damage on the economy.</em></li><li><em>Detectives warned that the men could inflict serious injury.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>inflict yourself/somebody on somebody</strong> to visit or be with someone when they do not want you – used humorously:</div><ul class=\"examples\"><li><em>Was it really fair to her friends to inflict her nephew on them?</em></li></ul></div>","3657":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧flu‧ence</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnfluəns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the power to affect the way someone or something develops, behaves, or thinks, without using direct force or orders: ► see thesaurus at effect</div><ul class=\"examples\"><li><em>As a scientist, his influence was immense.</em></li><li><strong><em>influence on/over</strong>: the unions’ influence over local politics</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> someone or something that has an influence on other people or things</div><ul class=\"examples\"><li><strong><em>bad/good/positive etc influence (on somebody)</strong>: Gayle’s mother said I was a bad influence on her daughter.</em></li><li><em>For centuries the country remained untouched by outside influences.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>under the influence (of alcohol/drink/drugs etc)</strong> drunk or feeling the effects of a drug</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to affect the way someone or something develops, behaves, thinks etc without directly forcing or ordering them: ► see thesaurus at persuade</div><ul class=\"examples\"><li><em>Marx was strongly influenced by the historian Niebuhr.</em></li><li><strong><em>influence a decision/outcome/choice etc</strong>: Several factors are likely to influence this decision.</em></li><li><strong><em>influence somebody to do something</strong>: What influenced you to take up nursing?</em></li></ul></div></div>","3658":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧flu‧en‧tial</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnfluˈenʃəl◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">having a lot of influence and therefore changing the way people think and behave: ► see thesaurus at powerful</div><ul class=\"examples\"><li><em>He had influential friends.</em></li><li><strong><em>influential in</strong>: Dewey was influential in shaping economic policy.</em></li><li><em>a highly influential art magazine</em></li></ul></div>","3659":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧form</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈfɔːm $ -ɔːrm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to officially tell someone about something or give them information: ► see thesaurus at tell</div><ul class=\"examples\"><li><em>They decided to inform the police</em></li><li><strong><em>inform somebody about/of something</strong>: Please inform us of any change of address as soon as possible.</em></li><li><strong><em>inform somebody (that)</strong>: We regret to inform you that your application has been rejected.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>formal</em> to influence someone’s attitude or opinion:</div><ul class=\"examples\"><li><em>Her experience as a refugee informs the content of her latest novel.</em></li></ul></div>","3660":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧for‧mal</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈfɔːməl $ -ɔːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> relaxed and friendly without being restricted by rules of correct behaviour <em>OPP formal</em>:</div><ul class=\"examples\"><li><em>The atmosphere at work is fairly informal.</em></li><li><em>The two groups met for informal talks.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an informal style of writing or speaking is suitable for ordinary conversations or letters to friends <em>OPP formal</em></div><div class=\"sense\"><span class=\"snum\">3</span> informal clothes are suitable for wearing at home or in ordinary situations <em>SYN casual</em> <em>OPP formal</em></div></div>","3661":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧for‧mant</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈfɔːmənt $ -ɔːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who secretly gives the police, the army etc information about someone else <em>SYN informer</em>:</div><ul class=\"examples\"><li><em>One of the witnesses was a paid informant for the FBI.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>technical</em> someone who gives information about their language, social customs etc to someone who is studying them</div></div>","3662":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧for‧ma‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnfəˈmeɪʃən $ -fər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> facts or details that tell you something about a situation, person, event etc: → inside information at inside3(2) RegisterIn everyday English, in informal contexts, people often use the expression tell someone something rather than using the noun information: I wonder if you could give me some information about your childhood. ➔ I wonder if you could tell me something about your childhood. GRAMMAR: Countable or uncountable?• Information is an uncountable noun and is not used in the plural. You say: · I need some information about hotels. ✗Don’t say: I need some informations about hotels.• Information is always followed by a singular verb: · The information is strictly confidential.• When talking about one fact or detail, you say a piece of information or a bit of information: · He told me an interesting piece of information.</div><ul class=\"examples\"><li><em>I need more information.</em></li><li><strong><em>information that</strong>: We have received information that Grant may have left the country.</em></li><li><strong><em>information about/on</strong>: The book contains information about a wide variety of subjects.</em></li><li><strong><em>my/our etc information is</strong> (=used to say what you know about a situation): My information is that Gary wants to stay with the club.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>American English</em> the telephone service which provides telephone numbers to people who ask for them SYN directory enquiries<em>British English</em></div><div class=\"sense\"><span class=\"snum\">3</span> <strong>for somebody&#x27;s information</strong> used when you provide a document or some information, because you think it may be useful for someone:</div><ul class=\"examples\"><li><em>I&#x27;m attaching a copy of the report for your information.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>For your information...</strong> <em>spoken</em> used when you are telling someone that they are wrong about a particular fact:</div><ul class=\"examples\"><li><em>For your information, I’ve worked as a journalist for six years.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>for information only</strong> written on copies of letters and documents that are sent to someone who needs to know about them but does not have to deal with them</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>too much information!</strong> <em>spoken</em> <em>informal</em> used when someone has just told you details that you think are embarrassing or unpleasant, and you do not want to hear any more:</div><ul class=\"examples\"><li><em>&#x27;I was really ill at the weekend - I had to stay on the toilet all day.&#x27; &#x27;Too much information!&#x27;</em></li></ul></div>","3663":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧for‧ma‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈfɔːmətɪv $ -ɔːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">providing many useful facts or ideas:</div><ul class=\"examples\"><li><em>an informative and entertaining book</em></li></ul></div>","3664":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧formed</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈfɔːmd $ -ɔːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> having a lot of knowledge or information about a particular subject or situation:</div><ul class=\"examples\"><li><em>Informed sources said it was likely that the president would make a televised statement.</em></li><li><strong><em>well-informed/ill-informed</strong>: I became reasonably well-informed about the subject.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>informed decision/choice/judgment etc</strong> a decision etc that is based on knowledge of a subject or situation:</div><ul class=\"examples\"><li><em>Good information is essential if people are to make informed choices about services.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>keep somebody informed</strong> to give someone the latest news and details about a situation:</div><ul class=\"examples\"><li><em>Please keep me fully informed of any developments.</em></li></ul></div>","3665":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧fra‧struc‧ture</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnfrəˌstrʌktʃə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the basic systems and structures that a country or organization needs in order to work properly, for example roads, railways, banks etc:</div><ul class=\"examples\"><li><em>Some countries lack a suitable economic infrastructure.</em></li><li><em>a $65 billion investment package in education, health care and infrastructure</em></li></ul></div>","3666":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧fringe</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈfrɪndʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to do something that is against a law or someone’s legal rights:</div><ul class=\"examples\"><li><em>A backup copy of a computer program does not infringe copyright.</em></li></ul></div>","3667":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ge‧ni‧ous</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈdʒiːniəs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an ingenious plan, idea, or object works well and is the result of clever thinking and new ideas:</div><ul class=\"examples\"><li><em>Many fish have ingenious ways of protecting their eggs from predators.</em></li><li><em>an ingenious device</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who is ingenious is very good at inventing things or at thinking of new ideas</div></div>","3668":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧gre‧di‧ent</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈɡriːdiənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> one of the foods that you use to make a particular food or dish:</div><ul class=\"examples\"><li><em>Combine all the ingredients in a large bowl.</em></li><li><em>The food is home-cooked using fresh ingredients.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a quality you need to achieve something:</div><ul class=\"examples\"><li><em>John has all the ingredients of a great player.</em></li><li><em>Investment in new product development is an essential ingredient of corporate success.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>active ingredient</strong> the substance in a product such as a medicine that causes the product’s intended result:</div><ul class=\"examples\"><li><em>Acetic acid is the chief active ingredient in vinegar.</em></li></ul></div>","3669":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧hab‧it</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈhæbɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">if animals or people inhabit an area or place, they live there <em>SYN live</em>: ► see thesaurus at live</div><ul class=\"examples\"><li><em>The woods are inhabited by many wild animals.</em></li><li><em>inhabited islands</em></li></ul></div>","3670":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧hab‧i‧tant</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈhæbɪtənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">one of the people who live in a particular place:</div><ul class=\"examples\"><li><em>a city of six million inhabitants</em></li></ul></div>","3671":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧her‧ent</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈhɪərənt, -ˈher- $ -ˈhɪr-, -ˈher-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">a quality that is inherent in something is a natural part of it and cannot be separated from it</div><ul class=\"examples\"><li><strong><em>inherent in</strong>: I’m afraid the problems you mention are inherent in the system.</em></li><li><em>Every business has its own inherent risks.</em></li></ul></div>","3672":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧her‧it</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈherɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to receive money, property etc from someone after they have died ► see thesaurus at get</div><ul class=\"examples\"><li><strong><em>inherit something from somebody</strong>: He inherited a fortune from his grandmother.</em></li><li><em>inherited wealth</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> if you inherit a situation, especially one in which problems have been caused by other people, you have to deal with it:</div><ul class=\"examples\"><li><em>The present government inherited a closed, state-dominated economy.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to have the same character or appearance as your parents</div><ul class=\"examples\"><li><strong><em>inherit something from somebody</strong>: Mr. Grass inherited his work ethic from his father.</em></li><li><em>I inherited my mother’s curly hair.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[transitive]</span> to get something that someone else does not want anymore</div><ul class=\"examples\"><li><strong><em>inherit something from somebody</strong>: We inherited the furniture from the previous tenants.</em></li></ul></div>","3673":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧her‧i‧tance</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈherətəns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> money, property etc that you receive from someone who has died:</div><ul class=\"examples\"><li><em>Lucinda has to fight for her life and her inheritance in this gripping novel.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> physical or mental qualities that you inherit from your family:</div><ul class=\"examples\"><li><em>Our genetic inheritance cannot be changed.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> ideas, skills, literature etc from the past that influence people in the present:</div><ul class=\"examples\"><li><em>ideas that have become part of our cultural inheritance</em></li></ul></div>","3674":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧hib‧it</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈhɪbɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to prevent something from growing or developing well:</div><ul class=\"examples\"><li><em>An unhappy family life may inhibit children’s learning.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make someone feel embarrassed or nervous so that they cannot do or say what they want to</div><ul class=\"examples\"><li><strong><em>inhibit somebody from doing something</strong>: Recording the meeting may inhibit people from expressing their real views.</em></li></ul></div>","3675":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧hi‧bi‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnhəˈbɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a feeling of shyness or embarrassment that stops you doing or saying what you really want:</div><ul class=\"examples\"><li><em>She had no inhibitions about saying what she felt.</em></li><li><em>People tend to lose their inhibitions when they’ve drunk a lot of alcohol.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> <em>technical</em> when something is restricted or prevented from happening or developing:</div><ul class=\"examples\"><li><em>a marked inhibition of cell growth</em></li></ul></div>","3676":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧ni‧tial</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪˈnɪʃəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W2 AWL</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\">happening at the beginning <em>SYN first</em>:</div><ul class=\"examples\"><li><em>an initial investment of £5,000</em></li><li><strong><em>initial stage/phase/period</strong>: the initial stages of the disease</em></li><li><em>The initial response has been encouraging.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the first letter of someone’s first name:</div><ul class=\"examples\"><li><em>‘Can I have your initial, Mr Davies?’ ‘It’s G, Mr G Davies.’</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>initials</strong> <span class=\"gram\">[plural]</span> the first letters of all your names in order:</div><ul class=\"examples\"><li><em>His initials are DPH: they stand for David Perry Hallworth.</em></li></ul></div></div>","3677":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧ni‧tial‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪˈnɪʃəli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\">at the beginning:</div><ul class=\"examples\"><li><em>Stan initially wanted to go to medical school.</em></li><li><em>Initially, I thought I would only stay there a year.</em></li></ul></div>","3678":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧ni‧ti‧ate</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪˈnɪʃieɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>formal</em> to arrange for something important to start, such as an official process or a new plan:</div><ul class=\"examples\"><li><em>They have decided to initiate legal proceedings against the newspaper.</em></li><li><em>Intellectuals have initiated a debate on terrorism.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to tell someone about something or show them how to do something</div><ul class=\"examples\"><li><strong><em>initiate somebody into something</strong>: Those kids were initiated into heroin use at a young age.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to introduce someone into an organization, club, group etc, usually with a special ceremony</div><ul class=\"examples\"><li><strong><em>initiate somebody into something</strong>: At the age of thirteen, the boys in the tribe are initiated into manhood.</em></li></ul></div>","3679":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧ni‧tia‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪˈnɪʃətɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[decisions]</strong> <span class=\"gram\">[uncountable]</span> the ability to make decisions and take action without waiting for someone to tell you what to do:</div><ul class=\"examples\"><li><em>I wish my son would show more initiative.</em></li><li><em>Don’t keep asking me for advice. Use your initiative.</em></li><li><em>Lt. Carlos was not obeying orders. He acted on his own initiative (=he was not told what to do).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[plan]</strong> <span class=\"gram\">[countable]</span> an important new plan or process to achieve a particular aim or to solve a particular problem: ► see thesaurus at plan</div><ul class=\"examples\"><li><em>a government initiative to help exporters</em></li><li><em>an education initiative</em></li><li><strong><em>initiative for</strong>: a new initiative for peace in the Middle East</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[control]</strong> <strong>the initiative</strong> if you have or take the initiative, you are in a position to control a situation and decide what to do next:</div><ul class=\"examples\"><li><em>Why don’t you take the initiative and ask him out?</em></li><li><em>Politicians need to seize the initiative from the terrorists.</em></li><li><em>The government must not lose the initiative in the fight against terrorism.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[law]</strong> <span class=\"gram\">[countable]</span> <em>law</em> a process by which ordinary citizens can officially suggest a change in the law by signing a petition</div></div>","3680":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ject</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈdʒekt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to put liquid, especially a drug, into someone’s body by using a special needle</div><ul class=\"examples\"><li><strong><em>inject something into somebody/something</strong>: The drug is injected directly into the base of the spine.</em></li><li><strong><em>inject somebody with something</strong>: I have to inject myself with insulin.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to improve something by adding excitement, interest etc to it</div><ul class=\"examples\"><li><strong><em>inject something into something</strong>: Traditional handbag makers are injecting more fun into their designs. / A market building can inject new life into an area.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to provide more money, equipment etc for something</div><ul class=\"examples\"><li><strong><em>inject something into something</strong>: They need to inject more money into sports facilities.</em></li></ul></div>","3681":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧jec‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈdʒekʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> an act of putting a drug into someone’s body using a special needle → shot:</div><ul class=\"examples\"><li><em>The nurse gave me a tetanus injection.</em></li><li><strong><em>injection of</strong>: an injection of insulin</em></li><li><em>The children hate having injections.</em></li><li><em>The only sure treatment is antibiotics, preferably by injection.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> an addition of money to something in order to improve it</div><ul class=\"examples\"><li><strong><em>injection of</strong>: a massive injection of public funds</em></li><li><em>Our local football club may fold unless it gets a cash injection.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> the act of forcing a liquid into something:</div><ul class=\"examples\"><li><em>a fuel injection system</em></li></ul></div>","3682":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧jure</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪndʒə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to hurt yourself or someone else, for example in an accident or an attack → wound: ► see thesaurus at hurt</div><ul class=\"examples\"><li><em>Angus injured his leg playing rugby.</em></li><li><strong><em>be badly/seriously/critically injured</strong>: Two people have been critically injured in an accident.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>injure somebody’s pride/feelings etc</strong> to say unfair or unpleasant things that hurt someone’s pride, feelings etc RegisterIn everyday English, people usually say hurt rather than injure:· He hurt his leg playing rugby.· He really hurt my feelings.</div></div>","3683":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧jured</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪndʒəd $ -ərd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> having a wound or damage to part of your body → wounded:</div><ul class=\"examples\"><li><em>an injured bird</em></li><li><em>Chelsea have three injured players.</em></li><li><em>Grandpa was badly injured in the war.</em></li><li><em>The car accident left him seriously injured.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the injured</strong> the people who have been hurt → the wounded:</div><ul class=\"examples\"><li><em>Many of the injured are still in a serious condition.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>injured look/expression etc</strong> a look that shows you feel you have been treated unfairly</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>injured pride/feelings etc</strong> a feeling of being upset or offended because you think you have been unfairly treated</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>the injured party</strong> <em>formal</em> the person who has been unfairly treated in a particular situation</div></div>","3684":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ju‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪndʒəri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2 AWL</span><span class=\"meta-item\">(plural injuries)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a wound or damage to part of your body caused by an accident or attack:</div><ul class=\"examples\"><li><em>She was taken to hospital with serious head injuries.</em></li><li><strong><em>injury to</strong>: The driver of the truck suffered injuries to his legs and arms. / Beckham has missed several games through injury (=because of injury). / He’s a lawyer who specializes in personal injury claims.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> <em>law</em> damage to someone’s reputation, career, or feelings</div><ul class=\"examples\"><li><strong><em>injury to</strong>: He says that the allegations caused serious injury to his reputation.</em></li></ul></div>","3685":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧jus‧tice</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈdʒʌstɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a situation in which people are treated very unfairly and not given their rights</div><ul class=\"examples\"><li><strong><em>injustice of</strong>: the injustice of slavery</em></li><li><strong><em>injustice against</strong>: innumerable injustices against the black population</em></li><li><em>The movie deals with injustices suffered by Native Americans.</em></li><li><em>He had developed a deep sense of social injustice.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>do somebody an injustice</strong> to judge someone’s character or abilities unfairly:</div><ul class=\"examples\"><li><em>To say that you are a poor cook is to do yourself an injustice.</em></li></ul></div>","3686":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ɪŋk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a coloured liquid that you use for writing, printing, or drawing:</div><ul class=\"examples\"><li><em>Please write in black ink.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the black liquid in sea creatures such as octopuses and squid</div></div>","3687":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧mate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnmeɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who is being kept in a prison</div></div>","3688":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a small hotel or pub, especially an old one in the countryside ► see thesaurus at hotel</div><div class=\"sense\"><span class=\"snum\">2</span> a word used in the names of some pubs and hotels:</div><ul class=\"examples\"><li><em>We’re staying at the Holiday Inn.</em></li></ul></div>","3689":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧nate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪˈneɪt◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an innate quality or ability is something you are born with:</div><ul class=\"examples\"><li><em>Children have an innate ability to learn language.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an innate belief is something you feel strongly about and are unlikely to change:</div><ul class=\"examples\"><li><em>the innate conservatism of the farming community</em></li></ul></div>","3690":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ner</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> on the inside or close to the centre of something <em>OPP outer</em>:</div><ul class=\"examples\"><li><em>an inner room</em></li><li><em>inner London</em></li><li><em>the inner ear</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> inner thoughts or feelings are ones that you feel strongly but do not always show to other people:</div><ul class=\"examples\"><li><em>Yoga gives me a sense of inner calm.</em></li><li><em>She’ll need great inner strength to get over the tragedy.</em></li><li><em>She never shared her inner thoughts with anyone.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> relating to things which happen or exist but are not easy to see:</div><ul class=\"examples\"><li><em>the inner workings of the film industry</em></li><li><em>the fascinating inner life of a political party</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>inner circle</strong> the few people in an organization, political party etc who control it or share power with its leader:</div><ul class=\"examples\"><li><em>members of the president’s inner circle</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>somebody’s inner voice</strong> thoughts or feelings inside your head which seem to warn or advise you:</div><ul class=\"examples\"><li><em>My inner voice told me to be cautious.</em></li></ul></div>","3691":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧no‧cence</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnəsəns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the fact of being not guilty of a crime <em>OPP guilt</em>:</div><ul class=\"examples\"><li><em>Can you prove your innocence?</em></li><li><strong><em>protest/maintain your innocence</strong> (=say repeatedly that you are not guilty): The prisoners continued to protest their innocence.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> lack of experience of life or of knowledge of the bad things in the world:</div><ul class=\"examples\"><li><em>In our innocence, we believed everything we were told.</em></li><li><em>the innocence of childhood</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>in all innocence</strong> if you do or say something in all innocence, you have no intention of doing harm or of offending anyone</div></div>","3692":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧no‧cent</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnəsənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not guilty of a crime <em>OPP guilty</em>:</div><ul class=\"examples\"><li><em>Nobody would believe that I was innocent.</em></li><li><strong><em>innocent of</strong>: He’s innocent of murder.</em></li><li><em>The court found him innocent and he was released.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>innocent victims/bystanders/people etc</strong> people who get hurt or killed in a war or crime although they are not directly involved in it:</div><ul class=\"examples\"><li><em>Many innocent civilians are among the casualties.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> done or said without intending to harm or offend anyone:</div><ul class=\"examples\"><li><em>He was startled by their angry reaction to his innocent remark.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> not having much experience of the bad things in the world, so that you are easily deceived <em>SYN naive</em>:</div><ul class=\"examples\"><li><em>I was thirteen years old and very innocent.</em></li></ul></div>","3693":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧no‧va‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnəˈveɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a new idea, method, or invention</div><ul class=\"examples\"><li><strong><em>innovation in</strong>: recent innovations in English teaching</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the introduction of new ideas or methods:</div><ul class=\"examples\"><li><em>We must encourage innovation if the company is to remain competitive.</em></li><li><strong><em>innovation in</strong>: We need to encourage innovation in industry.</em></li><li><em>Many people feel bewildered by the speed of technological innovation.</em></li></ul></div>","3694":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧nov‧at‧ive</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnəvətɪv $ ˈɪnəˌveɪtɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an innovative idea or way of doing something is new, different, and better than those that existed before: ► see thesaurus at new</div><ul class=\"examples\"><li><em>an innovative approach to language teaching</em></li><li><em>innovative schemes for recycling waste materials</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> using clever new ideas and methods:</div><ul class=\"examples\"><li><em>an innovative design team</em></li></ul></div>","3695":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧put</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnpʊt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> information that is put into a computer <em>OPP output</em>:</div><ul class=\"examples\"><li><em>If the input data specified it, the file will close and the process terminates.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> ideas, advice, money, or effort that you put into a job or activity in order to help it succeed</div><ul class=\"examples\"><li><strong><em>input into/to</strong>: Farmers contributed most of the input into the survey.</em></li><li><strong><em>input from</strong>: We’ll need input from community nurses.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> <em>technical</em> electrical power that is put into a machine for it to use</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle inputted or input, present participle inputting)</span></div><div class=\"entry-body\"><div class=\"sense\">to put information into a computer <em>OPP output</em></div><ul class=\"examples\"><li><strong><em>be input to something</strong>: The information is input to our computer system.</em></li></ul></div></div>","3696":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧quire</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈkwaɪə $ -ˈkwaɪr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to ask someone for information: ► see thesaurus at ask</div><ul class=\"examples\"><li><em>‘Why are you doing that?’ the boy inquired.</em></li><li><strong><em>inquire about</strong>: I am writing to inquire about your advertisement in ‘The Times’.</em></li><li><strong><em>inquire whether/why/how etc</strong>: The waiter inquired whether we would like to sit near the window.</em></li><li><strong><em>inquire something of somebody</strong>: ‘Where’s the station?’ she inquired of a passer-by.</em></li><li><em>Toby would have liked to inquire further (=ask more questions).</em></li></ul></div>","3697":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧quir‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈkwaɪəri $ ɪnˈkwaɪri, ˈɪŋkwəri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W2</span><span class=\"meta-item\">(plural inquiries)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a question you ask in order to get information ► see thesaurus at question</div><ul class=\"examples\"><li><strong><em>inquiry about</strong>: We’re getting a lot of inquiries about our new London–Rio service.</em></li><li><strong><em>inquiry from</strong>: inquiries from potential applicants</em></li><li><em>I don’t know who sent the gift, but I’ll make some inquiries.</em></li><li><strong><em>help the police with their inquiries<em>British English</em></strong> (=to answer questions about a crime)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the act or process of asking questions in order to get information:</div><ul class=\"examples\"><li><em>On further inquiry, it emerged that Malcolm had not been involved in the incident.</em></li><li><em>The local council set up a committee of inquiry to look into policing arrangements.</em></li><li><strong><em>scientific/intellectual inquiry</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> an official process to find out about something</div><ul class=\"examples\"><li><strong><em>inquiry into</strong>: a judicial inquiry into the deaths</em></li><li><strong><em>launch/set up/hold an inquiry (into something)</strong>: The Civil Aviation Authority has agreed to hold an inquiry into the accident. / The police have launched a murder inquiry. / Parents have called for an independent inquiry into the accident.</em></li></ul></div>","3698":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧sane</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈseɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>informal</em> completely stupid or crazy, often in a way that is dangerous:</div><ul class=\"examples\"><li><em>That’s an insane risk.</em></li><li><em>The whole idea sounds absolutely insane to me.</em></li><li><em>Why did you do that? Have you gone insane?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who is insane is permanently and seriously mentally ill so that they cannot live in normal society:</div><ul class=\"examples\"><li><em>The killer was declared criminally insane.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>the insane</strong> people who are mentally ill:</div><ul class=\"examples\"><li><em>a hospital for the insane</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>drive somebody insane</strong> <em>informal</em> to make someone feel more and more annoyed or angry, usually over a long period of time <em>SYN drive somebody mad</em>:</div><ul class=\"examples\"><li><em>My little brother’s been driving me insane all weekend.</em></li></ul></div>","3699":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧scrip‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈskrɪpʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a piece of writing inscribed on a stone, in the front of a book etc:</div><ul class=\"examples\"><li><em>a Latin inscription on the memorial stone</em></li></ul></div>","3700":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧sect</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnsekt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a small creature such as a fly or ant, that has six legs, and sometimes wings:</div><ul class=\"examples\"><li><em>an insect bite</em></li><li><em>flying insects</em></li><li><em>Don’t forget to bring insect repellent (=a chemical to keep insects away).</em></li></ul></div>","3701":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧se‧cure</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnsɪˈkjʊə◂ $ -ˈkjʊr◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not feeling at all confident about yourself, your abilities, or your relationships with people ► see thesaurus at confident</div><ul class=\"examples\"><li><strong><em>insecure about</strong>: She’s very insecure about her appearance.</em></li><li><em>She felt lonely and insecure away from her family.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a job, investment etc that is insecure does not give you a feeling of safety, because it might be taken away or lost at any time:</div><ul class=\"examples\"><li><em>Many of them work in low-paid insecure jobs.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a building or structure that is insecure is not safe, because it could fall down</div></div>","3702":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧sert</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈsɜːt $ -ɜːrt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to put something inside or into something else</div><ul class=\"examples\"><li><strong><em>insert something in/into/between something</strong>: His hand shook slightly as he inserted the key into the lock.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to add something to the middle of a document or piece of writing</div><ul class=\"examples\"><li><strong><em>insert something in/into/between something</strong>: His manager inserted a new clause into his contract. / Insert your comments in the space below.</em></li></ul></div>","3703":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧side</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈsaɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[container]</strong> in or into a container or other closed space so as to be completely covered or surrounded <em>OPP outside</em>:</div><ul class=\"examples\"><li><em>The jewels were locked away inside the safe.</em></li><li><em>I sent the money inside an envelope addressed to Ann.</em></li><li><em>Carl picked up the book and stuffed it inside his jacket.</em></li><li><em>Her car was locked and the keys were inside.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[building/room]</strong> in or into a building or room <em>OPP outside</em>:</div><ul class=\"examples\"><li><em>It’s raining. We’ll have to go inside.</em></li><li><em>She could hear voices inside, but no one came to the door.</em></li><li><em>Mail was piled up just inside the doorway.</em></li><li><em>The sound was coming from inside the house.</em></li><li><strong><em>inside of<em>American English</em></strong>: There were 20 people packed inside of her dorm room.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[country/area]</strong> in a country or area – used when you want to emphasize that something is happening there and not in other places <em>OPP outside</em>:</div><ul class=\"examples\"><li><em>Very little is known of events inside this mysterious country.</em></li><li><em>The guerrillas were said to be operating from bases inside the war zone.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[organization]</strong> if someone is inside a group or organization, they are part of it <em>OPP outside</em>:</div><ul class=\"examples\"><li><em>women’s influence inside the party</em></li><li><em>The information comes from sources inside the company.</em></li><li><em>Discussions should involve local people both inside and outside the school.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[head/mind]</strong> if something happens inside you, or inside your head or mind, it is part of what you think and feel, especially when you do not express it:</div><ul class=\"examples\"><li><em>You just don’t understand how I feel inside!</em></li><li><em>Steve’s a strange guy – you never know what’s going on inside his head.</em></li><li><em>Anger bubbled up deep inside her.</em></li><li><strong><em>inside of<em>American English</em></strong>: Something inside of me told me not to trust him.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[body]</strong> in your body:</div><ul class=\"examples\"><li><em>She could feel the baby kicking inside her.</em></li><li><em>You’ll feel better once you’ve got a good meal inside you (=after you have eaten something).</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[time]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> in less than a particular amount of time:</div><ul class=\"examples\"><li><em>A full report is expected inside three months.</em></li><li><strong><em>inside the hour/month etc</strong> (=before an hour, month etc has passed): We’ll be back inside the hour.</em></li><li><strong><em>inside of<em>especially American English</em></strong>: Our aim is to get the whole job finished inside of a week.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> less than a particular amount of time <em>OPP outside</em>:</div><ul class=\"examples\"><li><em>Jonson’s time of 9.3 seconds was just inside the world record.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[prison]</strong> <em>informal</em> in prison:</div><ul class=\"examples\"><li><em>My boyfriend’s been inside for a year.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧side</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈsaɪd, ˈɪnsaɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>the inside</strong> the inner part of something, which is surrounded or hidden by the outer part <em>OPP the outside</em></div><ul class=\"examples\"><li><strong><em>on the inside</strong>: The apple’s rotten on the inside.</em></li><li><strong><em>inside of</strong>: condensation on the inside of the window</em></li><li><em>The door had been locked from the inside.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>inside out</strong> with the usual outside parts on the inside:</div><ul class=\"examples\"><li><em>You’ve got that jumper inside out.</em></li><li><em>Her umbrella blew inside out.</em></li><li><em>I always turn my jeans inside out to wash them.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>turn a room/building etc inside out</strong> to search a place very thoroughly by moving everything that is in it:</div><ul class=\"examples\"><li><em>The drug squad turned the apartment inside out.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>know something inside out</strong> <em>British English</em>, know something inside and out<em>American English</em> to know something in great detail:</div><ul class=\"examples\"><li><em>She knows her subject inside out.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>on the inside</strong> someone who is on the inside is a member of a group or an organization:</div><ul class=\"examples\"><li><em>Someone on the inside must have helped with the robbery.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>on the inside</strong> <em>British English</em> if a car passes another car on the inside, it passes on the side that is away from the driver</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>somebody’s inside/insides</strong> <em>informal</em> someone’s stomach:</div><ul class=\"examples\"><li><em>My insides are beginning to complain about the lack of food.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧side</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnsaɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in or facing the inner part of something:</div><ul class=\"examples\"><li><em>the inside pages of the newspaper</em></li><li><em>the inside pocket of his jacket</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>inside information/the inside story etc</strong> information that is available only to people who are part of a particular group or organization:</div><ul class=\"examples\"><li><em>Police believe the robbers may have had inside information.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>the inside lane</strong> <em>British English</em> the lane that is furthest away from the middle of the road <em>OPP outside lane</em></div></div></div>","3704":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧sight</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnsaɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a sudden clear understanding of something or part of something, especially a complicated situation or idea</div><ul class=\"examples\"><li><strong><em>insight into</strong>: The article gives us a real insight into the causes of the present economic crisis. / The research provides new insights into the way we process language.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the ability to understand and realize what people or situations are really like:</div><ul class=\"examples\"><li><em>a woman of great insight</em></li></ul></div>","3705":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧sig‧nif‧i‧cant</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnsɪɡˈnɪfɪkənt◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">too small or unimportant to consider or worry about <em>SYN trivial</em>: ► see thesaurus at unimportant</div><ul class=\"examples\"><li><em>You realize that your problems are insignificant in comparison.</em></li><li><strong><em>insignificant number/amount</em></strong></li></ul></div>","3706":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧sin‧cere</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnsɪnˈsɪə◂ $ -ˈsɪr◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">pretending to be pleased, sympathetic etc, especially by saying nice things, but not really meaning what you say:</div><ul class=\"examples\"><li><em>an insincere smile</em></li><li><em>an offer which she knew to be impractical and insincere</em></li></ul></div>","3707":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧sist</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈsɪst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to say firmly and often that something is true, especially when other people think it may not be true</div><ul class=\"examples\"><li><strong><em>insist (that)</strong>: Mike insisted that he was right. / His friends insisted he had no connection with drugs.</em></li><li><strong><em>insist on something</strong>: She kept insisting on her innocence.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to demand that something should happen:</div><ul class=\"examples\"><li><em>Stay for supper – I insist!</em></li><li><strong><em>insist (that) somebody should do something</strong>: They insisted that everyone should come to the party. / He insisted I should take a taxi.</em></li><li><strong><em>insist on something</strong>: We insist on the highest standards of cleanliness in the hotel.</em></li><li><strong><em>insist on/upon doing something</strong>: He insisted upon checking everything himself.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>if you insist</strong> <em>spoken</em> used when agreeing to do something that you do not really want to do:</div><ul class=\"examples\"><li><em>‘Why don’t you call them up today?’ ‘Oh, if you insist!’</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>insist on doing something</strong> to keep doing something, especially something that is inconvenient or annoying:</div><ul class=\"examples\"><li><em>She will insist on washing her hair just when I want to have a bath.</em></li></ul></div>","3708":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧spect</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈspekt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to examine something carefully in order to find out more about it or to find out what is wrong with it: ► see thesaurus at examine</div><ul class=\"examples\"><li><em>I got out of the car to inspect the damage.</em></li><li><em>Police inspected the scene and interviewed all the staff.</em></li><li><strong><em>inspect something for something</strong>: The police will inspect the venue for safety.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make an official visit to a building, organization etc to check that everything is satisfactory and that rules are being obeyed: ► see thesaurus at check RegisterIn everyday English, people usually say take a look at something or someone or, in British English, have a look at something or someone rather than inspect something or someone:· Can I take a look at your ticket, please?</div><ul class=\"examples\"><li><em>The building is regularly inspected by the fire-safety officer.</em></li><li><em>General Allenby arrived to inspect the troops.</em></li></ul></div>","3709":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧spec‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈspekʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an official visit to a building or organization to check that everything is satisfactory and that rules are being obeyed</div><ul class=\"examples\"><li><strong><em>inspection of</strong>: regular inspections of the prison</em></li><li><em>An inspection was carried out at the school.</em></li><li><strong><em>tour of inspection</strong> (=an official visit to inspect something)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a careful examination of something to find out more about it or to check for anything wrong</div><ul class=\"examples\"><li><strong><em>for inspection</strong>: Copies of the documents are available for inspection (=people can look at them) at local libraries.</em></li><li><strong><em>(on) close/closer inspection</strong> (=when looked at in detail): However, on closer inspection, a number of problems emerged. / Close inspection of the plane’s engines revealed several small defects.</em></li></ul></div>","3710":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧spec‧tor</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈspektə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an official whose job is to check that something is satisfactory and that rules are being obeyed:</div><ul class=\"examples\"><li><em>ticket inspectors</em></li><li><em>a Health and Safety inspector</em></li><li><em>Standards of discipline at the school were strongly criticized in the inspector’s report.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a police officer of middle rank: → chief inspector</div><ul class=\"examples\"><li><em>Inspector Blake</em></li></ul></div>","3711":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧spi‧ra‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnspəˈreɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a good idea about what you should do, write, say etc, especially one which you get suddenly: ► see thesaurus at idea</div><ul class=\"examples\"><li><em>The Malvern Hills have provided inspiration for many artists and musicians over the decades.</em></li><li><em>He raised his eyes to the altar as if seeking inspiration.</em></li><li><em>He draws inspiration from ordinary scenes.</em></li><li><em>Mary Quant’s inspiration comes from the glam style of the seventies.</em></li><li><em>He had a sudden flash of inspiration.</em></li><li><em>He has always been a source of inspiration for me.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a person, experience, place etc that gives you new ideas for something you do:</div><ul class=\"examples\"><li><em>The seascapes of Cape Cod were her inspiration.</em></li><li><strong><em>inspiration for/behind</strong>: He was the inspiration for Wordsworth’s poem ‘The Old Huntsman’.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be an inspiration to somebody</strong> to make someone feel encouraged to be as good, successful etc as possible:</div><ul class=\"examples\"><li><em>People like Tara are an inspiration to us all.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>under the inspiration of somebody</strong> used to say who made a person or group want to do something:</div><ul class=\"examples\"><li><em>the spread of improved nursing under the inspiration of Florence Nightingale</em></li></ul></div>","3712":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧spire</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈspaɪə $ -ˈspaɪr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to encourage someone by making them feel confident and eager to do something:</div><ul class=\"examples\"><li><em>We need someone who can inspire the team.</em></li><li><strong><em>inspire somebody to do something</strong>: He inspired many young people to take up the sport.</em></li><li><strong><em>inspire somebody to something</strong>: I hope this success will inspire you to greater efforts.</em></li><li><em>Inspired by the sunny weather, I decided to explore the woods.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make someone have a particular feeling or react in a particular way:</div><ul class=\"examples\"><li><em>Gandhi’s quiet dignity inspired great respect.</em></li><li><strong><em>inspire confidence</strong> (=make people feel confident because they trust your ability): His driving hardly inspires confidence. / The hospital’s record does not inspire confidence.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to give someone the idea for something, especially a story, painting, poem etc:</div><ul class=\"examples\"><li><em>The story was inspired by a chance meeting with an old Russian duke.</em></li><li><em>a range of designs inspired by wild flowers</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>technical</em> to breathe in</div></div>","3713":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧stall</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈstɔːl $ -ˈstɒːl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to put a piece of equipment somewhere and connect it so that it is ready to be used:</div><ul class=\"examples\"><li><em>They’ve installed the new computer network at last.</em></li><li><em>Security cameras have been installed in the city centre.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to add new software to a computer so that it is ready to be used <em>OPP uninstall</em>:</div><ul class=\"examples\"><li><em>We’ve installed new anti-virus software.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>formal</em> to put someone in an important job or position, especially with a ceremony:</div><ul class=\"examples\"><li><em>Churchill was installed as Chancellor of the university.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>install yourself in/at etc</strong> to settle somewhere as if you are going to stay for a long time</div></div>","3714":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧stal‧la‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnstəˈleɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> when someone fits a piece of equipment somewhere:</div><ul class=\"examples\"><li><em>the installation and maintenance of alarm systems</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a piece of equipment that has been fitted in its place:</div><ul class=\"examples\"><li><em>The whole computer installation was nearly new.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a place where industrial or military equipment, machinery etc has been put:</div><ul class=\"examples\"><li><em>nuclear installations</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> a piece of modern art which can include objects, light, sound etc</div><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[uncountable]</span> <em>formal</em> the ceremony of putting someone in an important job or position:</div><ul class=\"examples\"><li><em>the installation of the new bishop</em></li></ul></div>","3715":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧stance</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnstəns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>for instance</strong> for example:</div><ul class=\"examples\"><li><em>We need to rethink the way we consume energy. Take, for instance, our approach to transport.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> an example of a particular kind of situation ► see thesaurus at example</div><ul class=\"examples\"><li><strong><em>instance of</strong>: They came across many instances of discrimination.</em></li><li><strong><em>instance where/when</strong>: instances where safety regulations have been breached</em></li><li><em>In this instance I think she was mistaken.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>in the first instance</strong> at the beginning of a series of actions:</div><ul class=\"examples\"><li><em>Anyone wishing to join the society should apply in the first instance to the secretary.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>at somebody’s instance</strong> <em>formal</em> because of someone’s wish or request</div></div>","3716":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧stant</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnstənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[usually before noun]</span> happening or produced immediately <em>SYN immediate</em>:</div><ul class=\"examples\"><li><em>an instant success</em></li><li><em>a system that provides instant access to client information</em></li><li><em>The women took an instant dislike to one another.</em></li><li><em>The programme brought an instant response.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[only before noun]</span> instant food, coffee etc is in the form of powder and prepared by adding hot water:</div><ul class=\"examples\"><li><em>instant coffee</em></li><li><em>instant soup</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable usually singular]</span> a moment:</div><ul class=\"examples\"><li><em>She caught his eye for an instant.</em></li><li><em>When the rain started, the crowd vanished in an instant (=immediately).</em></li><li><strong><em>instant of</strong>: an instant of panic</em></li><li><em>She stepped towards the door and, in that very same instant, the doorbell rang.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the instant (that)</strong> as soon as something happens:</div><ul class=\"examples\"><li><em>The instant I saw him, I knew he was the man from the restaurant.</em></li><li><em>Jen burst out laughing the instant she walked in.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>this instant</strong> <em>spoken</em> used when telling someone, especially a child, to do something immediately <em>SYN now</em>:</div><ul class=\"examples\"><li><em>Come here this instant!</em></li></ul></div></div>","3717":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧stant‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnstəntli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">immediately: ► see thesaurus at immediately</div><ul class=\"examples\"><li><em>All four victims died instantly.</em></li><li><em>The information was instantly available.</em></li></ul></div>","3718":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧stead</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈsted/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>instead of somebody/something</strong> used to say what is not used, does not happen etc, when something else is used, happens etc:</div><ul class=\"examples\"><li><em>You probably picked up my keys instead of yours.</em></li><li><em>Could I have tuna instead of ham?</em></li><li><em>Instead of being annoyed, he seemed quite pleased.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to say what is done, when you have just said that a particular thing is not done:</div><ul class=\"examples\"><li><em>Geoff didn’t study law. Instead, he decided to become an actor.</em></li><li><em>If Jo can’t attend the meeting, I could go instead.</em></li></ul></div>","3719":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧stinct</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnstɪŋkt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a natural tendency to behave in a particular way or a natural ability to know something, which is not learned → intuition</div><ul class=\"examples\"><li><strong><em>instinct for</strong>: Animals have a natural instinct for survival.</em></li><li><strong><em>instinct to do something</strong>: the human instinct to form relationships</em></li><li><strong><em>by instinct</strong>: Birds build nests by instinct.</em></li><li><strong><em>sexual/maternal/survival instinct</em></strong></li><li><em>Her instinct told her that something was wrong.</em></li><li><strong><em>somebody’s first instinct</strong> (=what someone feels like doing first when something happens): His first instinct was to rush back to Isobel.</em></li></ul></div>","3720":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧stinc‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈstɪŋktɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">based on instinct and not involving thought:</div><ul class=\"examples\"><li><em>a mother’s instinctive love</em></li></ul></div>","3721":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧sti‧tute</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnstɪtjuːt $ -tuːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">an organization that has a particular purpose such as scientific or educational work, or the building where this organization is based → academy:</div><ul class=\"examples\"><li><em>research institutes</em></li><li><strong><em>institute of/for</strong>: the Institute for Space Studies</em></li></ul></div>","3722":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧sti‧tu‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnstɪˈtjuːʃən $ -ˈtuː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a large organization that has a particular kind of work or purpose ► see thesaurus at organization</div><ul class=\"examples\"><li><strong><em>financial/educational/research etc institution</strong>: the government and other political institutions</em></li><li><em>powerful institutions such as world banks</em></li><li><em>the Institution of Electrical Engineers</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> an important system of organization in society that has existed for a long time:</div><ul class=\"examples\"><li><em>social institutions such as the family and religion</em></li><li><strong><em>the institution of marriage/monarchy etc</strong>: The scandal threatened to undermine the institution of the presidency.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a building that people are sent to when they need to be looked after, for example old people or children with no parents – often used to show disapproval:</div><ul class=\"examples\"><li><em>I was determined not to put my mother in an institution.</em></li><li><em>a mental institution (=for the mentally ill)</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[uncountable]</span> when something is started or introduced, especially something relating to the law or politics</div><ul class=\"examples\"><li><strong><em>institution of</strong>: the institution of divorce proceedings</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be an institution</strong> if a person, place, event etc is an institution, they have been an important part of a place for a very long time – often used humorously:</div><ul class=\"examples\"><li><em>The British pub isn’t just somewhere to drink – it’s an institution.</em></li></ul></div>","3723":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧sti‧tu‧tion‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnstəˈtjuːʃənəl $ -ˈtuː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[usually before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> relating to an institution:</div><ul class=\"examples\"><li><em>children in institutional care</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> institutional attitudes and behaviour have existed for a long time in an organization and have become accepted as normal even though they are bad:</div><ul class=\"examples\"><li><em>accusations of institutional racism in the police force</em></li></ul></div>","3724":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧struct</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈstrʌkt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to officially tell someone what to do → order ► see thesaurus at order</div><ul class=\"examples\"><li><strong><em>instruct somebody to do something</strong>: His secretary was instructed to cancel all his engagements.</em></li><li><strong><em>instruct (somebody) that</strong>: The judge immediately instructed that Beattie be released.</em></li><li><em>Eva went straight to the hotel, as instructed (=as she had been told).</em></li><li><strong><em>instruct somebody what to do</strong>: He had instructed the slaves what to say when questioned.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>formal</em> to teach someone something, or show them how to do something ► see thesaurus at teach</div><ul class=\"examples\"><li><strong><em>instruct somebody in something</strong>: Greater effort is needed to instruct children in road safety.</em></li><li><strong><em>instruct somebody how to do something</strong>: Employees are instructed how to make a complaint.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>British English</em> <em>formal</em> to officially tell someone about something GRAMMAR Instruct is usually passive in this meaning.</div><ul class=\"examples\"><li><strong><em>be instructed that</strong>: I was instructed that £20,000 had been paid into my account.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>British English</em> <em>law</em> to employ a lawyer to represent you in court</div></div>","3725":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧struc‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈstrʌkʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>instructions</strong> <span class=\"gram\">[plural]</span> the written information that tells you how to do or use something → directions:</div><ul class=\"examples\"><li><em>Press ‘Enter’ and follow the on-screen instructions.</em></li><li><strong><em>instruction for</strong>: Both products come with instructions for use.</em></li><li><strong><em>instructions on (how to do) something</strong>: Are there any instructions on how to plant the trees?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable usually plural]</span> a statement telling someone what they must do → orders</div><ul class=\"examples\"><li><strong><em>instructions to do something</strong>: He had specific instructions to check everyone’s identity cards.</em></li><li><strong><em>instructions that</strong>: Mrs Edwards gave instructions that she was not to be disturbed.</em></li><li><strong><em>on somebody’s instructions</strong> (=having been told by someone to do something): On the landlord’s instructions, the barmaid refused to serve him.</em></li><li><em>My instructions are (=I have been told) to give the package to him personally.</em></li><li><em>Make sure you carry out the doctor’s instructions.</em></li><li><strong><em>be under instruction to do something</strong> (=to have been told to do something): The police were under instruction to fire if necessary.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> <em>formal</em> teaching that you are given in a particular skill or subject:</div><ul class=\"examples\"><li><em>religious instruction</em></li><li><em>driving instruction</em></li><li><strong><em>instruction in</strong>: The school gives instruction in first aid.</em></li><li><strong><em>under instruction</strong> (=being taught): This group of trainees is still under instruction.</em></li></ul></div>","3726":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧struc‧tor</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈstrʌktə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who teaches a sport or practical skill: ► see thesaurus at teacher</div><ul class=\"examples\"><li><em>a driving instructor</em></li><li><em>ski instructors</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>American English</em> someone who teaches in an American college or university and who has a rank below assistant professor:</div><ul class=\"examples\"><li><em>a social studies instructor</em></li></ul></div>","3727":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧stru‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnstrəmənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[tool]</strong> a small tool used in work such as science or medicine:</div><ul class=\"examples\"><li><em>surgical instruments</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[music]</strong> an object used for producing music, such as a piano or violin <em>SYN musical instrument</em> → instrumental, instrumentalist:</div><ul class=\"examples\"><li><em>electronic instruments</em></li><li><strong><em>brass/wind/percussion/stringed etc instrument</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[for measuring]</strong> a piece of equipment for measuring and showing distance, speed, temperature etc:</div><ul class=\"examples\"><li><em>a failure of the flight instruments</em></li><li><em>sensitive earthquake-detecting instruments</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[method]</strong> <span class=\"gram\">[usually singular]</span> something or someone that is used to get a particular result</div><ul class=\"examples\"><li><strong><em>instrument of</strong>: Interest rates are an important instrument of economic policy.</em></li><li><strong><em>instrument for (doing) something</strong>: Good management should be an instrument for innovation.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[for hurting]</strong> something that is used to hit or hurt someone:</div><ul class=\"examples\"><li><em>Death was due to a blow on the head with a blunt instrument.</em></li><li><strong><em>instrument of torture</strong> (=an object used to make people suffer pain until they give information)</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>instrument of fate/God</strong> <em>literary</em> someone or something that is used by a power beyond our control</div></div>","3728":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧suf‧fi‧cient</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnsəˈfɪʃənt◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">not enough, or not great enough:</div><ul class=\"examples\"><li><em>Insufficient resources have been devoted to the health service.</em></li><li><strong><em>insufficient for</strong>: His salary was insufficient for their needs.</em></li><li><strong><em>insufficient (something) to do something</strong>: The heating is insufficient to kill the bacteria. / At the moment, there’s insufficient evidence to arrest anyone.</em></li></ul></div>","3729":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧sult</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈsʌlt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to offend someone by saying or doing something they think is rude:</div><ul class=\"examples\"><li><em>Nobody insults my family and gets away with it!</em></li><li><em>I hope Andy won’t be insulted if I don’t come.</em></li><li><strong><em>insult somebody by doing something</strong>: They insult us by ignoring our complaints.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>insult somebody’s intelligence</strong> to say or do something that suggests you think someone is stupid:</div><ul class=\"examples\"><li><em>I won’t insult your intelligence by lying. Yes, I told him.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧sult</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnsʌlt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a remark or action that is offensive or deliberately rude:</div><ul class=\"examples\"><li><em>She was shouting insults at her boyfriend.</em></li><li><em>$200 for all that work? It’s an insult.</em></li><li><em>Their offer was so low I took it as an insult (=thought it was meant to be an insult).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be an insult to somebody’s intelligence</strong> to offend someone by being too simple or stupid:</div><ul class=\"examples\"><li><em>Some advertising is an insult to our intelligence.</em></li></ul></div></div>","3730":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧sult‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈsʌltɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">very rude and offensive to someone: ► see thesaurus at rude</div><ul class=\"examples\"><li><em>insulting remarks</em></li><li><strong><em>insulting to</strong>: Sexist language is insulting to women.</em></li></ul></div>","3731":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧sur‧ance</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈʃʊərəns $ -ˈʃʊr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> an arrangement with a company in which you pay them money, especially regularly, and they pay the costs if something bad happens, for example if you become ill or your car is damaged → assurance, third party insurance: → life insurance</div><ul class=\"examples\"><li><em>Your father took out insurance to cover the mortgage.</em></li><li><strong><em>health/car/travel etc insurance</em></strong></li><li><strong><em>insurance against</strong>: insurance against loss of income due to unemployment</em></li><li><strong><em>insurance on/for</strong>: Do you have insurance on your house and its contents?</em></li><li><strong><em>claim (for) something on your insurance</strong> (=get an insurance company to pay for something): We can probably claim the damage on our insurance.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the business of providing insurance:</div><ul class=\"examples\"><li><em>My brother works in insurance.</em></li><li><strong><em>insurance company/group etc</strong>: the insurance industry</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> <em>British English</em> the money that you pay regularly to an insurance company <em>SYN insurance premium</em></div><ul class=\"examples\"><li><strong><em>insurance on</strong>: How much is the insurance on your car?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[singular, uncountable]</span> protection against something bad happening</div><ul class=\"examples\"><li><strong><em>insurance against</strong>: An extra lock on the door is an added insurance against burglars.</em></li></ul></div>","3732":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧sure</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈʃʊə $ -ˈʃʊr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to buy insurance so that you will receive money if something bad happens to you, your family, your possessions etc:</div><ul class=\"examples\"><li><em>Have you insured the contents of your home?</em></li><li><strong><em>insure (something/somebody) against loss/damage/theft/sickness etc</strong>: It is wise to insure your property against storm damage.</em></li><li><strong><em>insure something for £1,000/$2,000 etc</strong>: You should insure the painting for at least £100,000.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to provide insurance for something or someone:</div><ul class=\"examples\"><li><em>Many companies won’t insure young drivers.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> an American spelling of ensure</div></div>","3733":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧tact</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈtækt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[not before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\">not broken, damaged, or spoiled:</div><ul class=\"examples\"><li><em>Only the medieval tower had remained intact.</em></li><li><em>His reputation survived intact.</em></li></ul></div>","3734":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧te‧gral</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪntəɡrəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> forming a necessary part of something:</div><ul class=\"examples\"><li><em>Vegetables are an integral part of our diet.</em></li><li><strong><em>integral to</strong>: Statistics are integral to medical research.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[usually before noun]</span> <em>British English</em> provided as part of something, rather than being separate:</div><ul class=\"examples\"><li><em>a racing car seat with an integral harness</em></li></ul></div>","3735":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧te‧grate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪntɪɡreɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if two or more things integrate, or if you integrate them, they combine or work together in a way that makes something more effective</div><ul class=\"examples\"><li><strong><em>integrate (something) into/with something</strong>: Colourful illustrations are integrated into the text. / Transport planning should be integrated with energy policy. / computers of different makes that integrate with each other</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to become part of a group or society and be accepted by them, or to help someone do this</div><ul class=\"examples\"><li><strong><em>integrate (somebody) into/with something</strong>: We’re looking for people who can integrate with a team. / Many children with learning difficulties are integrated into ordinary schools.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>especially American English</em> to end the practice of separating people of different races in schools, colleges etc <em>SYN desegregate</em> <em>OPP segregate</em></div></div>","3736":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧te‧gra‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪntɪˈɡreɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the combining of two or more things so that they work together effectively</div><ul class=\"examples\"><li><strong><em>integration of</strong>: the integration of data from other surveys</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> when people become part of a group or society and are accepted by them</div><ul class=\"examples\"><li><strong><em>integration into</strong>: The family unit is supported by its integration into a wider social network.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> the process of getting people of different races to live and work together instead of separately → assimilation:</div><ul class=\"examples\"><li><em>problems of racial integration</em></li></ul></div>","3737":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧teg‧ri‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈteɡrəti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the quality of being honest and strong about what you believe to be right</div><ul class=\"examples\"><li><strong><em>personal/professional/political etc integrity</strong>: a man of great moral integrity</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>formal</em> the state of being united as one complete thing:</div><ul class=\"examples\"><li><em>the territorial integrity of the country</em></li></ul></div>","3738":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧tel‧lect</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪntəlekt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the ability to understand things and to think intelligently</div><ul class=\"examples\"><li><strong><em>superior/considerable/keen etc intellect</strong>: He combined a formidable intellect with a talent for speaking.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> someone who is very intelligent</div></div>","3739":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧tel‧lec‧tu·al</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪntəˈlektʃuəl◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> relating to the ability to understand things and think intelligently → mental</div><ul class=\"examples\"><li><strong><em>intellectual development/ability/activity etc</strong>: a job that requires considerable intellectual effort</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an intellectual person is well-educated and interested in serious ideas and subjects such as science, literature etc → academic:</div><ul class=\"examples\"><li><em>Mark’s very intellectual.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> needing serious thought in order to be understood:</div><ul class=\"examples\"><li><em>an intellectual film</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">an intelligent well-educated person who spends time thinking about complicated ideas and discussing them → academic:</div><ul class=\"examples\"><li><em>a leading British intellectual</em></li></ul></div></div>","3740":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧tel‧li‧gence</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈtelədʒəns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> → artificial intelligence</div><div class=\"subsense\"><span class=\"subnum\">a)</span> the ability to learn, understand, and think about things:</div><ul class=\"examples\"><li><em>To be good at the game, you need a reasonable level of intelligence.</em></li><li><strong><em>high/low intelligence</strong>: John showed high intelligence from an early age.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> a high level of this ability:</div><ul class=\"examples\"><li><em>a woman who had both beauty and intelligence</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> information about the secret activities of foreign governments, the military plans of an enemy etc:</div><ul class=\"examples\"><li><em>According to our intelligence, further attacks were planned.</em></li><li><strong><em>intelligence operations/sources/reports etc</strong>: Intelligence sources denied the reports.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> a group of people or an organization that gathers this information for their government</div><ul class=\"examples\"><li><strong><em>intelligence agencies/services etc</strong>: In Britain there are three main intelligence organizations.</em></li><li><em>US Military Intelligence</em></li></ul></div>","3741":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧tel‧li‧gent</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈtelədʒənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an intelligent person has a high level of mental ability and is good at understanding ideas and thinking clearly:</div><ul class=\"examples\"><li><em>a group of highly intelligent (=very intelligent) students</em></li><li><em>Sontag was once famously described as the most intelligent woman in America.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an intelligent comment, question, conversation etc shows that you have thought about something carefully and understand it well:</div><ul class=\"examples\"><li><em>an intelligent question</em></li><li><em>You can’t have an intelligent conversation with him.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> an intelligent creature is able to think and understand:</div><ul class=\"examples\"><li><em>Are there intelligent beings on other planets?</em></li><li><em>forms of intelligent life</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> an intelligent machine, system etc is able to learn and use information</div></div>","3742":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧tend</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈtend/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to have something in your mind as a plan or purpose → intention RegisterIn everyday English, people usually say plan to do something or plan on doing something, rather than intend to do something or intend doing something:· I plan to spend the night there.· I didn’t plan on things taking so long. OR I didn’t plan for things to take so long.</div><ul class=\"examples\"><li><strong><em>intend to do something</strong>: I intend to spend the night there.</em></li><li><strong><em>intend somebody/something to do something</strong>: I didn’t intend her to see the painting until it was finished. / I never intended things to turn out the way they did.</em></li><li><strong><em>intend that</strong>: It is intended that these meetings will become a regular event.</em></li><li><strong><em>intend doing something</strong>: We intend looking at the situation again.</em></li><li><em>I fully intend (=definitely intend) to return home next year.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be intended for somebody/something</strong> to be provided or designed for a particular person or purpose:</div><ul class=\"examples\"><li><em>The book is intended for children aged 5–7.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>intended target/victim/destination etc</strong> the person, thing, result etc that an action is intended to affect or reach:</div><ul class=\"examples\"><li><em>It seems likely that General Rogers was the killer’s intended victim.</em></li></ul></div>","3743":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧tense</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈtens/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> having a very strong effect or felt very strongly:</div><ul class=\"examples\"><li><em>Young people today are under intense pressure to succeed.</em></li><li><em>the intense heat of the desert</em></li><li><em>The pain was so intense I couldn’t sleep.</em></li><li><em>He took an intense interest in all religious matters.</em></li><li><em>a look of intense dislike</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> intense activity is very serious, uses a lot of effort, and often involves doing a great deal in a very short time:</div><ul class=\"examples\"><li><em>The job demands intense concentration.</em></li><li><em>At least 3,000 people were killed in a week of intense fighting.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> someone who is intense is serious and has very strong feelings or opinions – used to show disapproval:</div><ul class=\"examples\"><li><em>She’s a little too intense for me.</em></li></ul></div>","3744":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ten‧si‧fy</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈtensɪfaɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span><span class=\"meta-item\">(past tense and past participle intensified, present participle intensifying, third person singular intensifies)</span></div><div class=\"entry-body\"><div class=\"sense\">to increase in degree or strength, or to make something do this:</div><ul class=\"examples\"><li><em>In June the civil war intensified.</em></li><li><em>His mother’s death intensified his loneliness.</em></li></ul></div>","3745":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ten‧si‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈtensəti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\">(plural intensities)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the quality of being felt very strongly or having a strong effect:</div><ul class=\"examples\"><li><em>The intensity of the hurricane was frightening.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the quality of being serious and having very strong feelings or opinions:</div><ul class=\"examples\"><li><em>He spoke with great intensity.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> <em>technical</em> the strength of something such as light or sound:</div><ul class=\"examples\"><li><em>an instrument which measures light intensity</em></li></ul></div>","3746":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ten‧sive</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈtensɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> involving a lot of activity, effort, or careful attention in a short period of time:</div><ul class=\"examples\"><li><em>a one-week intensive course in English</em></li><li><em>a day of intensive negotiations</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>intensive farming/agriculture</strong> farming which produces a lot of food from a small area of land</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>energy-intensive/knowledge-intensive etc</strong> involving or needing a lot of energy, knowledge etc: → capital-intensive, labour-intensive</div><ul class=\"examples\"><li><em>a knowledge-intensive industry</em></li></ul></div>","3747":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧tent</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈtent/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>be intent on/upon (doing) something</strong> to be determined to do something or achieve something:</div><ul class=\"examples\"><li><em>She was intent on pursuing a career in business.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> giving careful attention to something so that you think about nothing else:</div><ul class=\"examples\"><li><em>his intent gaze</em></li><li><strong><em>intent on/upon</strong>: Intent upon her work, she didn’t notice the cold.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>formal</em> what you intend to do <em>SYN intention</em>:</div><ul class=\"examples\"><li><em>She behaved foolishly but with good intent.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>law</em> the intention to do something illegal</div><ul class=\"examples\"><li><strong><em>with intent (to do something)</strong>: Jones was found guilty of wounding with intent. / He is charged with possession of a gun with intent to commit a robbery.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>to all intents and purposes</strong> (also for all intents and purposes<em>American English</em>) used to say that a situation is not exactly as you describe it, but the effect is the same as if it were:</div><ul class=\"examples\"><li><em>The war was, to all intents and purposes, over.</em></li></ul></div></div>","3748":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ten‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈtenʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a plan or desire to do something → intend ► Do not say that someone ‘has no intention to do something’. Say that someone has no intention of doing something. ► see thesaurus at purpose</div><ul class=\"examples\"><li><strong><em>have no/every intention of doing something</strong>: I have no intention of retiring just yet.</em></li><li><em>They went into town with the intention of visiting the library.</em></li><li><strong><em>intention to do something</strong>: It is our intention to be the number one distributor of health products.</em></li><li><strong><em>good intentions/the best (of) intentions</strong> (=intentions to do something good or kind, especially when you do not succeed in doing it): He thinks the minister is full of good intentions that won’t be carried out.</em></li></ul></div>","3749":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ten‧tion‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈtenʃənəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">done deliberately and usually intended to cause harm <em>SYN deliberate</em> <em>OPP unintentional</em>:</div><ul class=\"examples\"><li><em>I did trip him, but it wasn’t intentional.</em></li></ul></div>","3750":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ter‧act</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪntərˈækt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if people interact with each other, they talk to each other, work together etc</div><ul class=\"examples\"><li><strong><em>interact with</strong>: Lucy interacts well with other children in the class.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if one thing interacts with another, or if they interact, they affect each other</div><ul class=\"examples\"><li><strong><em>interact with</strong>: The immune system interacts with both the nervous system and the hormones.</em></li></ul></div>","3751":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ter‧ac‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪntərˈækʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a process by which two or more things affect each other</div><ul class=\"examples\"><li><strong><em>interaction of</strong>: Price is determined through the interaction of demand and supply.</em></li><li><strong><em>interaction with/between</strong>: the complex interaction between mind and body</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the activity of talking to other people, working together with them etc</div><ul class=\"examples\"><li><strong><em>interaction with/between</strong>: the degree of interaction between teacher and student</em></li></ul></div>","3752":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ter‧ac‧tive</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪntərˈæktɪv◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an interactive computer program, television system etc allows you to communicate directly with it, and does things in reaction to your actions:</div><ul class=\"examples\"><li><em>interactive computer systems</em></li><li><em>the museum’s interactive exhibits</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> involving talking and working together:</div><ul class=\"examples\"><li><em>interactive teaching methods such as role playing</em></li></ul></div>","3753":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ter‧cept</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪntəˈsept $ -ər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to stop something or someone that is going from one place to another before they get there:</div><ul class=\"examples\"><li><em>an attempt to intercept drugs being smuggled over the border</em></li><li><em>His phone calls were intercepted.</em></li></ul></div>","3754":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧terest</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪntrɪst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[singular, uncountable]</span> if you have an interest in something or someone, you want to know or learn more about them</div><ul class=\"examples\"><li><strong><em>interest in</strong>: My parents encouraged my interest in science.</em></li><li><em>I’d recommend this book to anyone who has an interest in jazz.</em></li><li><em>Ben has shown an interest in learning French.</em></li><li><em>My mother had never expressed any interest in the garden.</em></li><li><em>Babies soon begin to take an interest in the world around them.</em></li><li><em>John appeared to have no interest in girls.</em></li><li><em>I watched the first few episodes, but soon lost interest.</em></li><li><em>The last round of bidding aroused considerable interest.</em></li><li><em>Our survey reveals a disturbing lack of interest in teacher training.</em></li><li><em>I read your article with great interest.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable usually plural]</span> an activity that you enjoy doing or a subject that you enjoy studying:</div><ul class=\"examples\"><li><em>His interests include walking and golf.</em></li><li><em>As a biologist, my main interest has been human genetics.</em></li><li><em>Her outside interests (=interests that are not part of her work) were numerous.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> a quality or feature of something that attracts your attention or makes you want to know more about it:</div><ul class=\"examples\"><li><em>A Persian rug will add colour and interest to your hallway.</em></li><li><strong><em>be of (no) interest (to somebody)</strong> (=be interesting or not interesting to someone): It’s a book that will be of interest to a wide range of readers. / What you do in your private life is of no interest to me. / art galleries, museums and other places of interest / topics of general interest (=that everyone wants to know about)</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[uncountable]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> the extra money that you must pay back when you borrow money</div><ul class=\"examples\"><li><strong><em>interest on</strong>: The interest on the loan is 16% per year.</em></li><li><em>How much are the monthly interest payments?</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> money paid to you by a bank or financial institution when you keep money in an account there: → compound interest, interest rate, simple interest</div><ul class=\"examples\"><li><em>an account that pays higher interest</em></li><li><em>The more you save, the more interest you’ll earn.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable usually plural, uncountable]</span> the things that bring advantages to someone or something</div><ul class=\"examples\"><li><strong><em>protect/look after/safeguard somebody’s interests</strong>: The regulations were introduced in order to safeguard the interests of local fishing communities.</em></li><li><strong><em>be in somebody’s (best) interest(s) (to do something)</strong> (=be the best thing for someone): The court decided that it was in the girl’s best interests to remain with her grandparents.</em></li><li><strong><em>have somebody’s (best) interests at heart</strong> (=care about someone and want to do what is best for them): He has your best interests at heart, you know.</em></li><li><em>We’ve got to balance economic interests and environmental interests.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>be in the national/public interest</strong> to be good or necessary for the safety or success of a country and its people:</div><ul class=\"examples\"><li><em>I believe it is in the public interest that these facts are made known.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>in the interest(s) of justice/safety/efficiency etc</strong> in order to make a situation or system fair, safe etc:</div><ul class=\"examples\"><li><em>The race was postponed in the interests of safety.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>(just) out of interest/as a matter of interest</strong> <em>spoken</em> used to say that you are asking a question only because you are interested and not because you need to know:</div><ul class=\"examples\"><li><em>Just out of interest, how much did they offer you?</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <span class=\"gram\">[countable]</span> if you have an interest in a particular company or industry, you own shares in it:</div><ul class=\"examples\"><li><em>The company is believed to be keen to sell its extensive brewing interests.</em></li><li><em>His business interests are spread throughout Europe.</em></li><li><strong><em>controlling interest</strong> (=enough shares to control what decisions are taken): In 1986 GM acquired a controlling interest in the sports car maker Lotus.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <span class=\"gram\">[countable usually plural]</span> a group of people in the same business who share aims or ideas:</div><ul class=\"examples\"><li><em>Farming interests now dominate many of the National Park committees.</em></li><li><em>The majority of Brazil’s huge commercial interests support the measure.</em></li><li><em>the need to reduce the influence of special interests (=groups who are concerned about particular subjects)</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>have no interest in doing something</strong> to not want to do something:</div><ul class=\"examples\"><li><em>I have no interest in continuing this conversation.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>declare an interest (in something)</strong> to officially state that you are connected with something or someone, and so cannot be completely fair and independent when making a decision involving them</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>human interest/love interest</strong> the part of a story, film, or event which is interesting because it shows things about people’s lives or romantic relationships:</div><ul class=\"examples\"><li><em>As a trainee reporter, she spent most of her time on human interest stories.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● W2</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to make someone want to pay attention to something and find out more about it:</div><ul class=\"examples\"><li><em>Here’s an article which might interest you.</em></li><li><em>What interests me is all the history of these places.</em></li><li><strong><em>it interests somebody that/how/to do</strong>: It may interest you to know that a number of scholarships are available.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>interest yourself in something</strong> <em>formal</em> to give something a lot of attention because you want to find out more about it:</div><ul class=\"examples\"><li><em>He had always interested himself in foreign affairs.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to try to persuade someone to buy, do, or eat something</div><ul class=\"examples\"><li><strong><em>interest somebody in something</strong>: The salesman tried to interest me in the higher-priced model.</em></li><li><strong><em>Could I interest you in a drink/dessert etc?</strong> (=used as a polite way of offering someone a drink etc)</em></li></ul></div></div>","3755":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧terest‧ed</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪntrɪstɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> giving a lot of attention to something because you want to find out more about it or because you enjoy it <em>OPP uninterested</em> <em>, bored</em></div><ul class=\"examples\"><li><strong><em>interested in</strong>: I’ve always been interested in music. / All she’s interested in is clothes.</em></li><li><em>I wasn’t sure if he was really interested or if he was just being polite.</em></li><li><strong><em>interested to hear/know/see etc</strong>: I’d be very interested to hear your opinion.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if you are interested in doing or having something, you want to do it or have it:</div><ul class=\"examples\"><li><em>I’ve got a spare ticket for the opera, if you’re interested.</em></li><li><strong><em>interested in (doing) something</strong>: Sheila’s interested in starting her own business. / Would you be interested in a second-hand car?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>interested party/group</strong> a person or group that is directly or personally concerned with a situation and is likely to be affected by its results <em>OPP disinterested</em>:</div><ul class=\"examples\"><li><em>All interested parties are invited to attend the meeting.</em></li></ul></div>","3756":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧terest‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪntrəstɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\">if something is interesting, you give it your attention because it seems unusual or exciting or provides information that you did not know about <em>OPP uninteresting</em> <em>, boring</em>:</div><ul class=\"examples\"><li><em>That’s an interesting question.</em></li><li><em>a really interesting TV programme</em></li><li><strong><em>find something interesting</strong>: I found his talk very interesting.</em></li><li><em>Did you meet any interesting people?</em></li><li><strong><em>it is interesting to see/know etc</strong>: It will be interesting to see what happens when he gets a bit older.</em></li><li><em>It’s interesting that no one remembers seeing the car.</em></li></ul></div>","3757":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ter‧face</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪntəfeɪs $ -ər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the way in which you see the information from a computer program on a screen, or how you type information into the program → GUI</div><div class=\"sense\"><span class=\"snum\">2</span> <em>technical</em> the part of a computer system that connects two different machines</div><div class=\"sense\"><span class=\"snum\">3</span> the way in which two subjects, events etc affect each other</div><ul class=\"examples\"><li><strong><em>interface between</strong>: The book deals with the interface between accountancy and law.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>technical</em> the surface where two things touch each other</div></div>","3758":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ter‧fere</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪntəˈfɪə $ -tərˈfɪr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to deliberately get involved in a situation where you are not wanted or needed <em>SYN meddle</em>:</div><ul class=\"examples\"><li><em>My daughter-in-law said that I was interfering, but I was only trying to help.</em></li><li><strong><em>interfere in</strong>: It’s not the church’s job to interfere in politics.</em></li></ul></div>","3759":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ter‧fer‧ence</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪntəˈfɪərəns $ -tərˈfɪr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an act of interfering</div><ul class=\"examples\"><li><strong><em>interference in</strong>: I resent his interference in my work.</em></li><li><em>Industrial relations should be free from state interference.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> unwanted noise on the radio, television, or on the telephone, or faults in the television picture</div><div class=\"sense\"><span class=\"snum\">3</span> <em>especially American English</em> the act of blocking or touching another player in a sports game, for example by standing in front of them or holding on to them, when you are not supposed to SYN obstruction<em>British English</em></div><div class=\"sense\"><span class=\"snum\">4</span> <strong>run interference</strong> <em>American English</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to protect a player who has the ball in American football by blocking players from the opposing team</div><div class=\"subsense\"><span class=\"subnum\">b)</span> to help someone to achieve something by dealing with people or problems that might cause them trouble</div></div>","3760":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ter‧im</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪntərɪm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> intended to be used or accepted for a short time only, until something or someone final can be made or found:</div><ul class=\"examples\"><li><em>an interim report</em></li><li><em>He received an interim payment of £10,000.</em></li><li><em>An interim government was established.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>interim period</strong> the period of time between two events:</div><ul class=\"examples\"><li><em>During the interim period, air quality has deteriorated.</em></li></ul></div>","3761":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧te‧ri‧or</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈtɪəriə $ -ˈtɪriər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable usually singular]</span> the inner part or inside of something <em>OPP exterior</em>:</div><ul class=\"examples\"><li><em>The interior of the church was dark.</em></li><li><em>the car’s warm interior</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the interior</strong> the part of a country that is farthest away from the coast:</div><ul class=\"examples\"><li><em>The interior of the country is mainly desert.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>Minister/Department of the Interior</strong> the government minister or department that deals with matters within a country rather than abroad</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\">inside or indoors <em>OPP exterior</em>:</div><ul class=\"examples\"><li><em>The interior walls are all painted white.</em></li></ul></div></div>","3762":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ter‧me‧di‧ate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪntəˈmiːdiət◂ $ -tər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> an intermediate class, course etc is at a level of knowledge or skill that is between the basic level and the advanced level:</div><ul class=\"examples\"><li><em>a book aimed at students at the intermediate level and above</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> intermediate students, sports players etc have reached a level of knowledge or skill that is between the basic level and the advanced level:</div><ul class=\"examples\"><li><em>intermediate learners of English</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an intermediate stage in a process of development is between two other stages:</div><ul class=\"examples\"><li><em>an intermediate stage during which the disease is dormant</em></li></ul></div>","3763":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ter‧nal</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈtɜːnl $ -ɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W2 AWL</span><span class=\"meta-item\"><span class=\"gram\">[usually before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> within a particular country <em>SYN domestic</em> <em>OPP external</em>:</div><ul class=\"examples\"><li><em>We have no interest in interfering in the internal affairs of other countries.</em></li><li><em>the threat to internal security</em></li><li><em>internal markets</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> within a company or organization rather than outside it <em>OPP external</em>:</div><ul class=\"examples\"><li><em>There’s to be an internal inquiry into the whole affair.</em></li><li><em>the internal mail</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> inside your body <em>OPP external</em></div><ul class=\"examples\"><li><strong><em>internal organs/injuries</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">4</span> inside something rather than outside <em>OPP external</em>:</div><ul class=\"examples\"><li><em>They’ve knocked down a couple of internal walls.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> existing in your mind <em>SYN inner</em>:</div><ul class=\"examples\"><li><em>internal doubts</em></li></ul></div>","3764":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ter‧na‧tion‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪntəˈnæʃənəl◂ $ -tər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\">relating to or involving more than one nation → national</div><ul class=\"examples\"><li><strong><em>international trade/market/competition</em></strong></li><li><em>the response of the international community</em></li><li><em>the UN and other international organizations</em></li></ul></div>","3765":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> In‧ter‧net</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪntənet $ -tər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><strong>the Internet</strong> a computer system that allows millions of computer users around the world to exchange information:</div><ul class=\"examples\"><li><em>Do you have access to the Internet?</em></li><li><strong><em>on the Internet</strong>: You can find all kinds of information on the internet.</em></li></ul></div>","3766":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ter‧pret</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈtɜːprɪt $ -ɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to translate spoken words from one language into another:</div><ul class=\"examples\"><li><em>They spoke good Spanish, and promised to interpret for me.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to believe that something someone does or something that happens has a particular meaning</div><ul class=\"examples\"><li><strong><em>interpret something as something</strong>: His refusal to work late was interpreted as a lack of commitment to the company.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to explain the meaning of something:</div><ul class=\"examples\"><li><em>Freud’s attempts to interpret the meaning of dreams</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[transitive]</span> to perform a part in a play, a piece of music etc in a way that shows your feelings about it or what you think it means</div></div>","3767":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ter‧pre‧ta‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˌtɜːprɪˈteɪʃən $ -ɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the way in which someone explains or understands an event, information, someone’s actions etc:</div><ul class=\"examples\"><li><em>One possible interpretation is that they want you to resign.</em></li><li><em>It’s difficult to put an accurate interpretation on (=explain) the survey results.</em></li><li><em>What exactly the author meant by that statement is open to interpretation (=able to be understood or explained in different ways).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the way in which someone performs a play, a piece of music etc and shows what they think and feel about it:</div><ul class=\"examples\"><li><em>Laurence Olivier’s brilliant interpretation of Henry V</em></li></ul></div>","3768":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ter‧pret‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈtɜːprɪtə $ -ˈtɜːrprɪtər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who changes spoken words from one language into another, especially as their job → translator:</div><ul class=\"examples\"><li><em>Speaking through an interpreter (=using an interpreter), Ahmed said, ‘I’m very worried about my wife and children.’</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a computer program that changes an instruction into a form that can be understood directly by the computer</div></div>","3769":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ter‧ro‧ga‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈterəɡeɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the process of interrogating someone:</div><ul class=\"examples\"><li><em>a long interrogation</em></li><li><em>Under interrogation, he admitted that he had taken the money.</em></li></ul></div>","3770":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ter‧rupt</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪntəˈrʌpt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to stop someone from continuing what they are saying or doing by suddenly speaking to them, making a noise etc:</div><ul class=\"examples\"><li><em>Will you stop interrupting me!</em></li><li><em>Sorry to interrupt, but I need to ask you to come downstairs.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to make a process or activity stop temporarily:</div><ul class=\"examples\"><li><em>My studies were interrupted by the war.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> if something interrupts a line, surface, view etc, it stops it from being continuous</div></div>","3771":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ter‧sec‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪntəˈsekʃən, ˈɪntəsekʃən $ -tər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a place where roads, lines etc cross each other, especially where two roads meet SYN junction<em>British English</em></div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the act of intersecting something</div></div>","3772":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ter‧val</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪntəvəl $ -tər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the period of time between two events, activities etc:</div><ul class=\"examples\"><li><em>He left the room, returning after a short interval with a message.</em></li><li><strong><em>interval between</strong>: The interval between arrest and trial can be up to six months.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>sunny/bright intervals</strong> <em>British English</em> short periods of fine weather between cloudy weather, rainy weather etc</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>at weekly/20-minute etc intervals</strong> every week, 20 minutes etc:</div><ul class=\"examples\"><li><em>The trains run at half-hourly intervals.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>at regular intervals</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> something that happens at regular intervals happens often:</div><ul class=\"examples\"><li><em>The phone rang at regular intervals all afternoon.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> objects that are placed at regular intervals have all been placed at the same distance from each other:</div><ul class=\"examples\"><li><em>Trees had been planted at regular intervals.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <em>British English</em> a short period of time between the parts of a play, concert etc SYN intermission<em>American English</em>:</div><ul class=\"examples\"><li><em>We can get some drinks in the interval.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <em>technical</em> the amount of difference in pitch between two musical notes</div></div>","3773":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ter‧vene</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪntəˈviːn $ -tər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive]</span> to become involved in an argument, fight, or other difficult situation in order to change what happens</div><ul class=\"examples\"><li><strong><em>intervene in</strong>: The police don’t usually like to intervene in disputes between husbands and wives.</em></li><li><em>The army will have to intervene to prevent further fighting.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> to interrupt someone when they are speaking:</div><ul class=\"examples\"><li><em>‘Stop shouting, Emily,’ John intervened.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive]</span> if an event intervenes, it delays or interrupts something else:</div><ul class=\"examples\"><li><em>He was just establishing his career when the war intervened.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[intransitive]</span> if a period of time intervenes, it comes between two events:</div><ul class=\"examples\"><li><em>In the six years that intervened, I saw them once.</em></li></ul></div>","3774":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ter‧ven‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪntəˈvenʃən $ -tər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the act of becoming involved in an argument, fight, or other difficult situation in order to change what happens:</div><ul class=\"examples\"><li><em>government intervention to regulate prices</em></li></ul></div>","3775":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ter‧view</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪntəvjuː $ -ər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a formal meeting at which someone is asked questions in order to find out whether they are suitable for a job, course of study etc</div><ul class=\"examples\"><li><strong><em>interview for</strong>: an interview for a job on the ‘Los Angeles Times’</em></li><li><em>a portfolio of work presented at interview</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> an occasion when a famous person is asked questions about their life, experiences, or opinions for a newspaper, magazine, television programme etc</div><ul class=\"examples\"><li><strong><em>interview with</strong>: an interview with the president</em></li><li><strong><em>newspaper/radio/television interview</em></strong></li><li><em>Elton John gave an interview to Barbara Walters (=he answered her questions).</em></li><li><em>an exclusive interview (=one that is given to only one newspaper, programme etc)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> an official meeting with someone who asks you questions:</div><ul class=\"examples\"><li><em>a police interview</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to ask someone questions during an interview ► see thesaurus at ask</div><ul class=\"examples\"><li><strong><em>interview somebody for something</strong>: We’re interviewing six candidates for the job.</em></li><li><strong><em>interview somebody about something</strong>: The police want to interview you about the accident.</em></li></ul></div></div>","3776":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ter‧view‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪntəvjuːə $ -tərvjuːər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the person who asks the questions in an interview</div></div>","3777":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ti‧mate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪntəmət/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[restaurant/meal/place]</strong> private and friendly so that you feel comfortable:</div><ul class=\"examples\"><li><em>the intimate atmosphere of a country pub</em></li><li><em>an intimate meal for two</em></li><li><em>The collection has been moved from its intimate setting to the British Museum.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[friends]</strong> having an extremely close friendship:</div><ul class=\"examples\"><li><em>an intimate friend of Picasso’s</em></li><li><em>an intimate relationship</em></li><li><em>She’s on intimate terms with people in government.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>intimate knowledge of something</strong> very detailed knowledge of something as a result of careful study or a lot of experience:</div><ul class=\"examples\"><li><em>his intimate knowledge of the coal industry</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[private]</strong> relating to very private or personal matters: ► see thesaurus at private</div><ul class=\"examples\"><li><em>the publication of intimate details of their affair</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[sex]</strong> <em>formal</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> relating to sex:</div><ul class=\"examples\"><li><em>The virus can only be transmitted through intimate contact.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <strong>be intimate with somebody</strong> to have sex with someone</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>intimate link/connection etc</strong> a very close connection between two things:</div><ul class=\"examples\"><li><em>the intimate connection between physical and mental health</em></li></ul></div>","3778":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧tim‧i‧date</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈtɪmədeɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to frighten or threaten someone into making them do what you want</div><ul class=\"examples\"><li><strong><em>intimidate somebody into doing something</strong>: They tried to intimidate the young people into voting for them.</em></li><li><em>Attempts to intimidate her failed.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make someone feel worried and not confident:</div><ul class=\"examples\"><li><em>The whole idea of going to Oxford intimidated me.</em></li></ul></div>","3779":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧to</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪntə; before vowels ˈɪntʊ; strong ˈɪntuː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[to the inside of something]</strong> to the inside or inner part of a container, place, area etc:</div><ul class=\"examples\"><li><em>Come into the office.</em></li><li><em>He thrust his hand into his coat pocket.</em></li><li><em>There must be another way into the cave.</em></li><li><em>Sue got back into bed and pulled the quilt over her head.</em></li><li><em>I’ve got to go into town this morning.</em></li><li><em>We dived into the sea.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[becoming involved]</strong> used to say that someone becomes involved in a situation or activity, or becomes part of a group:</div><ul class=\"examples\"><li><em>At the age of 16, I went into the printing trade as an apprentice.</em></li><li><em>They tried to drag me into their quarrel.</em></li><li><em>a player who deserves to get back into the England team</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[changing]</strong> used to say that someone or something starts being in a different state or form:</div><ul class=\"examples\"><li><em>She fell into a deep sleep.</em></li><li><em>The whole banking system was thrown into confusion.</em></li><li><em>I screwed my wet handkerchief into a ball.</em></li><li><em>Cut the cake into pieces.</em></li><li><em>Neruda’s poems have been translated into English.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[hitting something]</strong> used to say that a person or vehicle hits someone or something after moving towards them:</div><ul class=\"examples\"><li><em>He almost bumped into me as he rushed past.</em></li><li><em>The car swerved and crashed into the wall.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[direction]</strong> in a particular direction:</div><ul class=\"examples\"><li><em>They rode off into the sunset.</em></li><li><em>Make sure you’re speaking directly into the microphone.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[time]</strong> at or until a certain time:</div><ul class=\"examples\"><li><em>Andy and I talked well into the night.</em></li><li><em>John was well into his forties before he got married.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[finding out]</strong> used to say what someone is trying to find out information about:</div><ul class=\"examples\"><li><em>an investigation into the events leading up to his death</em></li><li><em>I’ve been doing some research into this.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[dividing numbers]</strong> <em>spoken</em> used when you are dividing one number by another:</div><ul class=\"examples\"><li><em>Eight into twenty-four is three.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>be into something</strong> <em>spoken</em> to like and be interested in something:</div><ul class=\"examples\"><li><em>I’m really into folk music.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>be into somebody</strong> <em>American English</em> <em>informal</em> to owe someone money:</div><ul class=\"examples\"><li><em>He’s into me for $50.</em></li></ul></div>","3780":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧tol‧e‧ra‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈtɒlərəbəl $ -ˈtɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">too difficult, bad, annoying etc for you to accept or deal with <em>OPP tolerable</em>:</div><ul class=\"examples\"><li><em>‘This is intolerable!’ exclaimed Sir Rufus.</em></li><li><em>The pain had become intolerable.</em></li><li><strong><em>intolerable burden/strain/pressure</strong>: Caring for an elderly relative can become an intolerable burden.</em></li></ul></div>","3781":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧tol‧e‧rance</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈtɒlərəns $ -ˈtɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> unwillingness to accept ways of thinking and behaving that are different from your own <em>OPP tolerance</em> ► see thesaurus at prejudice</div><ul class=\"examples\"><li><strong><em>racial/religious intolerance</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> an inability to take particular medicines or eat particular foods without suffering bad effects → allergic</div><ul class=\"examples\"><li><strong><em>intolerance of</strong>: an intolerance of alcohol</em></li><li><strong><em>food/glucose/lactose intolerance</em></strong></li></ul></div>","3782":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧tri‧cate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪntrɪkət/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">containing many small parts or details that all work or fit together → complex: ► see thesaurus at complicated</div><ul class=\"examples\"><li><em>intricate patterns</em></li></ul></div>","3783":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧trigue</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈtriːɡ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> if something intrigues you, it interests you a lot because it seems strange or mysterious:</div><ul class=\"examples\"><li><em>Other people’s houses always intrigued her.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive]</span> <em>formal</em> to make secret plans to harm someone or make them lose their position of power</div><ul class=\"examples\"><li><strong><em>intrigue against</strong>: While King Richard was abroad, the barons had been intriguing against him.</em></li></ul></div>","3784":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧trin‧sic</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈtrɪnsɪk, -zɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">being part of the nature or character of someone or something <em>OPP extrinsic</em>:</div><ul class=\"examples\"><li><em>the intrinsic interest of the subject</em></li><li><strong><em>intrinsic nature/quality/value/property of something</strong>: There is nothing in the intrinsic nature of the work that makes it more suitable for women.</em></li><li><strong><em>intrinsic to</strong>: Flexibility is intrinsic to creative management.</em></li></ul></div>","3785":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧tro‧duce</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪntrəˈdjuːs $ -ˈduːs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[when people meet]</strong> if you introduce someone to another person, you tell them each other’s names for the first time:</div><ul class=\"examples\"><li><em>Have you two been introduced? Tom, this is Greg.</em></li><li><strong><em>introduce somebody to somebody</strong>: June, let me introduce you to Bob.</em></li><li><strong><em>introduce yourself</strong> (=formally tell someone who you are): May I introduce myself? My name is Meg Johnson.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[new system/product]</strong> to bring a plan, system, or product into use for the first time: RegisterIn everyday British English, people often say bring in a plan, law, system etc rather than introduce it:· They want to bring in a system of identity cards.</div><ul class=\"examples\"><li><em>They want to introduce a system of identity cards.</em></li><li><em>The store have introduced a new range of food for children.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[bring something to a place]</strong> to bring a type of thing somewhere for the first time</div><ul class=\"examples\"><li><strong><em>introduce something to/into something</strong>: The grey squirrel was introduced into Britain from North America.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[new experience]</strong> to show someone something or tell them about it for the first time</div><ul class=\"examples\"><li><strong><em>introduce somebody to something/introduce something to somebody</strong>: Malcolm introduced me to the joys of wine-tasting.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[programme/public event]</strong> to speak at the beginning of and sometimes during a television or radio programme, or at the beginning of a public event:</div><ul class=\"examples\"><li><em>Jim Adams will introduce tonight’s programme.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[start a change]</strong> to make something new start to happen or exist in a situation:</div><ul class=\"examples\"><li><em>The peace agreement has introduced a feeling of optimism here.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[law]</strong> to formally present a possible new law to be discussed:</div><ul class=\"examples\"><li><em>Several senators introduced legislation aimed at sexual harassment.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[put something into something]</strong> <em>technical</em> to put something carefully into something else</div><ul class=\"examples\"><li><strong><em>introduce something into something</strong>: Fuel was introduced into the jet pipe.</em></li></ul></div>","3786":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧tro‧duc‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪntrəˈdʌkʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[new system/product]</strong> <span class=\"gram\">[uncountable]</span> the act of bringing something into use for the first time</div><ul class=\"examples\"><li><strong><em>introduction of</strong>: the introduction of a range of new products / With the introduction of independent taxation, a married woman’s position is much clearer.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[bring something to a place]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[uncountable]</span> the act of bringing something somewhere for the first time</div><ul class=\"examples\"><li><strong><em>introduction of</strong>: the introduction of Buddhism to China nearly 2,000 years ago</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[countable]</span> a type of thing that is brought somewhere for the first time:</div><ul class=\"examples\"><li><em>The potato was a 16th-century introduction.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[when meeting somebody]</strong> <span class=\"gram\">[countable]</span> the act of formally telling two people each other’s names when they first meet:</div><ul class=\"examples\"><li><em>Pete, are you going to make the introductions?</em></li><li><em>Our first contestant needs no introduction (=everyone already knows the person).</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[book/speech]</strong> <span class=\"gram\">[countable]</span> a written or spoken explanation at the beginning of a book, speech etc:</div><ul class=\"examples\"><li><em>In the introduction, he explains why he wrote the book.</em></li><li><em>Mr Brown gave a brief introduction to the course.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[music]</strong> <span class=\"gram\">[countable]</span> a short part at the beginning of a song or piece of music</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[explanation]</strong> <span class=\"gram\">[countable]</span> something that explains the basic facts of a subject</div><ul class=\"examples\"><li><strong><em>introduction to</strong>: The book is a useful introduction to British geology.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[new experience]</strong> <span class=\"gram\">[countable]</span> someone’s first experience of something</div><ul class=\"examples\"><li><strong><em>introduction to</strong>: an introduction to water sports</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[letter]</strong> <span class=\"gram\">[countable]</span> a letter by someone else that explains who you are, which you can give to a person you have not met before</div></div>","3787":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧tro‧duc‧to‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪntrəˈdʌktəri◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> said or written at the beginning of a book, speech etc in order to explain what it is about</div><ul class=\"examples\"><li><strong><em>introductory chapter/paragraph</strong>: the objectives described in the introductory chapter</em></li><li><em>as the chairman said in his introductory remarks</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> intended for people who have never done a particular activity before:</div><ul class=\"examples\"><li><em>an introductory course in data processing</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>introductory offer/price etc</strong> a special low price that is charged for a new product for a limited period of time:</div><ul class=\"examples\"><li><em>Don’t miss our introductory offer!</em></li></ul></div>","3788":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧tro‧vert</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪntrəvɜːt $ -ɜːrt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who is quiet and shy, and does not enjoy being with other people <em>OPP extrovert</em></div></div>","3789":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧trude</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈtruːd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to interrupt someone or become involved in their private affairs, in an annoying and unwanted way:</div><ul class=\"examples\"><li><em>Would I be intruding if I came with you?</em></li><li><strong><em>intrude into/on/upon</strong>: Employers should not intrude into the private lives of their employees.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to come into a place or situation, and have an unwanted effect</div><ul class=\"examples\"><li><strong><em>intrude on</strong>: It is to be hoped that TV cameras never intrude on this peaceful place.</em></li></ul></div>","3790":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧trud‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈtruːdə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who illegally enters a building or area, usually in order to steal something:</div><ul class=\"examples\"><li><em>The police think the intruder got in through an unlocked window.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who is in a place where they are not wanted:</div><ul class=\"examples\"><li><em>At first I felt like an intruder in their family.</em></li></ul></div>","3791":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧tru‧sion</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈtruːʒən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> when someone does something, or something happens, that affects your private life or activities in an unwanted way</div><ul class=\"examples\"><li><strong><em>intrusion into/on/upon</strong>: I resented this intrusion into my domestic affairs.</em></li><li><em>the unwelcome intrusion of the press</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> when something comes into a place or situation and has an unwanted effect:</div><ul class=\"examples\"><li><em>the intrusion of badly designed new buildings in the historic high street</em></li></ul></div>","3792":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧tu‧i‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪntjuˈɪʃən $ -tu-, -tju-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the ability to understand or know something because of a feeling rather than by considering the facts <em>SYN instinct</em>:</div><ul class=\"examples\"><li><em>feminine intuition</em></li><li><em>Intuition told her it was unwise to argue.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> an idea about what is true in a particular situation based on a feeling rather than facts</div><ul class=\"examples\"><li><strong><em>intuition (that)</strong>: He had an intuition there was trouble brewing.</em></li><li><em>We should trust our intuitions.</em></li></ul></div>","3793":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧vade</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈveɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to enter a country, town, or area using military force, in order to take control of it: ► see thesaurus at attack</div><ul class=\"examples\"><li><em>The Romans invaded Britain 2,000 years ago.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to go into a place in large numbers, especially when you are not wanted:</div><ul class=\"examples\"><li><em>Every summer, the town is invaded by tourists.</em></li><li><em>Fans invaded the pitch at half time.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to get involved in something in an unwanted and annoying way:</div><ul class=\"examples\"><li><em>What right does he have to invade my privacy?</em></li><li><em>Patients are given the feeling that they mustn’t try to invade medical territory (=try to deal with things that are not their responsibility).</em></li></ul></div>","3794":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧val‧id</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈvælɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a contract, ticket, claim etc that is invalid is not legally or officially acceptable <em>OPP valid</em>:</div><ul class=\"examples\"><li><em>Without the right date stamped on it, your ticket will be invalid.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an argument, reason etc that is invalid is not based on true facts or clear ideas, and lacks good judgment <em>OPP valid</em></div><div class=\"sense\"><span class=\"snum\">3</span> if something you type into a computer is invalid, the computer does not recognize or accept it:</div><ul class=\"examples\"><li><em>Filename in invalid format.</em></li></ul></div>","3795":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧val‧i‧date</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈvælədeɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to make a document, ticket, claim etc no longer legally or officially acceptable:</div><ul class=\"examples\"><li><em>Failure to disclose all relevant changes may invalidate your policy.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to show that something such as a belief or explanation is wrong:</div><ul class=\"examples\"><li><em>Later findings invalidated the theory.</em></li></ul></div>","3796":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧val‧u‧a‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈvæljuəbəl, -jəbəl $ -ˈvæljəbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">extremely useful ► see thesaurus at useful</div><ul class=\"examples\"><li><strong><em>invaluable to/for</strong>: Your advice has been invaluable to us.</em></li><li><strong><em>invaluable in/for (doing) something</strong>: This help was invaluable in focussing my ideas.</em></li><li><em>The internet is an invaluable source of information.</em></li></ul></div>","3797":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧var‧i‧a‧bly</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈveəriəbli $ -ˈver-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">if something invariably happens or is invariably true, it always happens or is true:</div><ul class=\"examples\"><li><em>It invariably rains when I go there.</em></li><li><em>The security guards were invariably ex-servicemen.</em></li></ul></div>","3798":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧va‧sion</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈveɪʒən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> when the army of one country enters another country by force, in order to take control of it</div><ul class=\"examples\"><li><strong><em>invasion of</strong>: the invasion of Normandy</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> the arrival in a place of a lot of people or things, often where they are not wanted:</div><ul class=\"examples\"><li><em>the annual invasion of teenagers for the Glastonbury Festival</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>invasion of privacy</strong> a situation in which someone tries to find out details about another person’s private affairs in a way that is upsetting and often illegal</div></div>","3799":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧vent</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈvent/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to make, design, or think of a new type of thing: ► Do not confuse with discover (=to be the first person to find something or to know that it exists): Scientists have discovered a new type of bacteria.</div><ul class=\"examples\"><li><em>Alexander Graham Bell invented the telephone in 1876.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to think of an idea, story etc that is not true, usually in order to deceive people:</div><ul class=\"examples\"><li><em>They invented a very convincing alibi.</em></li></ul></div>","3800":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ven‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈvenʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a useful machine, tool, instrument etc that has been invented:</div><ul class=\"examples\"><li><em>The dishwasher is a wonderful invention.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the act of inventing something:</div><ul class=\"examples\"><li><em>The invention of the computer has revolutionized the business world.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable, uncountable]</span> a story, explanation etc that is not true:</div><ul class=\"examples\"><li><em>They subsequently admitted that the story was pure invention.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[uncountable]</span> the ability to think of new and clever ideas:</div><ul class=\"examples\"><li><em>With such powers of invention, he should get a job easily.</em></li></ul></div>","3801":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ven‧tory</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnvəntri $ -tɔːri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\">(plural inventories)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a list of all the things in a place</div><ul class=\"examples\"><li><strong><em>inventory of</strong>: We made an inventory of everything in the apartment.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> <em>American English</em> all the goods in a shop <em>SYN stock</em></div></div>","3802":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> inˌverted ˈcomma</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable usually plural]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> one of a pair of marks (‘) or (’) that are put at the beginning and end of a written word, sentence etc to show that someone said it or wrote it, or when writing the title of a book, song etc <em>SYN quotation mark</em> → punctuation mark</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>in inverted commas</strong> <em>spoken</em> used to show that a word you are using to describe something is only what it is usually called, and not what you think it really is:</div><ul class=\"examples\"><li><em>Her friends, in inverted commas, all disappeared when she was in trouble.</em></li></ul></div>","3803":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧vest</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈvest/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to buy shares, property, or goods because you hope that the value will increase and you can make a profit:</div><ul class=\"examples\"><li><em>I’ve got a few thousand dollars I’m looking to invest.</em></li><li><strong><em>invest (something) in something</strong>: Oliver made a fortune by investing in antique furniture. / Williams invested a large sum of money in Swiss stocks.</em></li><li><em>He had invested heavily (=invested a lot of money) in the bond market.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> if a government, business, or organization invests in something, they spend a large amount of money to improve it or help it succeed RegisterIn everyday English, people often say put money in/into something rather than invest in something:· He put money into his brother’s business.· The government put in millions of pounds.</div><ul class=\"examples\"><li><strong><em>invest (something) in something</strong>: The city has invested millions of dollars in the museum. / The factory plans to invest in new computers.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to use a lot of time, effort etc or spend money in order to make something succeed</div><ul class=\"examples\"><li><strong><em>invest something in something</strong>: It was very difficult to leave a home we had invested so much in.</em></li></ul></div>","3804":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ves‧ti‧gate</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈvestɪɡeɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to try to find out the truth about something such as a crime, accident, or scientific problem: RegisterIn everyday English, people often say look into something rather than investigate something:· I’ll ask my colleague to look into it.</div><ul class=\"examples\"><li><em>The state police are investigating the incident.</em></li><li><em>The study investigates the impact of violent TV programming on children.</em></li><li><em>I heard a noise and went downstairs to investigate.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to try to find out more about someone’s character, actions etc, because you think they may have been involved in a crime:</div><ul class=\"examples\"><li><em>Penney was already being investigated by the police on suspicion of murder.</em></li></ul></div>","3805":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ves‧ti‧ga‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˌvestɪˈɡeɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> an official attempt to find out the truth about or the cause of something such as a crime, accident, or scientific problem:</div><ul class=\"examples\"><li><em>The investigation continued for nearly three years.</em></li><li><strong><em>investigation into</strong>: The authorities are planning to launch a full-scale investigation into the crash.</em></li><li><strong><em>investigation of</strong>: Baker demanded an investigation of the district attorney’s office.</em></li><li><em>a criminal investigation</em></li><li><em>A private detective was hired to conduct the investigation.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the act of investigating something</div><ul class=\"examples\"><li><strong><em>investigation of</strong>: the investigation of computer fraud</em></li><li><strong><em>under investigation</strong> (=being investigated): The whole issue is still under investigation.</em></li></ul></div>","3806":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ves‧ti‧ga‧tor</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈvestəɡeɪtə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who investigates things, especially crimes:</div><ul class=\"examples\"><li><em>police investigators</em></li></ul></div>","3807":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧vest‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈvestmənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the use of money to get a profit or to make a business activity successful, or the money that is used:</div><ul class=\"examples\"><li><em>We plan to buy some property as an investment.</em></li><li><strong><em>investment in</strong>: That year, Japanese investment in American real estate totaled $13.06 billion.</em></li><li><strong><em>investment of</strong>: Each of us was required to put up a minimum investment of £5,000.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> something that you buy or do because it will be useful later</div><ul class=\"examples\"><li><strong><em>a good/sound investment</strong>: The lessons cost me over £500, but I consider them a good investment.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[singular, uncountable]</span> when you spend a large amount of time, energy, emotion etc on something:</div><ul class=\"examples\"><li><em>a huge investment of time and effort</em></li></ul></div>","3808":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧vest‧or</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈvestə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who gives money to a company, business, or bank in order to get a profit</div></div>","3809":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧vis‧i‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈvɪzəbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> something that is invisible cannot be seen <em>OPP visible</em>:</div><ul class=\"examples\"><li><em>The house was surrounded by trees, and invisible from the road.</em></li><li><strong><em>invisible to</strong>: The plane is meant to be invisible to radar.</em></li><li><em>Using a telescope, Galileo discovered stars that were invisible to the naked eye.</em></li><li><strong><em>virtually/practically/almost etc invisible</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> not noticed, or not talked about:</div><ul class=\"examples\"><li><em>There’s an invisible barrier that keeps women out of top jobs.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>invisible earnings/exports/trade etc</strong> money that is made from services and tourism rather than from products</div></div>","3810":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧vi‧ta‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪnvɪˈteɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a written or spoken request to someone, inviting them to go somewhere or do something</div><ul class=\"examples\"><li><strong><em>an invitation to do something</strong>: an invitation to speak at a scientific conference</em></li><li><strong><em>invitation to</strong>: Roger never turns down an invitation to dinner.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the act of being invited or of inviting someone to go somewhere or do something</div><ul class=\"examples\"><li><strong><em>by invitation</strong>: Attendance at the seminars is by invitation only (=only those people who have been invited can attend).</em></li><li><em>They were always dropping by, usually without invitation.</em></li><li><strong><em>at somebody’s invitation/at the invitation of somebody</strong>: Kegl traveled to Nicaragua at the invitation of the Education Minister.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a card inviting someone to attend a party, wedding etc</div><ul class=\"examples\"><li><strong><em>party/wedding invitation</strong>: We sent out more than 300 wedding invitations.</em></li><li><strong><em>invitation to</strong>: Did you get an invitation to Jason’s party?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[singular, uncountable]</span> encouragement to do something</div><ul class=\"examples\"><li><strong><em>take something as an invitation to do something</strong>: He seemed to take my silence as an invitation to talk.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be an open invitation for/to somebody</strong> to make it very easy for someone to rob you or harm you:</div><ul class=\"examples\"><li><em>Leaving the car unlocked is just an open invitation to thieves.</em></li></ul></div>","3811":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧vite</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈvaɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to ask someone to come to a party, wedding, meal etc GRAMMAR: Prepositions with invite• You invite someone to an event or a place: · Did they invite you to the wedding?· She invited me to her house.• You invite someone for a meal or a period of time: · He invited us for brunch.· I’ll invite them for the weekend.</div><ul class=\"examples\"><li><strong><em>invite somebody to something</strong>: Who should we invite to the party?</em></li><li><strong><em>invite somebody to do something</strong>: Gail invited me to stay with her while her husband was out of town.</em></li><li><strong><em>invite somebody for something</strong>: Why don’t you invite her for a drink at the club one evening?</em></li><li><em>I’m afraid I wasn’t invited.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to politely ask someone to do something</div><ul class=\"examples\"><li><strong><em>invite somebody to do something</strong>: Anyone interested in contributing articles is invited to contact the editor.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to encourage something bad to happen, especially without intending to:</div><ul class=\"examples\"><li><em>Any government that sells arms to dictators is inviting trouble.</em></li></ul></div>","3812":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧voice</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnvɔɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a list of goods that have been supplied or work that has been done, showing how much you owe for them → bill ► see thesaurus at bill</div></div>","3813":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧volve</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈvɒlv $ ɪnˈvɑːlv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1 AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if an activity or situation involves something, that thing is part of it or a result of it:</div><ul class=\"examples\"><li><em>What will the job involve?</em></li><li><em>I didn’t realize putting on a play involved so much work.</em></li><li><strong><em>involve doing something</strong>: Running your own business usually involves working long hours.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to include or affect someone or something:</div><ul class=\"examples\"><li><em>These changes will involve everyone on the staff.</em></li><li><em>There have been four accidents involving Forest Service planes.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to ask or allow someone to take part in something</div><ul class=\"examples\"><li><strong><em>involve somebody in (doing) something</strong>: Try to involve as many children as possible in the game. / We want to involve the workforce at all stages of the decision-making process.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>involve yourself</strong> to take part actively in a particular activity</div><ul class=\"examples\"><li><strong><em>involve in</strong>: Reilly involves himself in every aspect of his company’s business.</em></li></ul></div>","3814":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧volved</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈvɒlvd $ ɪnˈvɑːlvd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>be/get involved</strong> to take part in an activity or event, or be connected with it in some way GRAMMAR: Prepositions with involved• Someone is involved in something: · He is involved in the family business.· Don’t get involved in their problems. ✗Don’t say: involved into something• Someone is involved with a project, person, or group: · She got involved with the youth club.Grammar guide ‒ ADJECTIVES</div><ul class=\"examples\"><li><strong><em>involved in</strong>: More than 30 software firms were involved in the project. / I don’t want to get involved in some lengthy argument about who is to blame. / I’m afraid your son’s been involved in an accident (=he is one of the people in an accident).</em></li><li><strong><em>involved with</strong>: Landel has been involved with the Hercules project for years.</em></li><li><strong><em>actively/deeply/heavily involved</strong> (=involved very much): Mrs. Cummings has been actively involved with the church for years.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>work/effort etc involved in doing something</strong> the amount of work, effort etc that is needed in order to make something succeed:</div><ul class=\"examples\"><li><em>Most people don’t realize the amount of effort involved in writing a novel.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be involved with somebody</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to be having a romantic relationship with someone, especially a sexual one:</div><ul class=\"examples\"><li><em>The senator denied that he was romantically involved with a member of his staff.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to spend time with someone that you have a relationship with:</div><ul class=\"examples\"><li><em>Fathers are encouraged to be more involved with their families.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> having so many different parts that it is difficult to understand <em>SYN complicated</em>: ► see thesaurus at complicated</div><ul class=\"examples\"><li><em>The plot was so involved that very few people knew what was going on.</em></li></ul></div>","3815":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧volve‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪnˈvɒlvmənt $ -ˈvɑːlv-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the act of taking part in an activity or event, or the way in which you take part in it <em>SYN participation</em>:</div><ul class=\"examples\"><li><em>School officials say they welcome parental involvement.</em></li><li><strong><em>involvement in</strong>: His new book examines the United States’ involvement in World War II.</em></li><li><strong><em>involvement with</strong>: Carey’s possible involvement with a series of robberies</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> something that you take part in or spend time doing:</div><ul class=\"examples\"><li><em>sporting involvements</em></li><li><em>her political involvements</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> the feeling of excitement and satisfaction that you get from an activity</div><ul class=\"examples\"><li><strong><em>involvement in</strong>: Weaver admitted a strong emotional involvement in her client’s case.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable, uncountable]</span> a romantic relationship between two people, especially when they are not married to each other</div><ul class=\"examples\"><li><strong><em>involvement with</strong>: Donna knew nothing of her husband’s involvement with another woman.</em></li></ul></div>","3816":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> in‧ward</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪnwəd $ -wərd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[only before noun]</span> felt or experienced in your own mind but not expressed to other people <em>OPP outward</em>:</div><ul class=\"examples\"><li><em>a feeling of inward satisfaction</em></li><li><em>inward panic</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> towards the inside or centre of something</div></div>","3817":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧ron</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈaɪən $ ˈaɪərn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[metal]</strong> <span class=\"gram\">[uncountable]</span> a common hard metal that is used to make steel, is magnetic, and is found in very small quantities in food and blood. It is a chemical element: symbol Fe: → wrought iron, cast iron</div><ul class=\"examples\"><li><em>the iron and steel industry</em></li><li><em>a driveway with large iron gates</em></li><li><em>iron ore (=rock that contains iron)</em></li><li><em>the absorption of iron from food</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[for clothes]</strong> <span class=\"gram\">[countable]</span> a thing used for making clothes smooth, which has a heated flat metal base</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>have several irons in the fire</strong> to be involved in several different activities or have several plans all happening at the same time:</div><ul class=\"examples\"><li><em>He has several economic irons in the fire, including gold and diamond mines.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[sport]</strong> <span class=\"gram\">[countable]</span> a golf club made of metal rather than wood:</div><ul class=\"examples\"><li><em>a 5-iron</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[chains]</strong> <strong>irons</strong> <span class=\"gram\">[plural]</span> <em>especially literary</em> a chain used to prevent a prisoner from moving:</div><ul class=\"examples\"><li><em>leg irons</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to make clothes smooth using an iron <em>SYN press</em>:</div><ul class=\"examples\"><li><em>Have you ironed my shirt?</em></li></ul></div></div>","3818":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧ron‧ic</span><span class=\"meta-item\"><strong>IPA:</strong> /aɪˈrɒnɪk $ aɪˈrɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an ironic situation is one that is unusual or amusing because something strange happens, or the opposite of what is expected happens or is true:</div><ul class=\"examples\"><li><em>Your car was stolen at the police station! How ironic!</em></li><li><em>It’s ironic that her husband smoked for thirty years, and yet she’s the one who died of lung cancer.</em></li><li><em>In an ironic twist, the most trustworthy character in the film turned out to be the thief.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> using words that are the opposite of what you really mean, often in a joking way: → sarcastic</div><ul class=\"examples\"><li><em>ironic comments</em></li><li><em>When I told Lucy I loved her book, she thought I was being ironic.</em></li></ul></div>","3819":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧ron‧i‧cally</span><span class=\"meta-item\"><strong>IPA:</strong> /aɪˈrɒnɪkli $ aɪˈrɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[sentence adverb]</span> used when talking about a situation in which the opposite of what you expected happens or is true:</div><ul class=\"examples\"><li><em>Ironically, his cold got better on the last day of his holiday.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> in a way that shows you really mean the opposite of what you are saying:</div><ul class=\"examples\"><li><em>‘Oh, no problem!’ said Terry, ironically.</em></li></ul></div>","3820":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧ron‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈaɪərəni $ ˈaɪrə-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\">(plural ironies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a situation that is unusual or amusing because something strange happens, or the opposite of what is expected happens or is true:</div><ul class=\"examples\"><li><em>Life is full of little ironies.</em></li><li><strong><em>tragic/cruel/bitter etc irony</strong>: The tragic irony is that the drug was supposed to save lives.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> when you use words that are the opposite of what you really mean, often in order to be amusing ► see thesaurus at language → sarcasm, dramatic irony</div><ul class=\"examples\"><li><strong><em>trace/hint/touch of irony</strong>: Wagner calls his program ‘the worst talk show in America,’ without a hint of irony.</em></li><li><strong><em>heavy irony<em>British English</em></strong> (=a lot of irony): ‘Of course Michael won’t be late; you know how punctual he always is,’ she said with heavy irony.</em></li></ul></div>","3821":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ir‧ra‧tion‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪˈræʃənəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">not based on clear thought or reason <em>SYN unreasonable</em> <em>OPP rational</em> <em>, reasonable</em>:</div><ul class=\"examples\"><li><em>an irrational fear of flying</em></li><li><em>He’s becoming increasingly irrational.</em></li></ul></div>","3822":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ir‧reg‧u‧lar</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪˈreɡjələ $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> having a shape, surface, pattern etc that is not even, smooth, or balanced <em>SYN uneven</em> <em>OPP regular</em>:</div><ul class=\"examples\"><li><em>a jagged, irregular coastline</em></li><li><em>It has a highly irregular shape, covered in bumps and indentations.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> not happening at times that are an equal distance from each other <em>OPP regular</em>:</div><ul class=\"examples\"><li><em>He’s receiving medication for an irregular heartbeat.</em></li><li><em>Beamish only returned to Britain at irregular intervals.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> not happening or done at the normal time for doing something <em>OPP regular</em>:</div><ul class=\"examples\"><li><em>Funeral directors often work long, irregular hours.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>formal</em> not obeying the usually accepted legal or moral rules:</div><ul class=\"examples\"><li><em>It would be highly irregular (=extremely irregular) for a minister to accept payments of this kind.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>irregular verb/plural etc</strong> a verb or a form of a word that does not follow the usual pattern of grammar, such as the verb ‘catch’ or the plural ‘fish’ <em>OPP regular</em></div><div class=\"sense\"><span class=\"snum\">6</span> <em>American English</em> a word meaning constipated (=unable to easily pass food waste from your body), used in order to be polite</div></div>","3823":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ir‧rel‧e‧vant</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪˈreləvənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">not useful or not relating to a particular situation, and therefore not important <em>OPP relevant</em>:</div><ul class=\"examples\"><li><em>We’re focussing too much on irrelevant details.</em></li><li><em>Students viewed Latin as boring and irrelevant.</em></li><li><strong><em>largely/totally/completely etc irrelevant</strong>: His age is completely irrelevant if he can do the job.</em></li><li><strong><em>irrelevant to</strong>: The defendant’s lawyer argued that his past offenses were irrelevant to this case.</em></li></ul></div>","3824":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ir‧re‧sis‧ti‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪrɪˈzɪstəbəl◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> so attractive, desirable etc that you cannot prevent yourself from wanting it</div><ul class=\"examples\"><li><strong><em>irresistible to</strong>: Tax-cutting proposals could prove irresistible to lawmakers.</em></li><li><em>Men find Natalie irresistible.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> too strong or powerful to be stopped or prevented:</div><ul class=\"examples\"><li><em>I was overcome by an irresistible urge to cry.</em></li></ul></div>","3825":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ir‧re‧spon‧si‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌɪrɪˈspɒnsəbəl◂ $ -ˈspɑːn-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">doing careless things without thinking or worrying about the possible bad results <em>OPP responsible</em> ► see thesaurus at careless</div><ul class=\"examples\"><li><strong><em>totally/highly/completely etc irresponsible</strong>: When it comes to money, Dan is completely irresponsible.</em></li><li><strong><em>it is irresponsible (for somebody) to do something</strong>: It would be irresponsible not to turn up for work without calling. / It was highly irresponsible of him to leave the children on their own in the pool.</em></li></ul></div>","3826":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ir‧ri‧tate</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪrɪteɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to make someone feel annoyed or impatient, especially by doing something many times or for a long period of time:</div><ul class=\"examples\"><li><em>It really irritates me when he doesn’t help around the house.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make a part of your body painful and sore:</div><ul class=\"examples\"><li><em>This cream may irritate sensitive skin.</em></li></ul></div>","3827":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ir‧ri‧tat‧ed</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪrɪteɪtɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> feeling annoyed and impatient about something ► see thesaurus at angry</div><ul class=\"examples\"><li><strong><em>irritated about/at/with/by</strong>: John was getting irritated by all her questions.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> painful and sore:</div><ul class=\"examples\"><li><em>Her throat and eyes were irritated.</em></li></ul></div>","3828":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ir‧ri‧tat‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪrəteɪtɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">an irritating habit, situation etc keeps annoying you:</div><ul class=\"examples\"><li><em>He’s the most irritating man I’ve ever met.</em></li><li><em>He was smiling in a way I found very irritating.</em></li><li><strong><em>irritating habit/characteristics/mannerisms</strong>: She has an irritating habit of interrupting.</em></li><li><em>a dry irritating cough</em></li></ul></div>","3829":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> is‧land</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈaɪlənd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a piece of land completely surrounded by water → insular: → desert island</div><ul class=\"examples\"><li><em>The Cayman Islands</em></li><li><em>the Greek island of Crete</em></li><li><strong><em>on an island</strong>: No cars are allowed on the island.</em></li></ul></div>","3830":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧so‧late</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈaɪsəleɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to separate one person, group, or thing from other people or things:</div><ul class=\"examples\"><li><em>The town was isolated by the floods.</em></li><li><em>The US has sought to isolate Cuba both economically and politically.</em></li><li><strong><em>isolate somebody from somebody</strong>: Presley’s phenomenal early success isolated him from his friends.</em></li><li><strong><em>isolate somebody from something</strong>: Newborn babies must be isolated from possible contamination.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if you isolate an idea, problem etc, you consider it separately from other things that are connected with it</div><ul class=\"examples\"><li><strong><em>isolate something from something</strong>: It is impossible to isolate political responsibility from moral responsibility.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>technical</em> to separate a substance, disease etc from other substances so that it can be studied</div><ul class=\"examples\"><li><strong><em>isolate something from something</strong>: The hepatitis B virus has been isolated from breast milk.</em></li></ul></div>","3831":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧so‧lat‧ed</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈaɪsəleɪtɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an isolated building, village etc is far away from any others <em>SYN remote</em>:</div><ul class=\"examples\"><li><em>small isolated communities</em></li><li><em>Not many people visit this isolated spot.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> feeling alone and unable to meet or speak to other people: ► see thesaurus at far</div><ul class=\"examples\"><li><em>Young mothers often feel isolated.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> an isolated action, event, example etc happens only once, and is not likely to happen again</div><ul class=\"examples\"><li><strong><em>isolated incident/case/event</strong>: Police say that last week’s protest was an isolated incident.</em></li></ul></div>","3832":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧so‧la‧tion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌaɪsəˈleɪʃən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> when one group, person, or thing is separate from others:</div><ul class=\"examples\"><li><em>Because of its geographical isolation, the area developed its own unique culture.</em></li><li><strong><em>isolation of</strong>: the isolation of rural areas</em></li><li><strong><em>international/diplomatic/political isolation</strong>: the country’s continuing political isolation</em></li><li><strong><em>in isolation</strong>: The political prisoner had been held in complete isolation.</em></li><li><em>The mansion sits in splendid isolation on top of the hill (=it is far from everything and looks impressive).</em></li><li><strong><em>isolation hospital/ward<em>British English</em></strong>: Scarlet fever victims had to go to the isolation hospital.</em></li><li><em>a patient’s isolation period</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> when someone feels alone and unable to meet or speak to other people:</div><ul class=\"examples\"><li><em>Retirement can often cause feelings of isolation.</em></li><li><em>elderly people living in social isolation</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>in isolation (from something)</strong> if something exists or is considered in isolation, it exists or is considered separately from other things that are connected with it:</div><ul class=\"examples\"><li><em>The future of health care cannot be considered in isolation from economic factors.</em></li></ul></div>","3833":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> is‧sue</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪʃuː, ˈɪsjuː $ ˈɪʃuː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[subject/problem]</strong> <span class=\"gram\">[countable]</span> a subject or problem that is often discussed or argued about, especially a social or political matter that affects the interests of a lot of people:</div><ul class=\"examples\"><li><em>Abortion is a highly controversial issue.</em></li><li><em>We should raise the issue of discrimination with the council.</em></li><li><em>The key issue is whether workers should be classified as ‘employees’.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[magazine]</strong> <span class=\"gram\">[countable]</span> a magazine or newspaper printed for a particular day, week, or month</div><ul class=\"examples\"><li><strong><em>issue of</strong>: The article appeared in the January issue of ‘Nature’.</em></li><li><strong><em>the current/latest issue</strong>: Have you seen the latest issue?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>take issue with somebody/something</strong> to disagree or argue with someone about something:</div><ul class=\"examples\"><li><em>It is difficult to take issue with his analysis.</em></li><li><strong><em>take issue with somebody over something</strong>: I must take issue with you over what you said yesterday.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>make an issue (out) of something</strong> to argue about something, especially in a way that annoys other people because they do not think it is important:</div><ul class=\"examples\"><li><em>I was upset by Eleanor’s remarks, but didn’t make an issue of it.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>have issues (with somebody/something)</strong> <em>informal</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to have problems dealing with something because of something that happened in the past:</div><ul class=\"examples\"><li><em>There’s a self-help group for people who have issues with money.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if you have issues with someone or something, you do not agree with or approve of them:</div><ul class=\"examples\"><li><em>I have a few issues with Marc.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>at issue</strong> <em>formal</em> the problem or subject at issue is the most important part of what you are discussing or considering:</div><ul class=\"examples\"><li><em>At issue here is the extent to which exam results reflect a student’s ability.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[act of giving something]</strong> <span class=\"gram\">[singular]</span> the act of officially giving people something to use:</div><ul class=\"examples\"><li><em>the issue of identity cards to all non-residents</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[set of things for sale]</strong> <span class=\"gram\">[countable]</span> a new set of something such as shares or stamps, made available for people to buy:</div><ul class=\"examples\"><li><em>We launched the share issue on March 1.</em></li><li><em>a new issue of bonds</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>die without issue</strong> <em>old use</em> to die without having any children</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W2 AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to officially make a statement, give an order, warning etc:</div><ul class=\"examples\"><li><em>Silva issued a statement denying all knowledge of the affair.</em></li><li><em>a warning issued by the Surgeon General</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if an organization or someone in an official position issues something such as documents or equipment, they give these things to people who need them</div><ul class=\"examples\"><li><strong><em>issue a passport/permit/visa etc</strong>: The US State Department issues millions of passports each year.</em></li><li><strong><em>issue somebody with something</strong>: All the workers were issued with protective clothing.</em></li><li><strong><em>issue something to somebody</strong>: The policy document will be issued to all employees.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to officially produce something such as new stamps, coins, or shares and make them available to buy</div></div></div>","3834":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ˌaɪ ˈtiː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">(information technology) the study or use of electronic processes and equipment for storing information and making it available</div></div>","3835":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[used as subject or object]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to refer to a thing, animal, situation, idea etc that has already been mentioned or is already known about:</div><ul class=\"examples\"><li><em>‘Where’s your office?’ ‘It’s on the third floor.’</em></li><li><em>I love the spring – it’s a wonderful time of the year.</em></li><li><em>There were people crying, buildings on fire. It was terrible!</em></li><li><em>Don’t blame me. It wasn’t my idea.</em></li><li><em>This little beast is a lemur and it lives in Madagascar.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to refer to the situation that someone is in now, or what is happening now:</div><ul class=\"examples\"><li><em>I can’t stand it any longer. I’m resigning.</em></li><li><em>How’s it going, Bob? I haven’t seen you for ages.</em></li><li><em>And the worst of it is the car isn’t even paid for yet.</em></li><li><em>Stop it, you two. You’re just being silly.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used as the subject or object of a verb when the real subject or object is later in the sentence:</div><ul class=\"examples\"><li><em>It worries me the way he keeps changing his mind.</em></li><li><em>What’s it like being a sailor?</em></li><li><em>Apparently it’s cheaper to fly than to go by train.</em></li><li><em>It’s a pity you couldn’t come.</em></li><li><em>It seems that we are not welcome here.</em></li><li><em>I found it hard to concentrate.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> used as the subject of a sentence when you are talking about the weather, the time, a distance etc:</div><ul class=\"examples\"><li><em>Is it still raining?</em></li><li><em>It was 4 o&#x27;clock and the mail still hadn’t come.</em></li><li><em>It’s my birthday today.</em></li><li><em>It’s over 200 miles from London to Manchester.</em></li><li><em>It gets dark very early in the winter.</em></li><li><em>It’s three years since I last saw her.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> used with the verb ‘be’ to emphasize that you are talking about one particular thing, person, group etc and not any other:</div><ul class=\"examples\"><li><em>It’s Lawrence you should be talking to.</em></li><li><em>It was malaria that killed him.</em></li><li><em>It was in New Zealand that Elizabeth first met Mr Cronje.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> used to refer to a baby when you do not know what sex the baby is:</div><ul class=\"examples\"><li><em>What will you call it if it’s a boy?</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to say who a person is:</div><ul class=\"examples\"><li><em>‘Who’s that over there?’ ‘It’s Robert Morley.’</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>spoken</em> used to say who is speaking, especially on the telephone:</div><ul class=\"examples\"><li><em>Hello, it’s Frank here.</em></li><li><em>It’s all right, it’s only me.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <em>informal</em> used to refer to sex:</div><ul class=\"examples\"><li><em>Have you done it with him yet?</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>if it wasn’t/weren’t for somebody/something</strong> (also if it hadn’t been for somebody/something) used to say who or what prevents or prevented something from happening:</div><ul class=\"examples\"><li><em>We would have arrived much earlier if it hadn’t been for the snow.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <em>informal</em> a particular ability or quality that is needed in order to do something:</div><ul class=\"examples\"><li><em>In a job like advertising, you’ve either got it or you haven’t!</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>this is it</strong> <em>spoken</em> used to say that something you expected to happen is actually going to happen:</div><ul class=\"examples\"><li><em>This is it, boys – the moment we’ve been waiting for.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>that’s it</strong> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to say that something is completely finished or that a situation cannot be changed:</div><ul class=\"examples\"><li><em>That’s it, then. There’s nothing more we can do.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to tell someone that they are doing something correctly:</div><ul class=\"examples\"><li><em>Slowly... slowly. Yeah, that’s it.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> (also that does it) used when you are angry about a situation and you do not want it to continue:</div><ul class=\"examples\"><li><em>That’s it. I’m leaving.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>think you’re it</strong> <em>informal</em> to think you are more important than you are:</div><ul class=\"examples\"><li><em>Just because he got a higher mark, he really thinks he’s it.</em></li></ul></div>","3836":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ɪtʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> if part of your body or your clothes itch, you have an unpleasant feeling on your skin that makes you want to rub it with your nails → scratch:</div><ul class=\"examples\"><li><em>My feet were itching terribly.</em></li><li><em>The label on this shirt itches me.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be itching to do something/be itching for something</strong> <em>informal</em> to want to do something very much and as soon as possible:</div><ul class=\"examples\"><li><em>He was itching for a fight.</em></li></ul></div>","3837":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> itch‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈɪtʃi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\">(comparative itchier, superlative itchiest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if part of your body is itchy, it feels slightly unpleasant and you want to rub it with your nails:</div><ul class=\"examples\"><li><em>My eyes sometimes get red and itchy in the summer.</em></li><li><em>an itchy rash</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if clothes are itchy, they make your skin feel slightly unpleasant, so that you want to rub your skin with your nails <em>SYN scratchy</em>:</div><ul class=\"examples\"><li><em>These tights are all itchy.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> wanting to go somewhere new or do something different:</div><ul class=\"examples\"><li><em>He’s had that job now for about eight years, and he’s starting to get itchy.</em></li><li><em>I’ve only been back home for a few months and I’ve already got itchy feet (=the desire to go somewhere new).</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>itchy fingers</strong> <em>informal</em> someone with itchy fingers is likely to steal things:</div><ul class=\"examples\"><li><em>I tucked the bills deep into my pocket, away from itchy fingers.</em></li></ul></div>","3838":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧tem</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈaɪtəm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a single thing, especially one thing in a list, group, or set of things: ► see thesaurus at thing</div><ul class=\"examples\"><li><em>He opened the cardboard box and took out each item.</em></li><li><em>The store is having a sale on furniture and household items.</em></li><li><strong><em>item on the agenda/list/menu</strong>: We went on to the next item on the agenda.</em></li><li><strong><em>item of clothing/furniture/jewellery etc</strong> (=a single piece of clothing, furniture, jewellery etc)</em></li><li><em>luxury items such as exotic spices and perfumes</em></li><li><em>The original 1965 bottle is now a collector’s item (=one of a set of objects people like to collect because they are interesting or valuable).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a single, usually short, piece of news in a newspaper or magazine, or on television:</div><ul class=\"examples\"><li><em>I also saw that news item in the Sunday Times.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be an item</strong> <em>informal</em> if two people are an item, they are having a romantic or sexual relationship</div></div>","3839":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /ɪts/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[possessive form of ‘it’]</span></span></div><div class=\"entry-body\"><div class=\"sense\">used to refer to something that belongs to or is connected with a thing, animal, baby etc that has already been mentioned: ► Do not confuse with it&#x27;s (=‘it is’ or ‘it has’).</div><ul class=\"examples\"><li><em>Salzburg is famous for its beautiful buildings.</em></li><li><em>The hotel has its own pool.</em></li></ul></div>","3840":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> it‧self</span><span class=\"meta-item\"><strong>IPA:</strong> /ɪtˈself/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[reflexive form of ‘it’]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to show that a thing, organization, animal, or baby that does something is affected by its own action:</div><ul class=\"examples\"><li><em>The cat lay on the sofa, washing itself.</em></li><li><em>The machine switches itself off when the process is complete.</em></li><li><em>a small local enterprise that has transformed itself into a highly successful company</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to emphasize that you are talking about one particular thing, organization etc:</div><ul class=\"examples\"><li><em>We’ve checked the wiring, so the problem may be the television itself.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>in/of itself</strong> considered separately from any other facts:</div><ul class=\"examples\"><li><em>There is a slight infection in the lung, which in itself is not serious.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>(all) by itself</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> alone:</div><ul class=\"examples\"><li><em>Will the dog be safe left in the car by itself?</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> without help or without a person making it work:</div><ul class=\"examples\"><li><em>The door seemed to open all by itself.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>(all) to itself</strong> not shared with other things:</div><ul class=\"examples\"><li><em>This idea deserves a chapter to itself.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>be patience/kindness/simplicity etc itself</strong> to be very patient, kind, simple etc:</div><ul class=\"examples\"><li><em>Loading the software is simplicity itself.</em></li></ul></div>","3841":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> i‧vo‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈaɪvəri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\">(plural ivories)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the hard smooth yellowish-white substance from the tusks (=long teeth) of an elephant:</div><ul class=\"examples\"><li><em>an ivory chess set</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> a yellowish-white colour:</div><ul class=\"examples\"><li><em>an ivory silk wedding gown</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable often plural]</span> something made of ivory, especially a small figure of a person or animal:</div><ul class=\"examples\"><li><em>a collection of ivories</em></li></ul></div>"};